window.__Q=window.__Q||{};window.__Q["tcm/4/A1"]=[{"q":"具有“辛凉透表，清热解毒”功用的方剂是","o":["桑菊饮","香薷散","败毒散","银翘散","黄连解毒汤"],"a":3,"e":"银翘散功用辛凉透表、清热解毒，为“辛凉平剂”，主治温病初起邪在卫分。桑菊饮为辛凉轻剂，功在疏风清热、宣肺止咳，二者层次有别。"},{"q":"阿胶鸡子黄汤证的病机是","o":["温病迁延日久，邪热灼伤真阴","温热病邪传入厥阴，肝经热盛，热极动风","肝肾阴虚，肝阳偏亢，阳亢化风，气血逆乱","肝肾不足，肝阳偏亢，生风化热","邪热久羁，耗伤阴血，虚风内动"],"a":4,"e":"阿胶鸡子黄汤主治邪热久羁、灼伤阴血、筋脉失养之虚风内动证，属阴虚风动。大定风珠证为温病迁延日久、邪热灼伤真阴，二者轻重不同。"},{"q":"橘皮竹茹汤组成中有","o":["黄芪","人参、生姜","白术","枳壳","半夏"],"a":1,"e":"橘皮竹茹汤由橘皮、竹茹、人参、生姜、大枣、甘草组成，人参、生姜益气补中以复胃气。全方降逆止呕、益气清热，不用半夏、枳壳、黄芪、白术。"},{"q":"下列各项，其中哪项不是定喘汤药物","o":["白果、麻黄","苏子、款冬花","杏仁、桑皮","黄芩、半夏","陈皮、茯苓"],"a":4,"e":"定喘汤由白果、麻黄、苏子、款冬花、杏仁、桑白皮、黄芩、半夏、甘草组成，宣肺降气、清热化痰。陈皮、茯苓为二陈汤之品，非本方所有。"},{"q":"下列不属于金锁固精丸组成的是","o":["莲子","沙苑蒺藜","龟甲","芡实","龙骨"],"a":2,"e":"金锁固精丸由沙苑蒺藜、芡实、莲须、莲子、龙骨、牡蛎组成，功在补肾涩精。龟甲滋阴潜阳，见于大定风珠、三甲复脉汤，不属本方。"},{"q":"木香槟榔丸主治","o":["痢疾、食积","脾虚食积","食积证","湿热食积","酒积伤脾"],"a":0,"e":"木香槟榔丸行气导滞、攻积泄热，主治积滞内停、湿蕴生热之痢疾与食积，见脘腹痞满胀痛、赤白痢疾、里急后重。枳实导滞丸则主湿热食积。"},{"q":"以大便秘结，小便频数，舌质红，苔薄黄，脉数为辨证要点的方剂是","o":["济川煎","肾气丸","黄龙汤","十枣汤","麻子仁丸"],"a":4,"e":"麻子仁丸润肠泄热、行气通便，主治胃肠燥热、脾约便秘，以大便干结、小便频数、苔薄黄、脉数为要点。小便频数正是脾约津液偏渗膀胱之征。"},{"q":"大承气汤中，用以行气消除胀满的药物是","o":["大黄","芒硝","枳实","厚朴","甘遂"],"a":3,"e":"大承气汤中厚朴行气除满，枳实破气消痞，二者相配以除痞满胀实。大黄泻热通便，芒硝软坚润燥，四药共成峻下热结之功。"},{"q":"清燥救肺汤的功用是","o":["清热燥湿，调和气血","清宣温燥，润肺止咳","轻宣凉燥，理肺化痰","清养肺胃，降逆下气","清燥润肺，养阴益气"],"a":4,"e":"清燥救肺汤清燥润肺、养阴益气，主治温燥伤肺重证，见身热头痛、干咳无痰、气逆而喘、咽干鼻燥。桑杏汤轻宣温燥，杏苏散轻宣凉燥。"},{"q":"有关君药的认识，不确切的是","o":["药力居方中之首","用量较作为臣、佐药应用时大","能引方中诸药以达病所","针对主证或主病起主要治疗作用","君药在方中是首要的"],"a":2,"e":"君药针对主病或主证起主要治疗作用，药力居方中之首，用量多较其为臣、佐药时大。“引方中诸药以达病所”是使药的功用，非君药特征。"},{"q":"属于固涩剂适应范围的病证是","o":["血热崩漏","肺虚久咳","火动遗精","伤食泄泻","热病多汗"],"a":1,"e":"固涩剂用于气血精津耗散滑脱之证，如自汗盗汗、肺虚久咳、遗精滑泄、久泻久痢。血热崩漏、火动遗精、伤食泄泻、热病多汗皆属邪实，误用固涩则闭门留寇。"},{"q":"症见脘腹胀满，舌苔白厚腻者，治宜","o":["燥湿运脾，和胃止呕","燥湿运脾，行气和胃","燥湿运脾，行气导滞","解表化湿，行气和胃","解表化湿，行气利水"],"a":1,"e":"脘腹胀满、舌苔白厚腻为湿滞脾胃之征，治宜燥湿运脾、行气和胃，方用平胃散。苍术燥湿运脾为君，厚朴行气除满，陈皮理气和胃。"},{"q":"大承气汤与大柴胡汤共用的药物是","o":["大黄、芒硝","大黄、厚朴","大黄、枳实","大黄、炙甘草","枳实、厚朴"],"a":2,"e":"大承气汤由大黄、芒硝、枳实、厚朴组成；大柴胡汤含柴胡、黄芩、半夏、芍药、枳实、大黄、生姜、大枣，两方共有大黄与枳实，芒硝仅属大承气汤。"},{"q":"四君子汤的功用为","o":["益气养阴","健脾养胃","补益肝脾","益气健脾","益气补血"],"a":3,"e":"四君子汤由人参、白术、茯苓、炙甘草组成，益气健脾，为治脾胃气虚证的基础方，见食少便溏、气短乏力、面色萎白、舌淡脉虚。"},{"q":"消风散证的致病因素是","o":["风寒","风热","风湿","风寒湿","风湿热"],"a":4,"e":"消风散主治风疹、湿疹，证由风毒湿热搏结肌肤、浸淫血脉而成，故以疏风养血、清热除湿为法。方中当归、生地凉血养血，取治风先治血之义。"},{"q":"温里剂组方中，最常与温里药配伍的是","o":["滋阴药","解表药","活血药","补气药","固涩药"],"a":3,"e":"温里剂主治里寒证，寒邪易伤阳气，故组方最常配伍补气药，温补相合以扶助阳气，如理中丸以干姜配人参、白术。亦可酌配行气、活血之品。"},{"q":"五积散的功用是","o":["发表清里，顺气化痰，活血消积","发表温里，顺气化痰，活血消积","解表散寒，顺气化痰，消食化积","解表散寒，温肺化饮，消食化积","清热泻火，顺气化痰，消食化积"],"a":1,"e":"五积散主治外感风寒、内伤生冷之寒、湿、气、血、痰五积，发表温里、顺气化痰、活血消积，属表里双解之剂，见发热无汗、头痛身疼、胸满恶食。"},{"q":"定喘汤的组成中不含有","o":["款冬花、桑白皮","苏子、半夏","桑叶、生石膏","白果、甘草","杏仁、黄芩"],"a":2,"e":"定喘汤由白果、麻黄、苏子、款冬花、杏仁、桑白皮、黄芩、半夏、甘草组成，宣肺降气、清热化痰。桑叶、生石膏为桑菊饮、麻杏石甘汤之品。"},{"q":"主治证病机为“素体阳气虚弱，复感风寒”的方剂是","o":["败毒散","参苏饮","麻黄附子细辛汤","再造散","加减葳蕤汤"],"a":3,"e":"再造散助阳益气、解表散寒，主治阳气虚弱、外感风寒证，见恶寒发热、无汗肢冷、面色苍白、脉沉无力。麻黄附子细辛汤虽治阳虚外感，但无助阳益气之功。"},{"q":"桑螵蛸散的主治证是","o":["心脾两虚证","心肾两虚证","脾肾两虚证","肝肾两虚证","肺肾两虚证"],"a":1,"e":"桑螵蛸散调补心肾、涩精止遗，主治心肾两虚之尿频、遗尿、遗精，兼心神恍惚、健忘。方中桑螵蛸补肾涩精为君，龙骨、龟甲、人参、茯神交通心肾。"},{"q":"龟鹿二仙胶的功用中包括","o":["滋阴降火","填精补血","涩精止遗","益气壮阳","养肝敛阴"],"a":3,"e":"龟鹿二仙胶由鹿角胶、龟板胶、人参、枸杞子组成，滋阴填精、益气壮阳，主治真元虚损、精血不足之证。龟板胶滋阴，鹿角胶补阳，阴阳气血并补。"},{"q":"原方用法要求药后“饮粥二升”并“一日食糜粥”的是","o":["吴茱萸汤","小建中汤","大建中汤","小柴胡汤","大承气汤"],"a":2,"e":"大建中汤温中补虚、缓急止痛，方后注要求服后饮粥二升，并一日食糜粥，以温养中气、助药力建中。此为建中类方特有的服药调护法。"},{"q":"下列方剂中，哪一项与滋养肺阴无关","o":["增液汤","百合固金汤","麦门冬汤","琼玉膏","清燥救肺汤"],"a":0,"e":"增液汤由玄参、麦冬、生地组成，增液润燥、润肠通便，主治温病津亏便秘，滋养的是胃肠之阴。百合固金汤、麦门冬汤、琼玉膏、清燥救肺汤均滋养肺阴。"},{"q":"三仁汤中的“三仁”是","o":["杏仁、火麻仁、薏苡仁","杏仁、郁李仁、薏苡仁","杏仁、桃仁、薏苡仁","杏仁、砂仁、薏苡仁","杏仁、白蔻仁、薏苡仁"],"a":4,"e":"三仁汤中杏仁宣利上焦肺气，白蔻仁畅中焦脾胃，薏苡仁渗利下焦湿邪，三仁分宣三焦。全方宣畅气机、清利湿热，主治湿温初起、湿重于热。"},{"q":"主治肠痈初起的方剂是","o":["内补黄芪汤","五味消毒饮","大黄牡丹汤","苇茎汤","阳和汤"],"a":2,"e":"大黄牡丹汤泻热破瘀、散结消肿，主治肠痈初起、湿热瘀滞证，见右下腹疼痛拒按、右足屈而不伸、小便自调。苇茎汤则主治肺痈。"},{"q":"具有降逆化痰、益气和胃功效的方剂是","o":["橘皮竹茹汤","旋覆代赭汤","半夏泻心汤","半夏厚朴汤","厚朴温中汤"],"a":1,"e":"旋覆代赭汤由旋覆花、代赭石、半夏、生姜、人参、大枣、甘草组成，降逆化痰、益气和胃，主治胃虚痰阻气逆之心下痞硬、噫气不除。"},{"q":"仙方活命饮的适应证是","o":["火毒结聚之疔疮","痈疡肿毒初起","热毒炽盛之脱疽","阳虚寒凝之阴疽","风火痰热之痈疮"],"a":1,"e":"仙方活命饮清热解毒、消肿溃坚、活血止痛，主治阳证痈疡肿毒初起，见红肿焮痛、身热凛寒、苔薄白或黄、脉数有力。金银花为君以清热解毒。"},{"q":"定喘汤与小青龙汤共有的药物是","o":["苏子、白果","麻黄、半夏","杏仁、冬花","桑白皮、黄芩","细辛、干姜"],"a":1,"e":"定喘汤与小青龙汤均含麻黄、半夏，麻黄宣肺平喘，半夏燥湿化痰。定喘汤配黄芩、桑白皮清肺热，小青龙则用桂枝、细辛、干姜温化寒饮。"},{"q":"治痰剂中常配伍的药物是","o":["祛湿药","补气药","清热药","收涩药","温里药"],"a":0,"e":"痰由湿生，治痰剂常配伍祛湿健脾之品，使湿去脾健则痰无由生，即“治痰必治脾”之义。二陈汤用半夏、茯苓燥湿健脾即属此例。"},{"q":"养阴清肺汤与百合固金汤两方均含有的药物是","o":["生地、玄参","贝母、薄荷","当归、白芍","桔梗、丹皮","熟地、甘草"],"a":0,"e":"养阴清肺汤与百合固金汤均用生地、玄参滋阴清热，故为两方共有。养阴清肺汤另有薄荷宣肺利咽，百合固金汤则用熟地、当归、桔梗润肺化痰。"},{"q":"以滋肾阴、补肾阳、开窍化痰为功用的方剂是","o":["左归丸","左归饮","右归丸","右归饮","地黄饮子"],"a":4,"e":"地黄饮子滋肾阴、补肾阳、开窍化痰，主治下元虚衰、痰浊上泛之喑痱，见舌强不能言、足废不能用。熟地、山茱萸滋肾，苁蓉、巴戟天补阳。"},{"q":"《医方考》中“泻责之脾，痛责之肝；肝责之实、脾责之虚。脾虚肝郁，故令痛泻”是对哪首方剂主治病机的描述","o":["四逆散","痛泻要方","半夏泻心汤","芍药汤","四神丸"],"a":1,"e":"痛泻要方补脾柔肝、祛湿止泻，主治脾虚肝旺之痛泻，见肠鸣腹痛、大便泄泻、泻后痛减。泻责之脾、痛责之肝，正是其病机概括。"},{"q":"胃虚、痰阻、气逆之心下痞硬、呕呃之证，宜用","o":["半夏厚朴汤","厚朴温中汤","半夏泻心汤","橘皮竹茹汤","旋覆代赭汤"],"a":4,"e":"旋覆代赭汤降逆化痰、益气和胃，主治胃气虚弱、痰浊内阻、气逆不降之心下痞硬、噫气不除、呕恶。半夏泻心汤主治寒热错杂之痞证，以痞满下利为主。"},{"q":"半夏泻心汤与小柴胡汤两方组成中均含有的药物是","o":["人参、黄芩、半夏、干姜","人参、生姜、半夏、大枣","半夏、黄芩、人参、大枣","柴胡、黄芩、人参、生姜","半夏、黄连、黄芩、大枣"],"a":2,"e":"半夏泻心汤由半夏、黄芩、黄连、干姜、人参、大枣、甘草组成，小柴胡汤由柴胡、黄芩、半夏、人参、生姜、大枣、甘草组成，两方共有半夏、黄芩、人参、大枣。"},{"q":"以下关于镇肝熄风汤证的辨证要点描述错误的是","o":["头目眩晕","脑部胀痛","面色如醉","心中烦热","脉弦数"],"a":4,"e":"镇肝熄风汤主治肝阳上亢、气血逆乱之类中风，辨证要点为头目眩晕、脑部胀痛、面色如醉、心中烦热、脉弦长有力。脉弦数为肝经热盛之象。"},{"q":"蒿芩清胆汤证之“小便黄少”病机为何","o":["湿阻三焦","内热煎熬","寒湿不化","瘀血内停","阴阳两虚"],"a":0,"e":"蒿芩清胆汤证为湿遏热郁、阻于少阳胆与三焦，三焦水道不利、湿无出路，故小便黄少。方中碧玉散、赤茯苓、通草正可清利湿热、通利三焦。"},{"q":"下列哪一项不是理中丸的用法","o":["日三服，夜二服","腹中未热 ，益至三四丸","服汤后，饮冷开水一升","微自温，勿发揭衣被","服汤后，饮热粥一升许"],"a":2,"e":"理中丸方后注要求服汤后如食顷饮热粥一升许，微自温、勿发揭衣被，以助温养中焦；日三服夜二服，腹中未热可益至三四丸。饮冷开水与温中之意相悖。"},{"q":"四神丸的功用是","o":["疏肝和胃，固肠止泻","健脾益气，固肠止泻","温肾暖脾，固肠止泻","益胃暖脾，固肠止泻","温中散寒，固肠止泻"],"a":2,"e":"四神丸由肉豆蔻、补骨脂、五味子、吴茱萸组成，温肾暖脾、固肠止泻，主治脾肾阳虚之五更泄泻，见黎明前脐腹作痛、肠鸣即泻、泻后则安。"},{"q":"贝母瓜蒌散主治证是","o":["湿痰咳嗽","热痰咳嗽","燥痰咳嗽","寒痰咳嗽","风痰眩晕"],"a":2,"e":"贝母瓜蒌散润肺清热、理气化痰，主治燥痰咳嗽，见咳痰少而黏、涩而难出、咽干口燥、苔白而干。二陈汤治湿痰，清气化痰丸治热痰。"},{"q":"最有可能在服法中使用反佐法的是","o":["四逆散","四逆汤","当归四逆汤","桂枝汤","小建中汤"],"a":1,"e":"四逆汤主治心肾阳衰寒厥证，若阴盛格阳、药入即吐，可热药冷服，取“治寒以热，凉而行之”的反佐之意。四逆散、当归四逆汤无此服法。"},{"q":"药物配伍具有“分经论治”特点的方剂是","o":["小柴胡汤","败毒散","桂枝汤","小青龙汤","九味羌活汤"],"a":4,"e":"九味羌活汤中羌活入太阳、细辛入少阴、白芷入阳明、川芎入少阳厥阴，分经论治，主治外感风寒湿邪兼内有蕴热证，见恶寒发热、无汗头痛而渴。"},{"q":"下列哪项不是桑杏汤的辨证要点","o":["身热不甚","咽干鼻燥","干咳无痰","气逆而喘","舌红"],"a":3,"e":"桑杏汤清宣温燥、润肺止咳，主治外感温燥轻证，辨证要点为身热不甚、干咳无痰、咽干鼻燥、舌红苔薄白而干。气逆而喘属燥热伤肺重证。"},{"q":"蒿芩清胆汤与八正散组成中共有的药物是","o":["枳实、大黄","黄芩、木通","半夏、栀子","滑石、甘草","青蒿、车前子"],"a":3,"e":"蒿芩清胆汤含碧玉散，即滑石、甘草、青黛；八正散亦用滑石、甘草，故两方共有滑石与甘草。黄芩、木通、栀子分属两方，并非共有。"},{"q":"体现“芳香清透以畅少阳之枢机，苦燥降利以化湿郁之痰浊”配伍特点的方剂是","o":["半夏泻心汤","茵陈蒿汤","蒿芩清胆汤","小柴胡汤","大柴胡汤"],"a":2,"e":"蒿芩清胆汤以青蒿、黄芩为君，芳香清透以畅少阳枢机；配半夏、陈皮、枳壳、竹茹苦燥降利，化湿郁之痰浊，为治少阳湿热痰浊之代表方。"},{"q":"小柴胡汤中配伍生姜的意义是","o":["和胃止呕","发汗解表","温中散寒","解表利水","疏泄少阳"],"a":0,"e":"小柴胡汤中生姜配半夏和胃降逆止呕，并助柴胡透达少阳之邪。柴胡疏透、黄芩清泄，参枣草益气扶正，生姜则专主和胃止呕。"},{"q":"被称为“辛凉轻剂”的方剂是","o":["桑菊饮","香薷散","银翘散","香苏散","葱豉桔梗汤"],"a":0,"e":"桑菊饮药力轻清，称“辛凉轻剂”，主治风温初起、表热轻证，以但咳、身热不甚、口微渴为特点。银翘散为辛凉平剂，白虎汤为辛凉重剂。"},{"q":"四磨汤的功效是","o":["宣肺降气，清热化痰","行气降逆，宽胸散结","化痰散引，和胃降逆","降逆止呃，益气清热","降逆化痰，益气和胃"],"a":1,"e":"四磨汤由人参、槟榔、沉香、乌药组成，行气降逆、宽胸散结，主治七情所伤、肝气郁结之胸膈烦闷、上气喘急。五磨饮子则去人参，加木香、枳实。"},{"q":"下列属于蒿芩清胆汤组成的药物是","o":["柴胡","黄连","白芍","茵陈","滑石"],"a":4,"e":"蒿芩清胆汤由青蒿、黄芩、竹茹、半夏、枳壳、陈皮、赤茯苓、碧玉散组成，碧玉散含滑石、甘草、青黛。方中不用柴胡、黄连、白芍、茵陈。"},{"q":"《医便》中的五磨饮子是在四磨汤的基础上去掉人参，增加了什么药","o":["半夏、生姜","枳实、厚朴","旋覆花、代赭石","苏子、半夏","木香、枳实"],"a":4,"e":"五磨饮子由四磨汤去人参，加木香、枳实而成，行气降逆之力更峻，主治大怒暴厥、气闭不通。去人参者，恐其补气留邪，有碍行气开郁。"},{"q":"下列不属于一贯煎组成药物的是","o":["当归身","北沙参","生地黄","川楝子","熟地黄"],"a":4,"e":"一贯煎由北沙参、麦冬、当归身、生地黄、枸杞子、川楝子组成，滋阴疏肝，主治肝肾阴虚、肝气郁滞证。方用生地黄而非熟地黄，熟地滋腻碍于疏泄。"},{"q":"具有涌吐痰涎宿食功用的方剂是","o":["安宫牛黄丸","瓜蒂散","保和丸","清气化痰丸","滚痰丸"],"a":1,"e":"瓜蒂散涌吐痰涎宿食，主治痰涎宿食壅滞胸脘证，见胸中痞硬、懊憹不安、欲吐不出、寸脉微浮。瓜蒂为君，赤小豆为臣，香豉安中护胃。"},{"q":"丁香柿蒂汤主治","o":["外寒里饮之咳喘","上实下虚之痰喘","胃虚有热之呃逆","胃气虚寒之呃逆","肝经气滞寒凝证"],"a":3,"e":"丁香柿蒂汤温中益气、降逆止呃，主治胃气虚寒之呃逆，见呃逆不已、胸痞脘闷、舌淡苔白、脉沉迟。橘皮竹茹汤则治胃虚有热之呃逆。"},{"q":"川芎茶调散的主治证是","o":["风寒头痛","风热头痛","风湿头痛","风邪头痛","风痰头痛"],"a":3,"e":"川芎茶调散疏风止痛，主治外感风邪头痛，风寒、风热均可加减。方中川芎善治少阳、厥阴头痛，为诸经头痛之要药，配清茶调服则上清头目。"},{"q":"下列方剂中，可以主治黄疸而见少阳证的是","o":["大柴胡汤","茵陈蒿汤","小柴胡汤","半夏厚朴汤","当归四逆汤"],"a":2,"e":"小柴胡汤和解少阳，兼能疏利肝胆、调畅气机，故可治黄疸而见寒热往来、胸胁苦满、口苦咽干之少阳证。茵陈蒿汤主治湿热黄疸而无少阳见症。"},{"q":"羌活胜湿汤证主治","o":["风寒湿痹","风湿热痹","顽痹","风湿犯表之痹证","外感风寒湿、里有蕴热证"],"a":3,"e":"羌活胜湿汤祛风胜湿止痛，主治风湿犯表之痹证，见肩背痛不可回顾、头痛身重、腰脊重痛、苔白脉浮。羌活、独活共祛一身之风湿。"},{"q":"药物组成中不含有干姜的方剂","o":["四逆汤","吴茱萸汤","理中丸","回阳救急汤","半夏泻心汤"],"a":1,"e":"吴茱萸汤由吴茱萸、人参、生姜、大枣组成，用生姜而不用干姜。四逆汤、理中丸、回阳救急汤、半夏泻心汤四方组成中均含干姜。"},{"q":"温燥伤肺轻证，治疗应首选的方剂是","o":["养阴清肺汤","清燥救肺汤","增液汤","桑杏汤","杏苏散"],"a":3,"e":"温燥伤肺轻证治宜清宣温燥、润肺止咳，首选桑杏汤，见身热不甚、干咳无痰、咽干鼻燥。清燥救肺汤则治温燥伤肺重证，见气逆而喘、胸满胁痛。"},{"q":"养心汤中君药是","o":["黄芪、人参","人参、当归","酸枣仁、黄连","人参、五味子","黄芪、远志"],"a":0,"e":"养心汤益气补血、养心安神，方中黄芪、人参为君，大补心脾之气以生血养心。当归、川芎养血，茯苓、茯神、远志、酸枣仁宁心安神。"},{"q":"以下关于阿胶鸡子黄汤的组成，表述错误的是","o":["钩藤、石决明","络石藤、茯神木","牡蛎、阿胶","鸡子黄、炙甘草","熟地、白芍"],"a":4,"e":"阿胶鸡子黄汤由阿胶、鸡子黄、白芍、生地黄、麦冬、牡蛎、石决明、钩藤、络石藤、茯神木、甘草组成，用生地黄滋阴凉血。熟地黄非本方所有。"},{"q":"二陈汤主治","o":["风寒咳嗽","热痰咳嗽","燥痰咳嗽","湿痰咳嗽","寒饮咳嗽"],"a":3,"e":"二陈汤燥湿化痰、理气和中，主治湿痰证，见咳嗽痰多色白易咯、胸膈痞闷、恶心呕吐、肢体困重、苔白腻、脉滑。半夏燥湿化痰为君。"},{"q":"体现“以泻代清”治法的方剂是","o":["凉膈散","泻白散","清胃散","导赤散","泻黄散"],"a":0,"e":"凉膈散泻火通便、清上泄下，主治上中二焦火热证。方中重用连翘，配大黄、芒硝通便泄热，使胸膈郁热从下而去，体现“以泻代清”之法。"},{"q":"健脾丸的君药是","o":["人参、山药、白术","人参、白术、茯苓","白术、茯苓、山药","人参、白术、茯苓、甘草","茯苓、人参、甘草、山药"],"a":1,"e":"健脾丸健脾和胃、消食止泻，方中人参、白术、茯苓益气健脾为君，山楂、神曲、麦芽消食化积，木香、砂仁、陈皮理气运脾。"},{"q":"具有滋阴润肺，益气补脾作用的方剂是","o":["生脉散","增液汤","琼玉膏","玉液汤","麦门冬汤"],"a":2,"e":"琼玉膏由生地黄、人参、白茯苓、白蜜熬膏，滋阴润肺、益气补脾，主治肺阴亏损之虚劳干咳、咽燥咯血、肌肉消瘦、气短乏力。"},{"q":"清营汤中具有透热转气作用的药物是","o":["金银花、连翘","水牛角、黄连","牡丹皮、丹参","麦门冬、玄参","生地黄、竹叶"],"a":0,"e":"清营汤中金银花、连翘清热解毒、轻清透泄，使营分之热转出气分而解，即“透热转气”之法。水牛角、黄连则专于清营凉血。"},{"q":"枳实导滞丸主治","o":["湿热食积","脾虚食积","食积证","酒积伤脾","痢疾，食积"],"a":0,"e":"枳实导滞丸消导化积、清热祛湿，主治湿热食积证，见脘腹胀痛、下痢泄泻、小便短赤、苔黄腻、脉沉有力。木香槟榔丸则主痢疾、食积。"},{"q":"左归丸中配伍鹿角胶的作用是","o":["滋阴","补阳","阳中求阴","阴中求阳","阴阳并补"],"a":2,"e":"左归丸滋阴补肾、填精益髓，方中纯补无泻，于大队滋阴药中配鹿角胶温补阳气，取“阳中求阴”之义，使阴得阳升而源泉不竭。"},{"q":"温经汤主治证的病机是","o":["脾气亏虚，冲脉不固","肝肾两虚，冲脉不固","冲任虚寒，瘀血阻滞","冲任虚损，瘀血阻滞","寒凝血瘀，湿阻胞宫"],"a":2,"e":"温经汤温经散寒、养血祛瘀，主治冲任虚寒、瘀血阻滞之月经不调、痛经、久不受孕，见少腹冷痛、经血淋漓不畅、傍晚手足心热。"},{"q":"小建中汤组成中用量为六两的药物是","o":["桂枝","生姜","大枣","芍药","饴糖"],"a":3,"e":"小建中汤由桂枝三两、芍药六两、炙甘草二两、生姜三两、大枣十二枚、饴糖一升组成，芍药倍用为六两，与桂枝相配以调和营卫、缓急止痛。"},{"q":"大秦艽汤与消风散配伍中体现“治风先治血，血行风自灭”之理的药物是","o":["生地","当归","白芍","熟地","川芎"],"a":1,"e":"消风散与大秦艽汤均用当归养血活血，取“治风先治血，血行风自灭”之义，使血脉通利则风邪自散。消风散中当归与生地、胡麻仁共养阴血。"},{"q":"桑螵蛸散的功用是","o":["温补肾阳，涩精止遗","温肾祛寒，缩尿止遗","固冲摄血，益气健脾","涩肠固脱，温补脾肾","调补心肾，涩精止遗"],"a":4,"e":"桑螵蛸散调补心肾、涩精止遗，主治心肾两虚之尿频、遗尿、遗精，兼心神恍惚、健忘。桑螵蛸补肾涩精，龙骨、龟甲、人参、茯神交通心肾。"},{"q":"理气化痰，清胆和胃为哪首方剂的功用","o":["清气化痰丸","贝母瓜蒌散","温胆汤","二陈汤","茯苓丸"],"a":2,"e":"温胆汤理气化痰、清胆和胃，主治胆胃不和、痰热内扰之虚烦不眠、呕吐呃逆、惊悸不宁。竹茹清热化痰，枳实、陈皮理气，半夏燥湿化痰。"},{"q":"朱砂安神丸服用方法为","o":["作汤剂，朱砂也入药一起煎煮","作丸剂，久服","作丸剂，多服","临睡前温开水送服","没有禁忌"],"a":3,"e":"朱砂安神丸镇心安神、清热养血，用法为丸剂临睡前温开水送服。朱砂主含硫化汞，有毒，不可多服久服，亦不宜入汤剂煎煮。"},{"q":"六味地黄丸中的君药是","o":["山萸肉","山药","熟地黄","茯苓","牡丹皮"],"a":2,"e":"六味地黄丸中熟地黄重用为君，滋阴补肾、填精益髓；山茱萸养肝涩精，山药补脾固精，为“三补”；泽泻、牡丹皮、茯苓为“三泻”。"},{"q":"逍遥散中配伍生姜的意义是","o":["温中散寒，健脾和中","辛温解表，散寒除湿","降逆和中，辛散达郁","温肺化饮，散寒止咳","补脾和胃，化气生津"],"a":2,"e":"逍遥散中烧生姜温胃和中、降逆止呕，兼辛散以助肝气条达，故能降逆和中、辛散达郁。薄荷少许亦助疏散郁遏之气。"},{"q":"清胃散的功用是","o":["清胃泻火","清胃滋阴","清胃养血","清胃凉血","清泻胃热"],"a":3,"e":"清胃散清胃凉血，主治胃火牙痛，见牙痛牵引头痛、面颊发热、齿龈红肿溃烂、口气热臭、舌红苔黄、脉滑数。黄连清胃泻火为君。"},{"q":"不属于青蒿鳖甲汤主治证候的是","o":["脉细数","舌红少苔","热退无汗","夜热早凉","身热夜甚"],"a":4,"e":"青蒿鳖甲汤养阴透热，主治温病后期邪伏阴分之夜热早凉、热退无汗、舌红少苔、脉细数。身热夜甚为热入营血之征，属清营汤证。"},{"q":"肉桂在真人养脏汤中的作用是","o":["温经散寒","温肾纳气","温通经脉","温阳化气","温肾暖脾"],"a":4,"e":"真人养脏汤涩肠固脱、温补脾肾，方中肉桂温肾暖脾、助阳散寒，与肉豆蔻、罂粟壳相合以固肠止泻。人参、白术、甘草益气健脾。"},{"q":"原书服法要求“香气大出，即取服，勿过煮”的方剂是","o":["桑菊饮","香薷散","银翘散","香苏散","葱豉桔梗汤"],"a":2,"e":"银翘散方后注要求“香气大出，即取服，勿过煮”，因金银花、荆芥穗、薄荷等辛散轻清，久煎则挥发性成分散失，药力大减。"},{"q":"黄龙汤与温脾汤共有的药物是","o":["大黄、芒硝","枳实、芍药","干姜、人参","当归、升麻","厚朴、甘草"],"a":0,"e":"黄龙汤由大黄、芒硝、枳实、厚朴、人参、当归、甘草、桔梗、生姜、大枣组成，温脾汤由大黄、芒硝、附子、干姜、人参、当归、甘草组成，两方共有大黄、芒硝。"},{"q":"小蓟饮子与导赤散共有的药物是","o":["生地、木通","当归、山栀子","滑石、甘草","小蓟、藕节","竹叶、车前子"],"a":0,"e":"小蓟饮子凉血止血、利水通淋，导赤散清心利水养阴，两方均用生地黄凉血滋阴、木通利水通淋，共治心与小肠之热。竹叶、甘草亦为两方共有。"},{"q":"不属于竹叶石膏汤组成药物的是","o":["半夏","人参","炙甘草","天门冬","麦门冬"],"a":3,"e":"竹叶石膏汤由竹叶、石膏、半夏、麦门冬、人参、炙甘草、粳米组成，清热生津、益气和胃。方用麦门冬而非天门冬，天门冬偏于滋阴润燥。"},{"q":"参苓白术散证的病机是","o":["阳虚水泛","脾胃气虚","寒湿困脾","肺肾气虚","脾胃气虚，湿自内生"],"a":4,"e":"参苓白术散益气健脾、渗湿止泻，证属脾胃气虚、湿自内生，见饮食不化、大便稀溏、四肢乏力、形体消瘦、胸脘闷胀、苔白腻、脉虚缓。"},{"q":"用于气虚发热，体现甘温除热法的方剂是","o":["补中益气汤","参苓白术散","人参蛤蚧散","生脉散","四君子汤"],"a":0,"e":"补中益气汤补中益气、升阳举陷，重用黄芪为君，配人参、白术、甘草甘温补中，升麻、柴胡升举清阳，使阳气复位而热自退，即甘温除热法。"},{"q":"消食剂中用药体现“通因通用”的代表方剂是","o":["保和丸","木香槟榔丸","葛花解酲汤","健脾丸","木香导滞丸"],"a":1,"e":"木香槟榔丸行气导滞、攻积泄热，治湿热积滞之痢疾，以通下之品治泻痢，即“通因通用”。大黄、牵牛、槟榔攻积导滞，积去则痢自止。"},{"q":"滚痰丸属于的何类方剂","o":["燥湿化痰剂","清热化痰剂","温化寒痰剂","润燥化痰剂","治风化痰剂"],"a":1,"e":"滚痰丸由青礞石、大黄、黄芩、沉香组成，泻火逐痰，主治实热老痰之癫狂惊悸、咳喘痰稠，故属清热化痰剂。青礞石下气坠痰为君。"},{"q":"桑菊饮的功用是","o":["辛凉透表，清热解毒","疏风清热，宣肺止咳","辛凉疏表，清肺平喘","辛凉宣肺，清热解毒","宣利肺气，疏风止咳"],"a":1,"e":"桑菊饮疏风清热、宣肺止咳，为辛凉轻剂，主治风温初起、表热轻证，以咳嗽、身热不甚、口微渴为要点。银翘散则辛凉透表、清热解毒。"},{"q":"主治肝郁血虚脾弱证的方剂是","o":["小柴胡汤","龙胆泻肝汤","逍遥散","归脾汤","补中益气汤"],"a":2,"e":"逍遥散疏肝解郁、养血健脾，主治肝郁血虚脾弱证，见两胁作痛、头痛目眩、口燥咽干、神疲食少、月经不调、乳房胀痛、脉弦而虚。"},{"q":"属于六味地黄丸中“三泻”的药物是","o":["茯苓、泽泻、山茱萸","泽泻、牡丹皮、熟地黄","山药、茯苓、泽泻","茯苓、泽泻、牡丹皮","山茱萸、山药、泽泻"],"a":3,"e":"六味地黄丸中泽泻泻肾浊、牡丹皮清肝火、茯苓渗脾湿，合为“三泻”，与熟地、山茱萸、山药“三补”相配，补泻兼施，寓泻于补。"},{"q":"下列各项中，属于肾著汤药物组成的是","o":["杜仲","干姜","生姜","补骨脂","核桃仁"],"a":1,"e":"肾著汤即甘姜苓术汤，由甘草、干姜、茯苓、白术组成，温中散寒、健脾除湿，主治寒湿腰痛之腰重如带五千钱。方中干姜温中，非生姜。"},{"q":"凉开剂中长于镇痉息风的是","o":["安宫牛黄丸","紫雪","苏合香丸","抱龙丸","紫金锭"],"a":1,"e":"紫雪清热开窍、息风止痉，长于镇痉，主治热闭心包兼热盛动风之高热烦躁、神昏谵语、抽搐痉厥。安宫牛黄丸长于清热解毒，至宝丹长于化浊开窍。"},{"q":"琼玉膏的功用是","o":["滋阴润肺，益气补脾","养阴清肺，解毒利咽","润肺益胃，降逆下气","滋阴填精，益气壮阳","滋阴益气，固肾止渴"],"a":0,"e":"琼玉膏由生地黄、人参、白茯苓、白蜜熬膏，滋阴润肺、益气补脾，主治肺阴亏损、虚火灼津之干咳咯血、咽燥消瘦、气短乏力。"},{"q":"《医方集解》中记载的苏子降气汤与《局方》中记载的苏子降气汤的变化为","o":["去当归加枳实","去肉桂加沉香","去半夏加百部","去厚朴加麻黄","去前胡加柴胡"],"a":1,"e":"《局方》苏子降气汤用肉桂温补下元，《医方集解》则去肉桂加沉香，降气平喘之力更专。两方均以苏子为君，降气祛痰、平喘止咳。"},{"q":"定喘汤的功用为","o":["降逆化痰，益气和胃","宣肺降气，清热化痰","宣肺止咳，降气定喘","降气平喘，祛痰止咳","定喘止咳，宣肺降气"],"a":1,"e":"定喘汤宣肺降气、清热化痰，主治风寒外束、痰热内蕴之哮喘，见咳喘痰多气急、痰稠色黄、苔黄腻、脉滑数。麻黄宣肺，黄芩、桑白皮清肺热。"},{"q":"杏苏散的功用是","o":["清宣温燥，润肺止咳","清燥润肺，养阴益气","清热燥湿，调和气血","轻宣凉燥，理肺化痰","清养肺胃，降逆下气"],"a":3,"e":"杏苏散轻宣凉燥、理肺化痰，主治外感凉燥证，见恶寒无汗、头微痛、咳嗽痰稀、鼻塞咽干、苔白脉弦。苏叶、杏仁宣肺，前胡、桔梗化痰。"},{"q":"主治喑痱的方剂是","o":["大补阴丸","加减复脉汤","右归丸","地黄饮子","龟鹿二仙胶"],"a":3,"e":"地黄饮子滋肾阴、补肾阳、开窍化痰，主治下元虚衰、痰浊上泛之喑痱，见舌强不能言、足废不能用、口干不欲饮、脉沉细弱。"},{"q":"患者体倦气短，口渴多汗，咽干舌红，脉虚，宜选用","o":["补中益气汤","玉屏风散","人参蛤蚧散","四君子汤","生脉散"],"a":4,"e":"生脉散益气生津、敛阴止汗，主治暑热或久咳耗伤气阴之体倦气短、口渴多汗、咽干舌红、脉虚。人参补气，麦冬养阴，五味子敛津止汗。"},{"q":"补中益气汤中的君药是","o":["白术","黄芪","甘草","当归","人参"],"a":1,"e":"补中益气汤中黄芪重用为君，补中益气、升阳固表；人参、白术、甘草健脾益气为臣；升麻、柴胡升举清阳，当归养血，陈皮理气。"},{"q":"大定风珠的功用是","o":["凉肝息风","镇肝息风","滋阴息风","滋阴养血","潜阳息风"],"a":2,"e":"大定风珠滋阴息风，主治温病后期阴虚风动证，见神倦瘛疭、脉气虚弱、舌绛苔少、时时欲脱。阿胶、鸡子黄为君，大队滋阴药配三甲潜阳。"},{"q":"慢性痢疾属湿热积滞者，宜选用","o":["保和丸","木香槟榔丸","木香导滞丸","枳实导滞丸","健脾丸"],"a":3,"e":"枳实导滞丸消导化积、清热祛湿，药力较木香槟榔丸缓和，故宜于慢性痢疾而属湿热积滞者。木香槟榔丸攻积峻猛，只宜积滞实证。"},{"q":"玉屏风散治汗出的机制是","o":["祛风散邪","敛汗固表","益气解表","益气固表","调和营卫"],"a":3,"e":"玉屏风散益气固表止汗，主治表虚自汗，证由卫气虚弱、腠理不固、津液外泄而致。黄芪益气固表为君，白术健脾益气，防风走表祛风。"},{"q":"下列不含人参、五味子的方剂是","o":["生脉散","天王补心丹","琼玉膏","回阳救急汤","石斛夜光丸"],"a":2,"e":"琼玉膏由生地黄、人参、白茯苓、白蜜组成，有益气之品而无五味子。生脉散、天王补心丹、回阳救急汤、石斛夜光丸均同时配伍人参、五味子。"},{"q":"治疗痰涎壅盛于上，肾阳不足于下的喘咳应选用","o":["苏子降气汤","定喘汤","麻黄汤","小青龙汤","都气丸"],"a":0,"e":"苏子降气汤降气平喘、祛痰止咳，主治上实下虚之喘咳，即痰涎壅盛于上、肾阳不足于下，见喘咳痰多、胸膈满闷、腰疼脚弱、呼多吸少。"},{"q":"麻黄杏仁甘草石膏汤中的君药是","o":["麻黄","杏仁","石膏","麻黄、石膏","麻黄、杏仁"],"a":3,"e":"麻黄杏仁甘草石膏汤中麻黄与石膏同为君药，麻黄宣肺平喘、石膏清泄肺热，一宣一清，共成辛凉宣泄、清肺平喘之功。石膏用量倍于麻黄以制其温散。"},{"q":"十枣汤中善泻脏腑水邪的药是","o":["甘遂","大戟","商陆","芫花","牵牛"],"a":1,"e":"十枣汤中甘遂善行经隧之水湿，大戟善泄脏腑之水邪，芫花善消胸胁伏饮痰癖，三药峻烈各有所长，以大枣十枚护胃缓毒。"},{"q":"下列哪项不是“十剂”中的内容","o":["轻重","滑涩","温清","补泄","宣通"],"a":2,"e":"十剂为宣、通、补、泄、轻、重、涩、滑、燥、湿十类，源自北齐徐之才。温、清属后世治法分类，不在十剂之列。"},{"q":"下列关于旋覆代赭汤的说法，错误的是","o":["旋覆花降逆止嗳","代赭石善镇冲逆","生姜温中补虚","半夏祛痰散结","参枣草补脾胃之气"],"a":2,"e":"旋覆代赭汤中生姜用量最重，功用为和胃降逆止呕，并制约代赭石质重性寒之弊。温中补虚之职由人参、大枣、甘草承担，非生姜。"},{"q":"桂枝汤中桂枝与芍药的用量比例是","o":["2∶1","1∶2","3∶2","2∶3","1∶1"],"a":4,"e":"桂枝汤中桂枝与芍药各用三两，用量相等，一散一收，调和营卫，故比例为1∶1。桂枝加桂汤则重用桂枝，桂枝加芍药汤则倍用芍药。"},{"q":"玉屏风散证汗出的病机是","o":["卫气虚弱，不能固表","营卫不和","外感风寒","暑热耗气伤阴","脾胃气虚，阳浮于外"],"a":0,"e":"玉屏风散证之自汗，由卫气虚弱、腠理疏松、表虚不固、津液外泄所致。黄芪益气固表，白术健脾益气，防风走表祛风，卫强则汗自止。"},{"q":"凉膈散原方用量最大的药物是","o":["大黄","竹叶","连翘","栀子","黄芩"],"a":2,"e":"凉膈散原方连翘用二斤半，为全方用量最大者，以其清热解毒、透散上焦郁火为主。配大黄、芒硝、甘草即调胃承气汤，泻下以清上。"},{"q":"茵陈蒿汤中，泻热逐瘀且通便的药物是","o":["栀子","芒硝","茵陈","大黄","桃仁"],"a":3,"e":"茵陈蒿汤中茵陈清热利湿退黄为君，栀子清利三焦湿热，大黄泻热逐瘀、通利大便，使湿热瘀滞从二便分消，故黄疸退而腹满除。"},{"q":"具有敛阴止汗，益气固表功用的方剂是","o":["玉屏风散","牡蛎散","当归六黄汤","知柏地黄汤","补中益气汤"],"a":1,"e":"牡蛎散益气固表、敛阴止汗，主治体虚自汗、盗汗，见心悸惊惕、短气烦倦。煅牡蛎敛汗固涩为君，黄芪益气固表，麻黄根止汗，小麦养心。"},{"q":"六味地黄丸的主治证是","o":["肝阴虚证","心阴虚证","脾阴虚证","肺阴虚证","肾阴虚证"],"a":4,"e":"六味地黄丸滋补肝肾，主治肾阴虚证，见腰膝酸软、头晕目眩、耳鸣耳聋、盗汗遗精、手足心热、舌红少苔、脉沉细数。三补三泻，补而不腻。"},{"q":"治疗外感温燥证宜首选的方剂是","o":["麻黄汤","桂枝汤","桑杏汤","杏苏散","桑菊饮"],"a":2,"e":"外感温燥证治宜清宣温燥、润肺止咳，首选桑杏汤。方中桑叶、豆豉轻宣燥热，杏仁、象贝宣肺止咳，沙参、梨皮润肺生津，为温燥轻证之良剂。"},{"q":"左金丸中黄连与吴茱萸的配伍比例是","o":["1∶1","2∶1","5∶1","6∶1","7∶1"],"a":3,"e":"左金丸中黄连与吴茱萸用量为六比一，重用黄连苦寒泻肝火、清胃热，少佐吴茱萸辛热开郁降逆，并制黄连之寒，取“实则泻其子”之义。"},{"q":"温胆汤之功用不包括","o":["理气","化痰","温胆","和胃","清胆"],"a":2,"e":"温胆汤理气化痰、清胆和胃，主治胆胃不和、痰热内扰证。方中竹茹、枳实性偏寒凉，全方实为清胆而非温胆，故名同实异。"},{"q":"补天大造丸的功用主治是","o":["养肝敛阴","补五脏虚损","涩精止遗","脾胃气虚","气阴两虚"],"a":1,"e":"补天大造丸由人参、黄芪、白术、当归、酸枣仁、远志、白芍、山药、枸杞子、熟地、龟甲、鹿角、紫河车等组成，补五脏虚损，主治虚劳诸不足。"},{"q":"小青龙汤中的君药是","o":["桂枝、白芍","干姜、细辛","干姜、半夏","麻黄、桂枝","桂枝、干姜"],"a":3,"e":"小青龙汤中麻黄、桂枝共为君药，发汗解表、宣肺平喘，并通阳化饮。干姜、细辛温肺化饮为臣，五味子敛肺，芍药和营，半夏化痰。"},{"q":"黄土汤与理中丸共有的药物是","o":["人参","白术","干姜","黄芩","附子"],"a":1,"e":"黄土汤由灶心黄土、白术、附子、干地黄、阿胶、黄芩、甘草组成，理中丸由人参、干姜、白术、甘草组成，两方共有白术、甘草，皆寓温中健脾之意。"},{"q":"十灰散与槐花散共有的药物是","o":["槐花","侧柏叶","小蓟","大蓟","山栀子"],"a":1,"e":"十灰散由大蓟、小蓟、荷叶、侧柏叶、茅根、茜草、山栀、大黄、牡丹皮、棕榈皮组成，槐花散由槐花、侧柏叶、荆芥穗、枳壳组成，两方共有侧柏叶凉血止血。"},{"q":"以下关于大定风珠的组成，表述错误的是","o":["鸡子黄、五味子","阿胶、熟地","白芍、麦冬","龟板、鳖甲","牡蛎、麻仁"],"a":1,"e":"大定风珠由生白芍、阿胶、生龟板、干地黄、麻仁、五味子、生牡蛎、麦冬、炙甘草、鸡子黄、生鳖甲组成，用干地黄凉血滋阴。熟地黄非本方所有。"},{"q":"玉真散的功用是","o":["祛风除湿，定搐止痉","祛风除湿，通络止痉","祛风化痰，定搐止痉","祛风化痰，通络止痉","祛风散邪，化痰止痉"],"a":2,"e":"玉真散由天南星、防风、白芷、天麻、羌活、白附子组成，祛风化痰、定搐止痉，主治破伤风之牙关紧闭、口撮唇紧、身体强直、角弓反张。"},{"q":"二陈汤中的君药是","o":["橘红","半夏","茯苓","乌梅","炙甘草"],"a":1,"e":"二陈汤中半夏燥湿化痰、降逆和胃为君；橘红理气燥湿，使气顺则痰消；茯苓健脾渗湿，生姜降逆化饮，乌梅收敛肺气，甘草调和诸药。"},{"q":"大黄牡丹汤和桃核承气汤两方组成中均含有的药物是","o":["大黄、桃仁、甘草","大黄、芒硝、甘草","大黄、赤芍、甘草","大黄、芒硝、桃仁","大黄、芒硝、赤芍"],"a":3,"e":"大黄牡丹汤由大黄、牡丹皮、桃仁、芒硝、冬瓜仁组成，桃核承气汤由桃仁、大黄、桂枝、甘草、芒硝组成，两方共有大黄、芒硝、桃仁以下瘀泻热。"},{"q":"金锁固精丸的主要功用是","o":["涩精止遗","固脬缩尿","固经止血","收涩止带","固表止汗"],"a":0,"e":"金锁固精丸补肾涩精，主治肾虚精关不固之遗精滑泄、神疲乏力、腰痛耳鸣。沙苑蒺藜补肾固精为君，芡实、莲子、莲须固肾涩精，龙骨、牡蛎潜阳固涩。"},{"q":"竹叶石膏汤的主治证是","o":["暑湿证","气分热盛证","暑热气津两伤证","暑病余热未清，气阴两伤证","气分热盛，气津两伤证"],"a":3,"e":"竹叶石膏汤清热生津、益气和胃，主治热病之后余热未清、气阴两伤证，见身热多汗、心胸烦闷、气逆欲呕、口干喜饮、舌红少苔、脉虚数。"},{"q":"平胃散的主治病证是","o":["脾胃气虚证","脾胃气滞证","痰阻脾胃证","湿浊内停证","湿滞脾胃证"],"a":4,"e":"平胃散燥湿运脾、行气和胃，主治湿滞脾胃证，见脘腹胀满、不思饮食、口淡无味、恶心呕吐、肢体沉重、苔白腻而厚、脉缓。"},{"q":"麻黄汤主治证候的病机是","o":["外感风寒，营卫不和","外感风寒湿邪，内有蕴热","风邪犯肺，肺失清肃","外感风寒，肺气失宣","外感风寒，水饮内停"],"a":3,"e":"麻黄汤发汗解表、宣肺平喘，主治外感风寒表实证，病机为风寒束表、卫阳被遏、肺气失宣，见恶寒发热、无汗而喘、头身疼痛、脉浮紧。"},{"q":"痛泻要方主治之腹泻特点是","o":["泻必腹痛，泻后痛减","每于五更，定时而发","腹痛腹泻，久治不愈","大便带血，血色黯淡","泻下无度，里急后重"],"a":0,"e":"痛泻要方主治脾虚肝旺之痛泻，因肝气横逆克脾、脾失健运、清浊不分而致，故泻必腹痛、泻后痛减，兼肠鸣、脉两关不调、左弦右缓。"},{"q":"健脾丸的功用是","o":["行气导滞，消食和胃","健脾和胃，消食止泻","补脾益气，消食止泻","健脾消积，行气和胃","消食和胃，健脾渗湿"],"a":1,"e":"健脾丸健脾和胃、消食止泻，主治脾虚食积证，见食少难消、脘腹痞闷、大便溏薄、倦怠乏力、苔腻微黄、脉虚弱。补消兼施，以补为主。"},{"q":"治疗肾虚便秘，首选方剂是","o":["济川煎","五仁丸","肾气丸","十枣汤","黄龙汤"],"a":0,"e":"济川煎温肾益精、润肠通便，主治肾阳虚弱、精津不足之便秘，见大便干结、小便清长、腰膝酸软、头目眩晕。肉苁蓉温肾润肠为君。"},{"q":"麦门冬汤的功用是","o":["养阴益胃，止咳化痰","养阴清肺，止咳化痰","滋养肺胃，降逆下气","滋养肺肾，降逆下气","养阴润肺，益胃生津"],"a":2,"e":"麦门冬汤滋养肺胃、降逆下气，主治虚热肺痿，见咳唾涎沫、短气喘促、咽干口燥、舌红少苔、脉虚数。重用麦冬七升为君，配半夏降逆。"},{"q":"具有敛肺止咳，益气养阴功用的方剂是","o":["生脉散","泻白散","九仙散","小青龙汤","定喘汤"],"a":2,"e":"九仙散敛肺止咳、益气养阴，主治久咳肺虚、气阴两伤证，见咳嗽日久、咳甚则气喘自汗、痰少而黏、脉虚数。罂粟壳敛肺止咳为君。"},{"q":"白虎汤的功用是","o":["清热生津","清热，益气，生津","清热通络，和营卫","清热生津，益气和胃","清热益气，养阴生津"],"a":0,"e":"白虎汤清热生津，主治气分热盛证，见壮热面赤、烦渴引饮、汗出恶热、脉洪大有力。石膏辛甘大寒，清阳明气分之热为君，知母助其清热滋阴。"},{"q":"参苓白术散除益气健脾外兼有何功用","o":["补气升阳举陷","益气固表止汗","和胃渗湿保肺","消食理气导滞","补肺益肾止咳"],"a":2,"e":"参苓白术散益气健脾、渗湿止泻，兼能和胃渗湿、培土生金以保肺，主治脾胃气虚夹湿之泄泻，亦治肺损虚劳。桔梗载药上行，开宣肺气。"},{"q":"组成药物中无茯苓的方剂是","o":["半夏厚朴汤","枳实消痞丸","厚朴温中汤","苏子降气汤","逍遥散"],"a":3,"e":"苏子降气汤由紫苏子、半夏、当归、前胡、厚朴、肉桂、甘草组成，方中不用茯苓。半夏厚朴汤、枳实消痞丸、厚朴温中汤、逍遥散均含茯苓。"},{"q":"葱豉桔梗汤的功用是","o":["解肌发汗","解肌清热","解肌透疹","疏风止痛","疏风清热"],"a":4,"e":"葱豉桔梗汤辛凉解表、疏风清热，主治风温初起，见头痛身热、微恶风寒、咳嗽咽痛。葱白、豆豉解表，薄荷、栀子、连翘、淡竹叶清热。"},{"q":"生化汤的功用是","o":["活血化瘀，行气止痛","温经散寒，祛瘀养血","养血活血，温经止痛","活血行气，温经止痛","活血祛瘀，通络止痛"],"a":2,"e":"生化汤养血活血、温经止痛，主治产后血虚寒凝、瘀血阻滞之恶露不行、小腹冷痛。重用当归养血活血，川芎、桃仁祛瘀，炮姜温经，甘草缓急。"},{"q":"清气化痰丸与温胆汤同用的药物是","o":["枳实","胆南星","甘草","黄芩","浙贝母"],"a":0,"e":"清气化痰丸由胆南星、瓜蒌仁、黄芩、半夏、陈皮、茯苓、枳实、杏仁组成，温胆汤由半夏、竹茹、枳实、陈皮、茯苓、甘草、生姜、大枣组成，两方共有枳实。"},{"q":"十灰散中用以凉血祛瘀，防血止留瘀的药物是","o":["牡丹皮","丹参","三七","当归","川芎"],"a":0,"e":"十灰散凉血止血，方中牡丹皮清热凉血、活血散瘀，使血止而不留瘀；大黄导热下行、凉血化瘀，亦寓此意。十药炒炭存性，增强止血之力。"},{"q":"大定风珠配伍的君药是","o":["鸡子黄、熟地","阿胶、干地黄","鸡子黄、干地黄","阿胶、鸡子黄","阿胶、熟地"],"a":3,"e":"大定风珠中阿胶、鸡子黄滋阴养血、濡养筋脉，共为君药，主治阴虚风动之瘛疭神倦。白芍、干地黄、麦冬滋阴柔肝为臣，三甲潜阳息风。"},{"q":"症见恶寒发热，呕吐泄泻，舌苔白腻者，治宜","o":["连朴饮","藿香正气散","甘露消毒丹","三仁汤","八正散"],"a":1,"e":"藿香正气散解表化湿、理气和中，主治外感风寒、内伤湿滞证，见恶寒发热、头痛、胸膈满闷、脘腹疼痛、呕吐泄泻、舌苔白腻。"},{"q":"吴茱萸汤的组成不包括","o":["吴茱萸","半夏","大枣","生姜","人参"],"a":1,"e":"吴茱萸汤由吴茱萸、人参、生姜、大枣组成，温中补虚、降逆止呕，主治肝胃虚寒、浊阴上逆之头痛、干呕吐涎沫。方中无半夏，降逆全赖吴茱萸与生姜。"},{"q":"枳实消痞丸的功用为","o":["行气祛痰，健脾和胃","行气温中，燥湿除满","行气散结，降逆化痰","行气消痞，健脾和胃","行气降逆，化痰散结"],"a":3,"e":"枳实消痞丸行气消痞、健脾和胃，主治脾虚气滞、寒热互结之心下痞满，见不欲饮食、倦怠乏力、大便不畅、苔腻微黄。枳实、厚朴行气，四君子健脾。"},{"q":"既是治疗少阳病证之基础方，又是和解少阳法之代表方是","o":["逍遥散","半夏泻心汤","痛泻要方","小柴胡汤","大柴胡汤"],"a":3,"e":"小柴胡汤和解少阳，主治伤寒少阳证之往来寒热、胸胁苦满、默默不欲饮食、心烦喜呕、口苦咽干目眩，为和解少阳法之代表方与基础方。"},{"q":"朱砂安神丸与交泰丸具有的共同药物组成为","o":["当归","黄连","肉桂","茯神","朱砂"],"a":1,"e":"朱砂安神丸由朱砂、黄连、生地黄、当归、炙甘草组成，交泰丸由黄连、肉桂组成，两方共有黄连以清心泻火。交泰丸取肉桂引火归元，交通心肾。"},{"q":"瓜蒌薤白白酒汤的功用为","o":["通阳散结，祛痰宽胸","通阳散结，下气祛痰","通阳散结，行气祛痰","温通心阳，下气祛痰","温通心阳，行气宽胸"],"a":2,"e":"瓜蒌薤白白酒汤通阳散结、行气祛痰，主治胸阳不振、痰气互结之胸痹，见胸痛彻背、喘息咳唾、短气、苔白腻、脉沉弦。瓜蒌化痰散结，薤白通阳。"},{"q":"败毒散组成中的人参属于","o":["君药","臣药","佐助药","佐制药","反佐药"],"a":2,"e":"败毒散中人参用量极少，属佐助药，益气扶正以鼓邪从表而解，使全方散中有补、祛邪而不伤正。正气充足则邪有外达之路。"},{"q":"当归补血汤有，而四物汤没有的药是","o":["干地黄","黄芪","川芎","芍药","当归"],"a":1,"e":"当归补血汤由黄芪、当归组成，黄芪用量五倍于当归，补气以生血。四物汤由熟地、当归、白芍、川芎组成，养血活血，方中无黄芪。"},{"q":"“每剂不过三钱，用生绢小袋盛之，煮作汤饮，随甘旨代茶水啜用，不宜煎熬太过”的用法出自于","o":["苓甘五味姜辛汤","三子养亲汤","半夏白术天麻汤","养阴清肺汤","半夏厚朴汤"],"a":1,"e":"三子养亲汤由紫苏子、白芥子、莱菔子组成，方后注要求每剂不过三钱，生绢小袋盛之煮汤代茶啜饮，不宜煎熬太过，以保持药力轻清。"},{"q":"逍遥散与银翘散共用的药物是","o":["炙甘草","薄荷","白芍","柴胡","连翘"],"a":1,"e":"逍遥散中加薄荷少许，助柴胡疏肝散热；银翘散亦用薄荷辛凉透表、清利头目，故两方共有薄荷。柴胡、白芍仅属逍遥散。"},{"q":"具有清热解毒，凉血散瘀功用的方剂是","o":["清营汤","黄连解毒汤","清瘟败毒饮","犀角地黄汤","白虎加桂枝汤"],"a":3,"e":"犀角地黄汤以犀角（水牛角代）咸寒入血分，清心凉血解毒，配生地、赤芍、丹皮凉血散瘀，故具清热解毒、凉血散瘀之功。"},{"q":"以下关于玉真散的药物组成描述正确的是","o":["防风、白芷、天麻、羌活、黑附子、天南星","防风、白芷、天麻、独活、黑附子、胆南星","防风、白芷、天麻、羌活、白附子、天南星","防风、白芷、天麻、羌活、白附子、胆南星","防风、白芷、天麻、独活、白附子、天南星"],"a":2,"e":"玉真散由防风、白芷、天麻、羌活、白附子、天南星六药组成，主治破伤风，取祛风化痰止痉之效。"},{"q":"济川煎主治证的病机关键在于","o":["阳虚冷结","肾虚精亏","肠燥津枯","血虚津少","津亏热结"],"a":1,"e":"济川煎所治便秘源于肾虚精亏、开阖失司，故以肉苁蓉温肾益精、润肠通便为君，配当归、牛膝养血下行。"},{"q":"逍遥散中体现“补肝体”作用的药物是","o":["当归、芍药","柴胡、薄荷","柴胡、白芍","白术、茯苓","生姜、甘草"],"a":0,"e":"逍遥散中当归养血补肝，白芍养血敛阴、柔肝缓急，二者相合补肝之体，以遂肝木条达之性。"},{"q":"槐花散中用以疏风止血的药物是","o":["防风","升麻","羌活","柴胡","荆芥穗"],"a":4,"e":"槐花散以荆芥穗炒黑入血分，疏风止血，与槐花、侧柏叶、枳壳相配，使肠风脏毒下血得止。"},{"q":"阿胶鸡子黄汤配伍的臣药是","o":["阿胶、生地","阿胶、白芍","白芍、鸡子黄","生地、鸡子黄","白芍、生地"],"a":4,"e":"阿胶鸡子黄汤以阿胶、鸡子黄滋阴养血为君，白芍、生地养阴柔肝为臣，佐牡蛎、石决明等潜阳息风。"},{"q":"地黄饮子组成中有","o":["人参","白术","天麻","当归","石菖蒲"],"a":4,"e":"地黄饮子用地黄、巴戟、山茱萸等阴阳并补，配石菖蒲、远志、茯苓交通心肾、开窍化痰，治喑痱证。"},{"q":"黄芩、半夏、滑石同用的方剂是","o":["小柴胡汤","半夏泻心汤","蒿芩清胆汤","温脾汤","归脾汤"],"a":2,"e":"蒿芩清胆汤以青蒿、黄芩清透胆热，配半夏、竹茹、枳壳和胃化痰，碧玉散中含滑石以利湿，三药同用。"},{"q":"以下关于消风散的君药描述错误的是","o":["牛蒡子","苍术","荆芥","防风","蝉蜕"],"a":1,"e":"消风散以荆芥、防风、蝉蜕、牛蒡子疏风止痒为君；苍术苦温燥湿，属臣佐之品，并非君药。"},{"q":"属于六味地黄丸中“三补”的药物是","o":["熟地黄、山茱萸、牡丹皮","熟地黄、山药、泽泻","熟地黄、山茱萸、山药","山茱萸、山药、牡丹皮","茯苓、泽泻、牡丹皮"],"a":2,"e":"六味地黄丸三补为熟地黄、山茱萸、山药，分补肾、肝、脾之阴；泽泻、牡丹皮、茯苓为三泻。"},{"q":"不属于黄芪桂枝五物汤组成的是","o":["黄芪","芍药","桂枝","生姜","甘草"],"a":4,"e":"黄芪桂枝五物汤即桂枝汤去甘草、倍生姜加黄芪，由黄芪、芍药、桂枝、生姜、大枣组成，故无甘草。"},{"q":"治疗痰热咳嗽之代表方","o":["清气化痰丸","贝母瓜蒌散","苓甘五味姜辛汤","二陈汤","温胆汤"],"a":0,"e":"清气化痰丸以胆南星、瓜蒌仁清热化痰，配黄芩、枳实、茯苓，主治痰热内结之咳嗽痰黄稠厚。"},{"q":"复元活血汤对大黄炮制的要求是","o":["先煎","后入","酒浸","炒炭","生用"],"a":2,"e":"复元活血汤中大黄酒浸，取其活血化瘀、荡涤败血之力，与柴胡相配，共奏疏肝通络、祛瘀生新之效。"},{"q":"玉屏风散中配伍黄芪的意义是","o":["补益正气，托脓外出","益气固表，行水消肿","内补脾肺，固表止汗","大补元气，气旺血行","补气健脾，化生气血"],"a":2,"e":"玉屏风散中黄芪内补脾肺之气，外固肌表而止汗，与白术、防风相配，补散兼施，主治表虚自汗。"},{"q":"小承气汤组成药物正确的是","o":["大黄、枳实、厚朴","大黄、芒硝、甘草","大黄、枳实、甘草","大黄、枳实、芒硝","大黄、厚朴、甘草"],"a":0,"e":"小承气汤由大黄、枳实、厚朴三味组成，轻下热结，主治痞、满、实而不燥之阳明腑实证，故不用芒硝。"},{"q":"干姜为苓甘五味姜辛汤中的","o":["臣药","佐药","君药","佐助药","佐制药"],"a":2,"e":"苓甘五味姜辛汤重用干姜为君，温肺散寒以化饮，辅以细辛、五味子，主治寒饮内停之咳嗽痰稀。"},{"q":"治疗热毒痢疾，应首选的方剂是","o":["芍药汤","香连丸","黄芩汤","白头翁汤","白头翁加甘草阿胶汤"],"a":3,"e":"白头翁汤以白头翁清热解毒、凉血止痢为君，配黄连、黄柏、秦皮，专治热毒深陷血分之痢。"},{"q":"黄土汤和龙胆泻肝汤共有的药物是","o":["白术、山栀子","山栀子、生地黄","山栀子、黄芩","黄芩、生地黄","白术、木通"],"a":3,"e":"黄土汤含黄芩、干地黄，龙胆泻肝汤含黄芩、生地黄，二方共有此二味，前者温阳摄血，后者清泻肝火。"},{"q":"苓甘五味姜辛汤中既温肺化饮，又温脾化湿的药物是","o":["茯苓","甘草","五味子","细辛","干姜"],"a":4,"e":"干姜辛热，既温肺散寒以化饮，又温脾阳以化湿，故为苓甘五味姜辛汤中兼顾肺脾之要药。"},{"q":"牡蛎散中功专止汗的药物是","o":["煅牡蛎","麻黄根","生黄芪","浮小麦","山茱萸"],"a":1,"e":"麻黄根甘涩，专入肺经，功专收敛止汗，与黄芪、牡蛎、浮小麦相伍，主治体虚之自汗盗汗。"},{"q":"下列各项，不属于杏苏散的组成药物","o":["半夏、茯苓","橘皮、前胡","荆芥、防风","枳壳、生姜","桔梗、大枣"],"a":2,"e":"杏苏散由苏叶、杏仁、半夏、茯苓、橘皮、前胡、桔梗、枳壳、甘草、生姜、大枣组成，方中无荆芥、防风。"},{"q":"当归四逆汤主治病证的主要临床表现是","o":["恶寒蜷卧","手足厥寒","腹痛下利","倦怠乏力","脉微欲绝"],"a":1,"e":"当归四逆汤证为血虚寒凝、阳气不达四末，故以手足厥寒、脉细欲绝为主症，治宜温经散寒、养血通脉。"},{"q":"阳和汤中少佐麻黄的主要用意是","o":["发汗散寒、通达表里","宣通肺气、开发腠理","鼓舞阳气、散寒通滞","制熟地黄、鹿角胶之滋腻","宣肺解表，调和营卫"],"a":2,"e":"阳和汤少佐麻黄辛温达卫，宣通经络，鼓舞阳气以散寒通滞，并引补血之品直达病所，使补而不滞。"},{"q":"炙甘草汤中用量最大的药物是","o":["炙甘草","生地黄","麦门冬","人参","生姜"],"a":1,"e":"炙甘草汤中生地黄用量一斤，居诸药之首，滋阴养血以充血脉，与炙甘草、人参、阿胶等同复脉气。"},{"q":"天台乌药散的功用为","o":["行气疏肝，散寒止痛","行气疏肝，祛寒止痛","温补肝肾，行气止痛","行气活血，调经止痛","行气活血，软坚散结"],"a":0,"e":"天台乌药散以乌药、木香、小茴香行气疏肝，配高良姜、青皮、槟榔散寒止痛，主治寒凝肝脉之疝痛。"},{"q":"右归丸的功用是","o":["温补肾阳，填精益髓","滋阴补肾，填精益髓","温肾化气，利水消肿","温肾壮阳，涩精止遗","温补肾阳，涩精缩尿"],"a":0,"e":"右归丸以附子、肉桂、鹿角胶温补肾阳，配熟地、山药、枸杞子、菟丝子填精益髓，纯补无泻。"},{"q":"黄土汤的组成药物中无","o":["白术","附子","干姜","阿胶","干地黄"],"a":2,"e":"黄土汤由灶心黄土、白术、附子、干地黄、阿胶、黄芩、甘草组成，温阳健脾以摄血，方中不用干姜。"},{"q":"具有温肾益精，润肠通便功用的方剂是","o":["肾气丸","五仁丸","麻子仁丸","济川煎","润肠丸"],"a":3,"e":"济川煎以肉苁蓉温肾益精、润肠通便为君，配当归、牛膝、枳壳、升麻、泽泻，寓通于补，降中有升。"},{"q":"川芎茶调散的功用是","o":["疏风解表","疏风清热","疏风止痛","祛风化痰","祛风除湿"],"a":2,"e":"川芎茶调散以川芎为君，辛温香窜，上行头目，善祛风止痛，配荆芥、白芷、羌活等，共成疏风止痛之剂。"},{"q":"厚朴温中汤的臣药为","o":["草豆蔻","陈皮","茯苓","木香","干姜"],"a":0,"e":"厚朴温中汤以厚朴行气燥湿为君，草豆蔻温中燥湿、干姜温中散寒共为臣，主治寒湿气滞之脘腹胀痛。"},{"q":"牡蛎散、玉屏风散、补中益气汤三方中共同的药物是","o":["当归","黄芪","防风","橘红","炙甘草"],"a":1,"e":"牡蛎散用黄芪益气固表，玉屏风散以黄芪为君益气固表止汗，补中益气汤重用黄芪补中升阳，三方皆备。"},{"q":"下列各项中，属于苓桂术甘汤主治症状的是","o":["胸胁胀痛","目眩心悸","气逆而喘","苔白腻","水入即吐"],"a":1,"e":"苓桂术甘汤证为脾阳不运、饮停心下，症见胸胁支满、目眩心悸，以茯苓、桂枝、白术、甘草温阳化饮。"},{"q":"平胃散主治证的病机是","o":["湿阻气滞，肝脾不和","湿阻气滞，肝胃不和","湿阻气滞，胆胃不和","湿阻气滞，脾胃失和","湿阻气滞，肠胃失和"],"a":3,"e":"平胃散以苍术燥湿运脾为君，厚朴行气除满，陈皮理气和胃，主治湿滞脾胃之脘腹胀满、舌苔白腻。"},{"q":"小陷胸汤治疗的痰证是","o":["热痰","湿痰","燥痰","风痰","顽痰"],"a":0,"e":"小陷胸汤以黄连苦寒泻热，半夏辛温化痰，瓜蒌润燥涤痰，三药相合，专治痰热互结于心下之结胸。"},{"q":"温脾汤与济川煎共有的药物是","o":["附子","肉苁蓉","当归","人参","甘草"],"a":2,"e":"温脾汤含当归、大黄、附子、干姜、人参、芒硝、甘草；济川煎含当归、牛膝、肉苁蓉等，二方共有当归。"},{"q":"下列方剂组成中含有人参、黄芪、白术、甘草的是","o":["参苓白术散","四君子汤","人参蛤蚧散","补中益气汤","玉屏风散"],"a":3,"e":"补中益气汤由黄芪、人参、白术、甘草、当归、陈皮、升麻、柴胡组成，四味益气药俱全，功在补中升阳。"},{"q":"大青龙汤的功用是","o":["发汗解表，宣肺平喘","发汗解表，兼清里热","解肌发表，调和营卫","温经散寒，养血通脉","发汗解表，平冲降逆"],"a":1,"e":"大青龙汤以麻黄汤倍麻黄加石膏、姜枣，外散风寒、内清郁热，主治表寒里热之无汗烦躁。"},{"q":"左归丸的功用是","o":["滋阴补肾，涩精止遗","温补肾阳，填精补血","滋阴补肾，填精益髓","补益肝肾，强壮筋骨","填精补髓，滋阴降火"],"a":2,"e":"左归丸以熟地、山药、山茱萸、枸杞子、龟板胶等纯补真阴，填精益髓，主治真阴不足之腰酸遗精。"},{"q":"阳和汤的主治病证不包括","o":["贴骨疽","流注","鹤西风","大头瘟","痰核"],"a":3,"e":"阳和汤主治阳虚寒凝之阴疽，如贴骨疽、脱疽、流注、痰核、鹤膝风；大头瘟属温毒上攻头面，非其所治。"},{"q":"补阳还五汤的功用","o":["补气，活血，养血","补气，活血，通络","补气，活血，行气","行气，舒肝，通络","行气，止痛，活血"],"a":1,"e":"补阳还五汤重用黄芪补气，配当归尾、赤芍、川芎、桃仁、红花、地龙活血通络，主治气虚血瘀之中风。"},{"q":"痛泻要方主治证的病机是","o":["肝郁克脾","土虚木乘","火不暖土","土不生金","心肾不交"],"a":1,"e":"痛泻要方证由脾虚肝旺、土虚木乘，肝脾不和，故腹痛即泻、泻后痛减，治宜补脾柔肝、祛湿止泻。"},{"q":"半夏白术天麻汤的组成含有","o":["半夏、橘红、白术、乌梅、甘草","半夏、橘红、白茯苓、乌梅、甘草","半夏、陈皮、白茯苓、大枣、甘草","半夏、陈皮、茯苓、胆南星、甘草","半夏、橘红、白术、大枣、甘草"],"a":4,"e":"半夏白术天麻汤由半夏、天麻、白术、茯苓、橘红、甘草、生姜、大枣组成，方中用橘红而非陈皮，亦无乌梅。"},{"q":"大黄牡丹汤中君药是","o":["大黄、桃仁","牡丹皮、大黄","桃仁、牡丹皮","瓜子、芒硝","大黄、芒硝"],"a":0,"e":"大黄牡丹汤以大黄泻热逐瘀、桃仁破血散结共为君，配牡丹皮、芒硝、冬瓜籽，主治肠痈初起。"},{"q":"泻白散的功用是","o":["清泻肺热","泻肺行水，下气平喘","清泻肺热，止咳平喘","辛凉疏表，清肺平喘","疏风清热，宣肺止咳"],"a":2,"e":"泻白散以桑白皮清泻肺热、平喘止咳为君，配地骨皮、甘草、粳米，主治肺有伏火之咳喘。"},{"q":"镇肝熄风汤配伍的君药是","o":["白芍","代赭石","怀牛膝","牡蛎","龟板"],"a":2,"e":"镇肝熄风汤重用怀牛膝为君，引血下行、补益肝肾，配代赭石、龙骨、牡蛎等重镇潜阳，主治肝阳上亢、气血上逆之类中风。"},{"q":"十灰散的病机是","o":["血热妄行，损伤血络","脾阳不足，统摄失常","血热妄行，瘀血内停","肝火犯肺，损伤血络","冲任虚寒，血不内守"],"a":0,"e":"十灰散所治出血由血热妄行、损伤血络而致，故以十味凉血止血药炒炭，兼清降火热，主治上部出血之呕血、咯血。"},{"q":"下列选项与“朱砂安神丸”组成有关，并且功效也正确的是","o":["黄连苦寒，入心经，清心泻火以除烦热","酸枣仁养血补肝，宁心安神","柏子仁养血安神","茯神健脾安神","远志宁心安神"],"a":0,"e":"朱砂安神丸以朱砂镇心安神，黄连苦寒入心经，清心泻火除烦，配生地、当归滋阴养血，主治心火亢盛之失眠。"},{"q":"主治梅核气的方剂为","o":["柴胡疏肝散","越鞠丸","四磨汤","半夏厚朴汤","枳实消痞丸"],"a":3,"e":"半夏厚朴汤以半夏化痰散结、降逆和胃，配厚朴、茯苓、生姜、苏叶，专治情志不畅、痰气互结之梅核气。"},{"q":"龙胆泻肝汤的主治证是","o":["肝阳上亢","肝火上炎","肝火犯肺","肝气郁结","肝火犯胃"],"a":1,"e":"龙胆泻肝汤以龙胆草、黄芩、栀子清泻肝胆实火，配泽泻、木通、车前子利湿，主治肝火上炎、湿热下注。"},{"q":"下列各项中，不属于芍药在真武汤中配伍意义的是","o":["利小便","柔肝缓急","敛阴舒筋","养血调经","制附子温燥之性"],"a":3,"e":"真武汤中芍药利小便、柔肝缓急、敛阴舒筋，并制附子温燥之性，与养血调经无关，调经属四物汤之类。"},{"q":"四物汤与补中益气汤共有的药是","o":["地黄","黄芪","白术","当归","芍药"],"a":3,"e":"四物汤由熟地、当归、白芍、川芎组成，为补血调血基础方；补中益气汤亦用当归养血，二方共有之品即当归。"},{"q":"半夏厚朴汤的功用为","o":["行气散结，降逆化痰","行气祛痰，降逆散结","行气解郁，理气化痰","行气消痞，健脾化痰","行气解郁，疏肝理脾"],"a":0,"e":"半夏厚朴汤以半夏、厚朴行气开郁、降逆化痰，配茯苓、生姜、苏叶，共奏行气散结、降逆化痰之功。"},{"q":"由大黄、芒硝、甘遂组成的方剂是","o":["小承气汤","大承气汤","小柴胡汤","大柴胡汤","大陷胸汤"],"a":4,"e":"大陷胸汤由大黄、芒硝、甘遂组成，泻热逐水，主治水热互结之结胸，见心下硬满、痛不可近。"},{"q":"下列选项中，不属于十枣汤组成的是","o":["商陆","甘遂","大戟","芫花","大枣"],"a":0,"e":"十枣汤由甘遂、大戟、芫花三味峻下逐水药与大枣十枚组成，商陆虽亦逐水，却非本方之品。"},{"q":"一贯煎的君药是","o":["沙参","枸杞子","当归","生地黄","麦门冬"],"a":3,"e":"一贯煎重用生地黄为君，滋阴养血、补益肝肾，配沙参、麦冬、当归、枸杞子、川楝子，主治肝肾阴虚之胁痛。"},{"q":"半夏厚朴汤中的臣药为","o":["半夏","厚朴","苏叶","茯苓","生姜"],"a":1,"e":"半夏厚朴汤以半夏为君化痰散结、降逆和胃，厚朴为臣行气开郁、下气除满，二者相配痰气并治。"},{"q":"九味羌活汤主治证候的病机是","o":["外感风寒，营卫不和","外感风寒湿邪，内有蕴热","外感风寒，内有蕴热","外感风寒，肺气失宣","外感风寒，水饮内停"],"a":1,"e":"九味羌活汤证为外感风寒湿邪、内有蕴热，故用羌活、防风、苍术散寒除湿，配黄芩、生地清泄里热。"},{"q":"血虚寒厥证手足厥寒宜用","o":["四逆散","四逆汤","当归四逆汤","独活寄生汤","回阳救急汤"],"a":2,"e":"当归四逆汤温经散寒、养血通脉，主治血虚寒凝之手足厥寒、脉细欲绝，与阳衰寒厥之四逆汤证不同。"},{"q":"大建中汤与小建中汤比较前者作用较峻的一项是","o":["补益气血","补虚散寒","温补肾阳","温里散寒","甘温益气"],"a":1,"e":"大建中汤用蜀椒、干姜辛热散寒，人参、饴糖补虚，其补虚散寒之力较小建中汤之甘温缓急更为峻猛。"},{"q":"桂枝在五苓散中的作用是","o":["温通血脉","解肌发表","温经散寒","调和营卫","温阳化气"],"a":4,"e":"五苓散中桂枝通阳化气以助气化，与茯苓、猪苓、泽泻、白术相配，使水湿得以下行，非为解表而设。"},{"q":"四神丸主治证的主要病机是","o":["命门火衰","脾阳不足","湿热下注","寒湿内停","瘀血阻滞"],"a":0,"e":"四神丸证由命门火衰、脾肾虚寒，五更阳气未振而作泻，故以补骨脂温肾暖脾为君，配肉豆蔻、五味子、吴茱萸。"},{"q":"六一散中滑石与甘草配伍，功能","o":["祛暑解表","清暑益气","清暑利湿","清热解毒","疏风清热"],"a":2,"e":"六一散以滑石六份、甘草一份组成，滑石清热利湿，甘草和中，共奏清暑利湿之功，主治暑湿之身热烦渴。"},{"q":"葛根黄芩黄连汤的功用是","o":["解表清里","解表温里","发散风热","清热解毒","清热燥湿"],"a":0,"e":"葛根黄芩黄连汤以葛根解表升清，黄芩、黄连清里燥湿止利，表里同治，主治表证未解、热陷阳明之协热下利。"},{"q":"补气生血的代表方剂是","o":["四物汤","当归补血汤","归脾汤","八珍汤","生脉散"],"a":1,"e":"当归补血汤重用黄芪五倍于当归，补气以生血，主治劳倦内伤、血虚发热，为补气生血之代表方。"},{"q":"左归丸组成中含有而右归丸组成中不含有的药物是","o":["枸杞子","龟板胶","鹿角胶","山茱萸","菟丝子"],"a":1,"e":"左归丸用龟板胶滋阴填精，右归丸改用鹿角胶温补精血，故龟板胶为左归丸有而右归丸无之品。"},{"q":"麦门冬汤组成中半夏与麦冬的用量比例为","o":["1∶2","1∶3","1∶5","1∶7","1∶9"],"a":3,"e":"麦门冬汤中麦门冬用七升、半夏用一升，二者用量为一比七，半夏降逆而不伤津，主治虚火咳逆。"},{"q":"大承气汤中含有的药对是","o":["大黄、甘草","附子、生姜","厚朴、枳壳","人参、当归","大黄、芒硝"],"a":4,"e":"大承气汤由大黄、芒硝、枳实、厚朴组成，大黄泻热、芒硝软坚，相须为用，为峻下热结之核心药对。"},{"q":"蒿芩清胆汤的功用是","o":["清泄三焦，舒畅气机","清胆利湿，和胃化痰","和解少阳，疏散郁热","疏肝理脾，健胃消食","温肝散寒，行气祛湿"],"a":1,"e":"蒿芩清胆汤以青蒿、黄芩清透少阳胆热，配竹茹、半夏、枳壳和胃化痰，碧玉散利湿，共奏清胆利湿、和胃化痰之功。"},{"q":"凉膈散中所含的“承气”汤是","o":["大承气汤","小承气汤","调胃承气汤","桃核承气汤","增液承气汤"],"a":2,"e":"凉膈散含大黄、芒硝、甘草三味，即调胃承气汤，配栀子、黄芩、连翘、薄荷、竹叶，泻火通便、清上泄下。"},{"q":"麻黄杏仁甘草石膏汤的功用是","o":["辛凉透表，清热解毒","疏风清热，宣肺止咳","辛凉疏表，清肺平喘","辛凉宣肺，清热解毒","宣利肺气，疏风止咳"],"a":2,"e":"麻黄杏仁甘草石膏汤以麻黄宣肺、石膏清肺，辛凉相合，主治外邪入里化热、肺热壅盛之喘咳。"},{"q":"橘皮竹茹汤的辨证要点是","o":["膈痞闷，脘腹胀痛，饮食不消","呃逆或呕吐，舌红嫩，脉虚数","胸中痞满，气从胁下冲逆，上攻心胸，舌苔白腻，脉沉弦或紧","少腹痛引睾丸，舌淡苔白，脉沉弦","胸膈满闷，痰多稀白，苔白滑或白腻"],"a":1,"e":"橘皮竹茹汤证为胃虚有热、气逆不降，故见呃逆或呕吐、舌红嫩、脉虚数，治宜降逆止呃、益气清热。"},{"q":"定喘汤适用于","o":["外感温燥，邪在肺卫","风寒客表，水饮内停","外感风寒，内伤湿滞","风寒外束，痰热内蕴","胸阳不振，痰浊中阻"],"a":3,"e":"定喘汤宣肺降气、清热化痰，主治风寒外束、痰热内蕴之哮喘，症见痰多色黄、微恶风寒、苔黄腻。"},{"q":"主治证病机为“素体阴虚，外感风热”的方剂是","o":["败毒散","参苏饮","麻黄附子细辛汤","再造散","加减葳蕤汤"],"a":4,"e":"加减葳蕤汤以葳蕤滋阴润燥，配葱白、淡豆豉、薄荷、桔梗、白薇，主治素体阴虚而外感风热之证。"},{"q":"槐花散的功效是","o":["凉血止血，利水通淋","温阳健脾，养血止血","清肠止血，疏风行气","清热解毒，凉血止痢","清热燥湿，调气和血"],"a":2,"e":"槐花散以槐花清肠凉血止血，侧柏叶、荆芥穗疏风止血，枳壳宽肠行气，共奏清肠止血、疏风行气之功。"},{"q":"玉屏风散的组成为","o":["黄芪、白术、甘草","白术、防风、黄芪","茯苓、白术、黄芪","黄芪、白术、人参","人参、白术、甘草"],"a":1,"e":"玉屏风散由黄芪、白术、防风三味组成，黄芪固表、白术健脾、防风走表祛风，益气固表而止汗。"},{"q":"真人养脏汤补涩不滞，是因为方中配伍了理气药","o":["陈皮","青皮","木香","砂仁","白豆蔻"],"a":2,"e":"真人养脏汤中木香行气导滞，与罂粟壳、诃子等收涩药相配，使补涩而不滞，故为方中调气之品。"},{"q":"苏子降气汤与定喘汤中共有的药物是","o":["当归、肉桂","苏子、半夏","厚朴、前胡","白果、麻黄","桑白皮、黄芩"],"a":1,"e":"苏子降气汤含紫苏子、半夏、厚朴、前胡等，定喘汤含苏子、半夏、麻黄、杏仁、黄芩等，共有苏子与半夏。"},{"q":"《金匮要略·呕吐哕下利病脉证治》：“哕逆者，（ ）主之。”","o":["吴茱萸汤","旋覆代赭汤","橘皮竹茹汤","炙甘草汤","小建中汤"],"a":2,"e":"《金匮要略》载“哕逆者，橘皮竹茹汤主之”，该方益气清热、降逆止呃，主治胃虚有热之呃逆。"},{"q":"下列各项方证中，无小便不利症状的是","o":["实脾散","真武汤","防己黄芪汤","猪苓汤","五苓散"],"a":0,"e":"实脾散主治脾肾阳虚、水湿内停之阴水，症见身半以下肿甚、胸腹胀满、大便溏薄；小便不利见于真武、五苓等方证。"},{"q":"川芎茶调散的君药是","o":["薄荷","川芎","荆芥","白芷","羌活"],"a":1,"e":"川芎茶调散以川芎为君，辛温香窜，上行头目，善祛风止痛；配荆芥、薄荷等疏风之品，共成疏风止痛之剂。"},{"q":"仙方活命饮中君药是","o":["当归","白芷","赤芍","穿山甲","金银花"],"a":4,"e":"仙方活命饮以金银花清热解毒为君，配穿山甲、皂角刺、白芷等消肿溃坚，主治阳证痈疡初起。"},{"q":"外感温燥，肺津受灼之轻证，宜选","o":["桑杏汤","清燥救肺汤","沙参麦冬汤","麦门冬汤","杏苏散"],"a":0,"e":"桑杏汤清宣温燥、润肺止咳，主治外感温燥、肺津受灼之轻证，见身热不甚、干咳无痰、右脉数大。"},{"q":"麻黄汤的臣药是","o":["麻黄","桂枝","杏仁","白芍","甘草"],"a":1,"e":"麻黄汤以麻黄发汗解表、宣肺平喘为君，桂枝解肌发表、温通经脉为臣，助麻黄发汗，杏仁、甘草为佐使。"},{"q":"小蓟饮子方中配伍当归的意义是","o":["养血和血，宁心安神","养血和血，引血归经","养血和血，调经止痛","养血和血，祛瘀生新","养血和血，缓急止痛"],"a":1,"e":"小蓟饮子中当归养血和血，引血归经，使止血而不留瘀，与生地、小蓟、藕节等凉血止血药相配。"},{"q":"下列属于四逆散组成的是","o":["枳壳","赤芍","柴胡","川芎","当归"],"a":2,"e":"四逆散由柴胡、芍药、枳实、甘草组成，柴胡疏肝解郁、透邪外出，与枳实升降并用，主治阳郁厥逆。"},{"q":"地黄饮子的功用中包括","o":["滋阴降火","乌发壮骨","理气","开窍化痰","安神益智"],"a":3,"e":"地黄饮子滋肾阴、补肾阳、开窍化痰，方中菖蒲、远志、茯苓交通心肾、开窍化痰，治下元虚衰之喑痱。"},{"q":"心火亢盛，耗伤阴血，心神失养而致心神烦乱，失眠多梦者，治疗最宜选用","o":["桂枝甘草龙骨牡蛎汤","珍珠母丸","磁朱丸","朱砂安神丸","生铁落饮"],"a":3,"e":"朱砂安神丸镇心安神、清热养血，主治心火亢盛、灼伤阴血所致心神烦乱、失眠多梦、舌尖红、脉细数。"},{"q":"龟鹿二仙胶组成中不包括","o":["鹿角","龟板","人参","枸杞子","生地黄"],"a":4,"e":"龟鹿二仙胶由鹿角、龟板、人参、枸杞子组成，填精补髓、益气壮阳，方中不用生地黄，主治真元虚损之羸瘦少气。"},{"q":"败毒散的组成中不含有","o":["枳壳","前胡","白前","柴胡","人参"],"a":2,"e":"败毒散由羌活、独活、柴胡、前胡、川芎、枳壳、桔梗、茯苓、人参、甘草、生姜、薄荷组成，方中无白前。"},{"q":"具有宣肺降气、清热化痰的功效的方剂是","o":["苏子降气汤","定喘汤","小青龙汤","麻黄汤","麻杏石甘汤"],"a":1,"e":"定喘汤宣肺降气、清热化痰，以麻黄宣肺散邪，黄芩、桑白皮清肺热，苏子、杏仁、半夏降气化痰。"},{"q":"主治热毒炽盛之脱疽的方剂是","o":["五味消毒饮","阳和汤","四妙勇安汤","仙方活命饮","苇茎汤"],"a":2,"e":"四妙勇安汤以金银花、玄参、当归、甘草四味，清热解毒、活血止痛，专治热毒炽盛之脱疽。"},{"q":"萆薢分清饮主治","o":["蓄水证","水热互结阴伤证","下焦虚寒之膏淋、白浊","中阳不足之痰饮","阳虚水泛证"],"a":2,"e":"萆薢分清饮温肾利湿、分清化浊，主治下焦虚寒、湿浊下注之膏淋、白浊，症见小便频数、浑浊如米泔。"},{"q":"以下哪一项不是方剂变化的形式","o":["药味增减变化","药量增减变化","药味、药量同时增减变化","治法更换变化","剂型更换变化"],"a":3,"e":"方剂变化的形式包括药味增减、药量增减、药味与药量同时增减及剂型更换；更换治法已属另立新方，不列为变化形式。"},{"q":"归脾汤中配伍茯神意在","o":["利水消肿","健脾渗湿","养心安神","渗湿止泻","涤痰除饮"],"a":2,"e":"归脾汤中茯神宁心安神，与远志、酸枣仁、龙眼肉相配，治心脾两虚之心悸失眠，非取其渗利之功。"},{"q":"丁香柿蒂汤中不含有","o":["丁香","柿蒂","人参","生姜","大枣"],"a":4,"e":"丁香柿蒂汤由丁香、柿蒂、人参、生姜组成，温中益气、降逆止呃，主治胃气虚寒之呃逆，方中不用大枣。"},{"q":"下列各项，其中哪项不是旋覆代赭汤用药","o":["旋覆花、代赭石","人参、生姜","半夏","柴胡、黄芩","炙甘草、大枣"],"a":3,"e":"旋覆代赭汤由旋覆花、代赭石、人参、半夏、生姜、甘草、大枣组成，益气降逆化痰，柴胡、黄芩非其用药。"},{"q":"被称为“仲景群方之冠”的方剂是","o":["正柴胡饮","麻黄汤","桂枝汤","小青龙汤","大青龙汤"],"a":2,"e":"桂枝汤调和营卫、解肌发表，配伍精当，被后世誉为“仲景群方之冠”，为治太阳中风之主方。"},{"q":"苏子降气汤的辨证要点是","o":["胸膈满闷，痰多稀白，苔白滑或白腻","哮喘咳嗽，痰多色黄，微恶风寒，苔黄腻，脉滑数","呕吐不渴，苔白滑","心下痞硬，嗳气频作，或呕吐，呃逆，苔白腻，脉缓或滑","呃逆或呕吐，舌红嫩，脉虚数"],"a":0,"e":"苏子降气汤证属上实下虚，痰涎壅盛于肺，故见胸膈满闷、痰多稀白、苔白滑或白腻，治宜降气平喘。"},{"q":"真人养脏汤的君药是","o":["肉豆蔻","罂粟壳","诃子","肉桂","人参"],"a":1,"e":"真人养脏汤重用罂粟壳涩肠止泻为君，配肉豆蔻、诃子温涩固脱，人参、白术、肉桂温补脾肾。"},{"q":"具有行气止痛，软坚散结功用的方剂为","o":["橘核丸","暖肝煎","天台乌药散","金铃子散","半夏厚朴汤"],"a":0,"e":"橘核丸以橘核、川楝子、海藻、昆布等行气止痛、软坚散结，主治寒湿疝气之睾丸肿胀偏坠。"},{"q":"下列不属于桑螵蛸散组成的是","o":["龙骨","鳖甲","菖蒲","远志","当归"],"a":1,"e":"桑螵蛸散由桑螵蛸、远志、菖蒲、龙骨、人参、茯神、当归、龟甲组成，调补心肾、涩精止遗，方中用龟甲而非鳖甲。"},{"q":"下列方剂中何方为“培土生金”法中的常用方剂","o":["补中益气汤","参苓白术散","归脾汤","生脉散","四君子汤"],"a":1,"e":"参苓白术散益气健脾、渗湿止泻，脾土健运则肺金得养，为培土生金法之常用方，多用于脾虚肺损之咳。"},{"q":"补阳还五汤原书用黄芪的量是","o":["一两","二两","三两","四两","五两"],"a":3,"e":"补阳还五汤原书黄芪用四两，大补元气以行血，配合活血通络之品，治气虚血瘀之半身不遂。"},{"q":"九仙散的君药是","o":["五味子","乌梅","罂粟壳","桔梗","人参"],"a":2,"e":"九仙散以罂粟壳为君，敛肺止咳，配乌梅、五味子、人参、阿胶等，主治久咳不已、气阴两伤。"},{"q":"主治证病机为“外感风寒，寒饮内停”的方剂是","o":["正柴胡饮","麻黄汤","桂枝汤","小青龙汤","大青龙汤"],"a":3,"e":"小青龙汤解表散寒、温肺化饮，主治外感风寒、寒饮内停之恶寒发热、无汗、咳喘、痰涎清稀而多泡沫。"},{"q":"具有“解表散寒，温肺化饮”功用的方剂是","o":["苓甘五味姜辛汤","苓桂术甘汤","小青龙汤","华盖散","参苏饮"],"a":2,"e":"小青龙汤以麻黄、桂枝解表散寒，干姜、细辛、半夏温肺化饮，五味子敛肺，共成解表散寒、温肺化饮之功。"},{"q":"滚痰丸中没有的药是","o":["大黄","礞石","沉香","瓜蒌仁","黄芩"],"a":3,"e":"滚痰丸由大黄、黄芩、礞石、沉香组成，泻火逐痰，主治实热老痰之癫狂惊悸，方中无瓜蒌仁。"},{"q":"下列各项中，属于羌活胜湿汤药物组成的是","o":["桑寄生","杜仲","白芷","秦艽","独活"],"a":4,"e":"羌活胜湿汤由羌活、独活、藁本、防风、甘草、蔓荆子、川芎组成，祛风胜湿止痛，主治风湿在表之头身重痛。"},{"q":"具有润肠泻热，行气通便功能的方剂是","o":["五仁丸","脾约丸","济川煎","黄龙汤","小承气汤"],"a":1,"e":"脾约丸即麻子仁丸，以麻子仁润肠，配大黄、枳实、厚朴泄热行气，主治肠胃燥热、脾约便秘。"},{"q":"表虚自汗证宜选用","o":["牡蛎散","青蒿鳖甲汤","桂枝汤","清骨散","玉屏风散"],"a":4,"e":"玉屏风散益气固表止汗，主治表虚自汗、易感风邪者，黄芪、白术、防风三药相配，补中有散。"},{"q":"具有凉血止血，利水通淋功效的方剂是","o":["小蓟饮子","五苓散","导赤散","八正散","猪苓汤"],"a":0,"e":"小蓟饮子凉血止血、利水通淋，以生地、小蓟、藕节凉血止血，滑石、木通、竹叶利水通淋，主治血淋尿血。"},{"q":"就方剂的组成而言，黄龙汤与乌梅丸共有的药物是","o":["附子、桂枝","人参、当归","黄连、黄柏","枳实、厚朴","生姜、大枣"],"a":1,"e":"黄龙汤含人参、当归、大黄、芒硝、枳实、厚朴等，乌梅丸含人参、当归、乌梅、黄连、黄柏等，二方共有者即人参、当归。"},{"q":"八法不包括的是","o":["补法","泻法","汗法","吐法","消法"],"a":1,"e":"八法为汗、吐、下、和、温、清、消、补，并无泻法之名，下法即寓泻之意，故泻法不属八法。"},{"q":"炙甘草汤的组成药物中含有","o":["麦冬、麻仁、枣仁","生地、元参、麦冬","阿胶、当归、芍药","生姜、大枣、黄芪","生地、阿胶、麦冬"],"a":4,"e":"炙甘草汤由炙甘草、生姜、人参、生地黄、桂枝、阿胶、麦门冬、麻仁、大枣加清酒组成，含生地、阿胶、麦冬。"},{"q":"牵正散证的病机是","o":["风邪初中头面经络","风湿阻于头面经络","风寒侵袭头面经络","风热侵袭头面经络","风痰阻于头面经络"],"a":4,"e":"牵正散以白附子、僵蚕、全蝎祛风化痰通络，证由风痰阻于头面经络，致口眼歪斜、面部肌肉抽动。"},{"q":"下列各项中，属于实脾散药物组成的是","o":["高良姜","大腹皮","砂仁","白芍","木瓜"],"a":4,"e":"实脾散由厚朴、白术、木瓜、木香、草果仁、大腹子、附子、茯苓、干姜、甘草组成，方中含木瓜。"},{"q":"以下关于天麻钩藤饮证的辨证要点描述错误的是","o":["头痛","眩晕","痉厥","失眠","脉弦"],"a":2,"e":"天麻钩藤饮证的辨证要点为头痛、眩晕、失眠、舌红苔黄、脉弦；痉厥乃热极动风、抽搐之象，非本方要点。"},{"q":"半夏泻心汤的功用是","o":["和胃消痞，散结除水","益气和胃，消痞止呕","寒热平调，散结除痞","平调寒热，理气和胃","泻火解毒，燥湿消痞"],"a":2,"e":"半夏泻心汤以半夏散结除痞，干姜、黄芩、黄连寒热平调，人参、大枣、甘草补中，主治寒热错杂之痞证。"},{"q":"中国历史上第一部由政府编制的成药药典是","o":["《五十二病方》","《太平惠民和剂局方》","《太平圣惠方》","《肘后备急方》","《普济方》"],"a":1,"e":"《太平惠民和剂局方》由宋代太医局编成，是我国第一部由政府颁行的成药药典，所收多为常用有效之剂。"},{"q":"何方主治营血虚滞证","o":["四物汤","归脾汤","当归补血汤","胶艾汤","八珍汤"],"a":0,"e":"四物汤补血调血，主治营血虚滞之面色无华、唇甲色淡、月经量少，为补血调血之基础方。"},{"q":"香薷散主治证为","o":["阴暑","阳暑","暑湿证","湿温证","暑温证"],"a":0,"e":"香薷散祛暑解表、化湿和中，主治夏月乘凉饮冷、外感于寒、内伤于湿之阴暑，症见恶寒发热、无汗、腹痛吐泻。"},{"q":"大秦艽汤与小续命汤组成中共有的药物是","o":["白芷、防风、细辛、生地","羌活、黄芩、川芎、麻黄","麻黄、杏仁、肉桂、甘草","川芎、黄芩、熟地、附子","黄芩、防风、川芎、甘草"],"a":4,"e":"大秦艽汤与小续命汤同含黄芩、防风、川芎、甘草，前者养血祛风，后者扶正祛风，主治各有侧重。"},{"q":"下列哪项不是脾约丸的组成药物","o":["芍药","大黄","芒硝","杏仁","枳实"],"a":2,"e":"麻子仁丸由麻子仁、芍药、枳实、大黄、厚朴、杏仁组成，润肠泄热、行气通便，方中不用芒硝。"},{"q":"蒿芩清胆汤中具有芳香透热作用的药物是","o":["淡竹茹","青子芩","陈广皮","青蒿脑","仙半夏"],"a":3,"e":"青蒿脑即青蒿之茎叶，芳香透达，善清透少阳胆经之热，为蒿芩清胆汤中透邪外出之品，使邪从表解。"},{"q":"功用为清宣温燥，润肺止咳的方剂是","o":["杏苏散","清燥救肺汤","麦门冬汤","桑杏汤","桑菊饮"],"a":3,"e":"桑杏汤清宣温燥、润肺止咳，以桑叶、杏仁、沙参、象贝、香豉、栀子皮、梨皮组方，治温燥伤肺之轻证。"},{"q":"主治妇人中风，热入血室而见经水适断，寒热发作有时的方剂是","o":["小柴胡汤","温经汤","逍遥散","血府逐瘀汤","青蒿鳖甲汤"],"a":0,"e":"妇人热入血室，经水适断、寒热发作有时，治宜和解少阳，小柴胡汤主之，使邪从少阳而解。"},{"q":"咳血方中用以清热化痰，止咳的药物是","o":["瓜蒌仁","薏苡仁","柏子仁","杏仁","胡麻仁"],"a":0,"e":"咳血方中瓜蒌仁清热化痰、润肺止咳，配青黛、栀子清肝泻火，海粉、诃子，主治肝火犯肺之咳血。"},{"q":"小蓟饮子与八正散共有的药物是","o":["小蓟、生地黄","生地黄、山栀子","滑石、山栀子","小蓟、大黄","大黄、淡竹叶"],"a":2,"e":"小蓟饮子含滑石、山栀子、木通、甘草等，八正散含滑石、山栀子、木通、大黄等，二方共有滑石与山栀子。"},{"q":"逍遥散中体现“实土以御木乘”的药物配伍是","o":["白术、茯苓、甘草","当归、白芍、大枣","柴胡、薄荷、生姜","白术、当归、柴胡","大枣、甘草、茯苓"],"a":0,"e":"逍遥散中白术、茯苓、甘草健脾益气，使脾土健运而不受肝木克伐，即“实土以御木乘”之意。"},{"q":"下列诸法中，不属于“八法”内容的是","o":["汗法、吐法","下法、清法","宣法、通法","清法、补法","和法、温法"],"a":2,"e":"八法指汗、吐、下、和、温、清、消、补八类治法，宣法、通法不在其列，系后世医家归纳之名。"},{"q":"蒿芩清胆汤中具有“导湿热从小便而去”作用的药物是","o":["木通、车前子","苍术、黄柏","茯苓、滑石","泽泻、防己","猪苓、薏苡仁"],"a":2,"e":"蒿芩清胆汤以茯苓健脾渗湿，碧玉散中滑石清热利水，使湿热从小便而去，故见小便色黄而短。"},{"q":"旋覆代赭汤主治","o":["胃虚痰阻证","脾虚生痰证","脾虚湿停证","胃虚有热呃逆证","胃气虚寒呃逆证"],"a":0,"e":"旋覆代赭汤益气降逆化痰，主治胃虚痰阻、气逆不降之噫气不除、心下痞硬，属胃虚痰阻证。"},{"q":"《温热经纬》清暑益气汤的主治证为","o":["暑湿证","暑热气津两伤证","暑温证","暑温夹湿证","阴暑"],"a":1,"e":"《温热经纬》清暑益气汤清暑益气、养阴生津，主治暑热耗伤气津之身热汗多、口渴心烦、体倦少气。"},{"q":"苏子降气汤的病变脏腑是","o":["脾肺","肺胃","脾肾","肺肾","脾肺肾"],"a":3,"e":"苏子降气汤证为上实下虚，痰涎壅盛于肺、肾阳不足于下，故病变脏腑在肺肾，治当降气平喘、温补下元。"},{"q":"组成中包括干姜与生姜的方剂为","o":["苏子降气汤","厚朴温中汤","暖肝煎","天台乌药散","枳实消痞丸"],"a":1,"e":"厚朴温中汤由厚朴、陈皮、甘草、茯苓、草豆蔻、木香、干姜、生姜组成，干姜、生姜并用，温中散寒、行气除满。"},{"q":"不属于黄连解毒汤主治证候的是","o":["大热烦躁","错语不眠","热病吐血","大便秘结","小便黄赤"],"a":3,"e":"黄连解毒汤泻火解毒，主治三焦火毒热盛之大热烦躁、错语不眠、吐衄发斑、小便黄赤，未见大便秘结。"},{"q":"白虎汤与竹叶石膏汤共有的药物是","o":["粳米","知母","人参","半夏","麦门冬"],"a":0,"e":"白虎汤与竹叶石膏汤同用石膏、知母、甘草、粳米四味，其中粳米益胃护津，为二方共有之品。"},{"q":"桂枝汤、小建中汤、当归四逆汤相同的药物是","o":["桂枝、芍药、甘草、大枣","桂枝、芍药、甘草、生姜","桂枝、芍药、生姜、大枣","芍药、甘草、生姜、大枣","桂枝、甘草、生姜、大枣"],"a":0,"e":"三方均有桂枝、芍药、甘草、大枣；桂枝汤另有生姜，小建中汤加饴糖，当归四逆汤加当归、细辛、通草。"},{"q":"四神丸的君药是","o":["肉豆蔻","五味子","吴茱萸","补骨脂","生姜"],"a":3,"e":"四神丸以补骨脂温肾暖脾、固涩止泻为君，配肉豆蔻、五味子、吴茱萸，佐生姜、大枣温养脾胃，主治五更肾泻。"},{"q":"六味地黄丸的臣药是","o":["山药、泽泻","山萸肉、牡丹皮","山药、山萸肉","泽泻、牡丹皮","牡丹皮、茯苓"],"a":2,"e":"六味地黄丸以熟地黄滋阴补肾为君，山茱萸养肝、山药补脾共为臣，泽泻、牡丹皮、茯苓为佐使之泻。"},{"q":"湿热食积，内阻胃肠证，治疗时当首选","o":["保和丸","木香导滞丸","健脾丸","枳实导滞丸","半夏泻心汤"],"a":3,"e":"枳实导滞丸以大黄、枳实、神曲攻积泄热，黄芩、黄连清热燥湿，茯苓、泽泻、白术利湿健脾，主治湿热食积。"},{"q":"十枣汤的最佳服药时间是","o":["饭后服","饭前服","平旦服","睡前服","不拘时服"],"a":2,"e":"十枣汤宜平旦空腹服，此时胃中空虚，药力易于吸收直达病所，且便于观察泻下程度以定后续用量。"},{"q":"主治“痛泻”的方剂是","o":["真人养脏汤","参苓白术散","痛泻要方","四神丸","乌梅丸"],"a":2,"e":"痛泻要方以白术健脾、白芍柔肝、陈皮理气、防风散肝舒脾，主治肝旺脾虚之腹痛肠鸣、痛则即泻。"},{"q":"五苓散与猪苓汤共同的药物是","o":["阿胶","泽泻","桂枝","滑石","白术"],"a":1,"e":"五苓散由猪苓、泽泻、白术、茯苓、桂枝组成，猪苓汤由猪苓、茯苓、泽泻、阿胶、滑石组成，共有泽泻。"},{"q":"止嗽散的功用是","o":["宣利肺气，缓急止痛","发汗解表，宣肺平喘","宣利肺气，疏风止咳","解表散寒，温肺化饮","发汗解表，降逆止咳"],"a":2,"e":"止嗽散以紫菀、百部润肺止咳，桔梗、白前宣降肺气，荆芥疏风，共奏宣利肺气、疏风止咳之功。"},{"q":"当归六黄汤中“六黄”是指","o":["黄芩、黄连、黄柏、黄芪、生地黄、熟地黄","黄芩、黄连、大黄、黄芪、生地黄、熟地黄","黄芩、黄连、大黄、麻黄、生地黄、熟地黄","黄芩、姜黄、大黄、麻黄、生地黄、熟地黄","黄柏、姜黄、大黄、麻黄、生地黄、熟地黄"],"a":0,"e":"当归六黄汤中“六黄”为黄芩、黄连、黄柏、黄芪、生地黄、熟地黄，功用滋阴泻火、固表止汗。"},{"q":"香薷散的功用是","o":["解表散寒，温肺化饮","发汗解表，兼清里热","祛暑解表，化湿和中","发汗祛湿，兼清里热","清暑益气，养阴生津"],"a":2,"e":"香薷散以香薷解表祛暑、化湿和中为君，配厚朴、白扁豆，主治夏月外感寒邪、内伤湿滞之阴暑。"},{"q":"《古今医鉴》所载参苓白术散，较《局方》参苓白术散方多何药","o":["木香","枳壳","半夏","苍术","陈皮"],"a":4,"e":"《古今医鉴》所载参苓白术散在《局方》基础上加陈皮，理气和胃，使补而不滞，余药相同。"},{"q":"具有益气生津，敛阴止汗作用的方剂是","o":["四君子汤","补中益气汤","桂枝汤","生脉散","牡蛎散"],"a":3,"e":"生脉散以人参益气、麦冬养阴生津、五味子敛肺止汗，主治气阴两伤之体倦气短、口渴自汗。"},{"q":"甘麦大枣汤的功用是","o":["养心安神，清热解毒","养心安神，健脾燥湿","养心安神，和中缓急","养血安神，定惊止痛","养心安神，缓急止痛"],"a":2,"e":"甘麦大枣汤以小麦养心安神，甘草、大枣甘润缓急，主治脏躁之精神恍惚、悲伤欲哭，功在养心安神、和中缓急。"},{"q":"苏子降气汤的组成中含有","o":["陈皮、苏子","枳壳、桔梗","当归、杏仁","百部、前胡","当归、肉桂"],"a":4,"e":"苏子降气汤由紫苏子、半夏、当归、甘草、前胡、厚朴、肉桂组成，加生姜、大枣、苏叶同煎，故含当归、肉桂。本方降气平喘、祛痰止咳，主治上实下虚之喘咳。"},{"q":"治疗温疟，应首选的方剂是","o":["白虎汤","达原饮","败毒散","白虎加桂枝汤","白虎加人参汤"],"a":3,"e":"温疟属里热炽盛兼夹表寒，症见热多寒少、骨节烦疼、时呕，治当清热透邪、通络达表，首选白虎加桂枝汤；白虎汤则主治阳明气分热盛而无表寒。"},{"q":"苏子降气汤、定喘汤共有的药物为","o":["前胡","白芥子","杏仁","厚朴","苏子"],"a":4,"e":"两方均用紫苏子降气平喘、化痰止咳。定喘汤另有麻黄、白果、款冬花，苏子降气汤另有前胡、厚朴、肉桂，故共有的药物为苏子。"},{"q":"四神丸的主治证是","o":["脾泄","肾泄","痛泄","虚痢","寒痢"],"a":1,"e":"四神丸由补骨脂、肉豆蔻、五味子、吴茱萸组成，温肾暖脾、固肠止泻，主治脾肾阳虚之肾泄，症见五更泄泻、不思饮食、腰酸肢冷。"},{"q":"温脾汤主治证候的病机是","o":["脾阳不足、寒积中阻","津枯肠燥、气机阻滞","饮食积滞、气机壅塞","里寒积滞、阳气不运","肾虚津亏、开合失司"],"a":0,"e":"温脾汤由大黄、附子、干姜、人参、芒硝、当归、甘草组成，攻下冷积与温补脾阳并行，主治脾阳不足、寒积中阻之腹痛便秘、脐下绞结。"},{"q":"参苓白术散在何方的基础上加砂仁、山药、莲子、白扁豆、薏苡仁、桔梗而成","o":["四君子汤","异功散","六君子汤","玉屏风散","补中益气汤"],"a":0,"e":"参苓白术散即四君子汤加山药、莲子、白扁豆、薏苡仁、砂仁、桔梗而成，益气健脾、渗湿止泻，主治脾胃气虚夹湿之食少便溏。"},{"q":"大补阴丸的脉象特点是","o":["脉沉细数","尺脉数而有力","尺脉数而无力","尺脉细数","脉虚数"],"a":1,"e":"大补阴丸滋阴降火，主治阴虚火旺之骨蒸潮热、盗汗遗精、咳嗽咯血，其脉象特点为尺脉数而有力，反映肾火偏亢而阴精亏虚。"},{"q":"温胆汤的功用是","o":["燥湿行气，软坚化痰","燥湿化痰，理气和中","理气化痰，和胃利胆","清热化痰，宽胸散结","温肺化痰，降逆消食"],"a":2,"e":"温胆汤由半夏、竹茹、枳实、陈皮、甘草、茯苓组成，功在理气化痰、和胃利胆，主治胆胃不和、痰热内扰之虚烦不眠、呕吐呃逆。"},{"q":"以“燥淫于内，治以苦温，佐以甘辛”为治则的方剂是","o":["桑杏汤","杏苏散","清燥救肺汤","百合固金汤","麦门冬汤"],"a":1,"e":"杏苏散为轻宣凉燥之方，遵“燥淫于内，治以苦温，佐以甘辛”之旨，用杏仁、苏叶、半夏、陈皮等苦温甘辛之品，外解风寒、内化痰湿。"},{"q":"主治“类中风”的代表方是","o":["大秦艽汤","牵正散","镇肝熄风汤","天麻钩藤饮","羚角钩藤汤"],"a":2,"e":"镇肝熄风汤由怀牛膝、代赭石、龙骨、牡蛎等组成，镇肝熄风、滋阴潜阳，为治类中风之代表方，症见头目眩晕、脑部热痛、心中烦热、脉弦长有力。"},{"q":"小陷胸汤之功用是","o":["清热化痰，宽胸散结","清热化痰，理气止咳","温肺散寒，涤痰化饮","燥湿化痰，平肝息风","荡涤实热，攻逐顽痰"],"a":0,"e":"小陷胸汤由黄连、半夏、瓜蒌实组成，清热化痰、宽胸散结，主治痰热互结之小结胸病，症见胸脘痞闷、按之则痛、舌苔黄腻、脉浮滑。"},{"q":"四逆散所治厥逆，正如李中梓云：“此证虽云四逆，必不甚冷，或指头微温，或脉不沉微，乃阴中涵阳之证，唯（ ），是为逆冷。”","o":["气不宣通","血不疏散","肾阳虚衰","阴血不濡","痰湿凝滞"],"a":0,"e":"四逆散证之厥逆由气机郁滞、阳气不达四末所致，故李中梓谓“唯气不宣通，是为逆冷”，治以透邪解郁、疏肝理脾，非阳虚寒盛之四逆。"},{"q":"用治风热湿毒，壅遏肠道之便血的方剂是","o":["理中丸","黄土汤","槐花散","十灰散","四生丸"],"a":2,"e":"槐花散清肠止血、疏风理气，主治风热湿毒壅遏肠道、损伤血络之肠风脏毒，症见便前出血、血色鲜红、舌红脉数。"},{"q":"缩泉丸的主治证是","o":["脾肾虚寒证","肝肾虚寒证","膀胱虚寒证","脾胃虚寒证","肠胃虚寒证"],"a":2,"e":"缩泉丸由益智仁、乌药、山药组成，温肾祛寒、缩尿止遗，主治膀胱虚寒之小便频数、遗尿，以尿频、舌淡、脉沉弱为辨证要点。"},{"q":"三仁汤中渗湿且能健脾的药物是","o":["杏仁","竹叶","滑石","薏仁","通草"],"a":3,"e":"三仁汤中薏苡仁甘淡微寒，既渗湿利水又能健脾，使湿邪从小便而去，与杏仁宣上、白蔻仁畅中相配，分消三焦湿浊。"},{"q":"治疗寒饮咳嗽的常用方是","o":["苓桂术甘汤","止嗽散","小青龙汤","苓甘五味姜辛汤","二陈汤"],"a":3,"e":"苓甘五味姜辛汤由茯苓、甘草、五味子、干姜、细辛组成，温肺化饮，主治寒饮咳嗽之咳痰清稀、胸满不舒；小青龙汤则兼解表寒。"},{"q":"猪苓汤证的病机是","o":["瘀热互结伤阴","痰热互结伤阴","水热互结伤阴","寒湿互结伤阴","湿热互结伤阴"],"a":2,"e":"猪苓汤由猪苓、茯苓、泽泻、阿胶、滑石组成，利水清热养阴，证属水热互结伤阴，症见小便不利、发热口渴、心烦不眠。"},{"q":"当归四逆汤中通草的作用是","o":["通经脉","通阳气","利水","清热","温阳"],"a":0,"e":"当归四逆汤中通草通利经脉、畅达血脉，与当归、桂枝相配，使寒邪去而血脉通，故其用为通经脉，非利水渗湿之品。"},{"q":"大蓟、小蓟并用的方剂是","o":["导赤散","小蓟饮子","槐花散","八正散","十灰散"],"a":4,"e":"十灰散由大蓟、小蓟、荷叶、侧柏叶、白茅根、茜草、山栀、大黄、牡丹皮、棕榈皮各等分烧灰存性组成，凉血止血，主治血热妄行之出血。"},{"q":"左归丸的证治要点是","o":["头目眩晕，腰膝酸软，舌光少苔，脉细","骨蒸潮热，舌红少苔，尺脉数而有力","头目眩晕， 腰酸腿软，舌淡少苔，脉细数","头目眩晕，胁肋疼痛，吞酸吐苦，舌红少津","腰痛脚弱，小便不利或反多，舌淡而胖，脉虚弱"],"a":0,"e":"左归丸纯甘壮水、填精益髓，主治真阴不足证，以头目眩晕、腰膝酸软、舌光少苔、脉细为证治要点，方中不用苦寒清火之品。"},{"q":"从组成药物看，小建中汤是由桂枝汤（ ）而成","o":["去芍药加饴糖","去芍药倍甘草","倍甘草加饴糖","倍甘草与芍药","倍芍药加饴糖"],"a":4,"e":"小建中汤即桂枝汤倍芍药加饴糖而成，倍芍药酸甘益阴、缓急止痛，饴糖温中补虚，使功用由解肌发表转为温中补虚、和里缓急。"},{"q":"黄土汤方中的黄芩为","o":["君药","臣药","佐制药","反佐药","使药"],"a":3,"e":"黄土汤中黄芩苦寒，为反佐药，既制约附子、白术之温燥，又清血中伏热，使温阳而不助火，与灶心黄土相配而标本兼顾。"},{"q":"朱砂安神丸的病位以（ ）为主","o":["肾","肺","肝","心","以上都不正确"],"a":3,"e":"朱砂安神丸由朱砂、黄连、炙甘草、生地黄、当归组成，镇心安神、清热养血，病位在心，主治心火亢盛、阴血不足之怔忡失眠。"},{"q":"使用理气剂的注意事项，下列哪项除外都是正确的","o":["辨清病变部位","辨清病变属性","辨疾病的内伤外感","理气药多芳香辛燥，易伤津耗气，其治可酌情配伍补益药","年老体弱、阴血不足、孕妇又有气郁、气逆者，应酌情减量，必须兼顾正气。"],"a":2,"e":"理气药多芳香辛燥，易伤津耗气，运用时须辨清病变部位与属性，并酌情配伍补益药；年老体弱、阴血不足及孕妇当减量兼顾正气。内伤外感之分不属其注意事项。"},{"q":"桑螵蛸散主要用治","o":["尿频遗尿","自汗盗汗","久泻久痢","崩漏带下","久咳肺虚"],"a":0,"e":"桑螵蛸散由桑螵蛸、远志、菖蒲、龙骨、人参、茯神、当归、龟甲组成，调补心肾、涩精止遗，主治心肾两虚之尿频遗尿、滑精、健忘。"},{"q":"下列各项中，属于独活寄生汤证辨证要点的是","o":["头身重痛","腰膝冷痛","全身酸痛","头痛恶寒","脉沉实"],"a":1,"e":"独活寄生汤祛风湿、止痹痛、益肝肾、补气血，主治痹证日久、肝肾两虚、气血不足证，以腰膝冷痛、屈伸不利、畏寒喜温为辨证要点。"},{"q":"清气化痰丸用法中以何为小丸","o":["水","酒","姜汁","藕汁","乳汁"],"a":2,"e":"清气化痰丸以姜汁为小丸，取姜汁降逆化痰、制约半夏之燥，并助清胆胃之热。方由胆南星、瓜蒌仁、黄芩、半夏、陈皮、枳实、茯苓、杏仁组成。"},{"q":"桂枝茯苓丸的功用是","o":["温经通阳，健脾益气","健脾利水，解肌发表","活血祛瘀，健脾利水","活血化瘀，缓消癥块","消癥除痞，益气温阳"],"a":3,"e":"桂枝茯苓丸由桂枝、茯苓、牡丹皮、桃仁、芍药组成，活血化瘀、缓消癥块，主治瘀阻胞宫之妇人素有癥块、妊娠漏下不止、血色紫黑晦暗。"},{"q":"痛泻要方与固冲汤共用的药物是","o":["陈皮、防风","白术、白芍","白术、山萸肉","黄芪、白术","茜草、甘草"],"a":1,"e":"两方均用白术、白芍。痛泻要方以白术健脾、白芍柔肝，配防风、陈皮祛湿止泻；固冲汤以白术、黄芪补气，白芍、山萸肉敛阴固冲。"},{"q":"治疗实证水肿，首选方剂是","o":["五苓散","真武汤","大青龙汤","大陷胸汤","十枣汤"],"a":4,"e":"十枣汤由甘遂、大戟、芫花研末，以大枣十枚煎汤送服，攻逐水饮，主治悬饮及水肿实证，症见咳唾胸胁引痛、水肿腹胀、二便不利。"},{"q":"六味地黄丸的功用是","o":["养心安神","滋阴补肾","健脾和胃","滋阴疏肝","滋阴降火"],"a":1,"e":"六味地黄丸由熟地黄、山茱萸、山药、泽泻、牡丹皮、茯苓组成，三补三泻而以补为主，功用滋阴补肾，主治肾阴虚之腰膝酸软、头晕耳鸣、舌红少苔。"},{"q":"应用开窍剂，首先应辨清","o":["实证和虚证","表证和里证","闭证和脱证","阴证和阳证","寒证和热证"],"a":2,"e":"开窍剂适用于邪闭心窍之神昏，运用时首辨闭证与脱证：闭证宜开，脱证当固，误投开窍之品反耗散正气。闭证之中又分温热与寒湿。"},{"q":"金锁固精丸的组成中除莲须、莲子粉、煅龙骨、煅牡蛎外还有","o":["桑螵蛸、益智仁","菖蒲、远志","乌药、山药","沙苑子、芡实","山药、芡实"],"a":3,"e":"金锁固精丸由沙苑子、芡实、莲须、莲子粉、煅龙骨、煅牡蛎组成，补肾涩精，主治肾虚精关不固之遗精滑泄、腰痛耳鸣、舌淡苔白。"},{"q":"治疗伤寒邪在少阳、肝脾不和、寒热错杂的方剂属于","o":["解表剂","和解剂","清热剂","补益剂","理气剂"],"a":1,"e":"和解剂用以治疗伤寒邪在少阳、肝脾不和、寒热错杂之证，代表方如小柴胡汤、逍遥散、半夏泻心汤，共奏和解少阳、调和肝脾、平调寒热之功。"},{"q":"半夏白术天麻汤中治疗风痰眩晕头痛之要药是","o":["半夏、橘红","半夏、白术","白术、天麻","半夏、天麻","天麻、橘红"],"a":3,"e":"半夏燥湿化痰、降逆止呕，天麻平肝息风而止头眩，二药相合为治风痰眩晕头痛之要药，构成“化痰息风”的核心配伍。"},{"q":"应用天王补心丹的辨证要点是","o":["失眠，惊悸，舌红，脉细数","失眠心悸，手足心热，舌红少苔，脉细数","虚烦失眠，咽干口燥，舌红，脉弦细","精神恍惚，悲伤欲哭，舌红苔少，脉细","心悸失眠，体倦食少，舌淡，脉细弱"],"a":1,"e":"天王补心丹滋阴养血、补心安神，主治心肾阴亏、虚火内扰证，以失眠心悸、手足心热、舌红少苔、脉细数为辨证要点。"},{"q":"回阳救急汤中不需煎煮的药物是","o":["五味子","麝香","茯苓","陈皮","肉桂"],"a":1,"e":"回阳救急汤中麝香芳香走窜、通行十二经，宜临服时调入，取其速达病所、助参附回阳救逆，故不需煎煮。"},{"q":"大青龙汤的组成是","o":["麻黄汤倍用麻黄、甘草，减少杏仁用量，再加石膏、生姜、大枣","麻黄汤倍用麻黄、甘草，增加杏仁用量，再加石膏、生姜、大枣","麻黄汤倍用桂枝、甘草，减少杏仁用量，再加石膏、生姜、大枣","麻黄汤倍用麻黄、甘草，减少杏仁用量，再加石膏、干姜、大枣","麻黄汤倍用麻黄、甘草，增加杏仁用量，再加石膏、干姜、大枣"],"a":0,"e":"大青龙汤即麻黄汤倍用麻黄、甘草，减少杏仁用量，再加石膏、生姜、大枣而成，发汗解表兼清里热，主治外感风寒、内有蕴热之表寒里热证。"},{"q":"当归四逆汤组成中没有","o":["细辛","通草","大枣","川芎","甘草"],"a":3,"e":"当归四逆汤由当归、桂枝、芍药、细辛、甘草、通草、大枣组成，温经散寒、养血通脉，方中并无川芎。"},{"q":"以活血祛瘀，行气止痛为主要功效的方剂是","o":["温经汤","失笑散","金铃子散","桂枝茯苓丸","血府逐瘀汤"],"a":4,"e":"血府逐瘀汤由桃红四物汤合四逆散加桔梗、牛膝组成，活血祛瘀、行气止痛，主治胸中血瘀之胸痛头痛日久、痛如针刺而有定处。"},{"q":"下列药物，哪一组为健脾丸的组成","o":["白术、甘草、黄芩、谷芽、砂仁、神曲、山楂、山药","白术、茯苓、人参、木香、黄连、神曲、砂仁、山楂","黄连、木香、肉豆蔻、玄参、苍术、神曲、山药、麦芽","人参、山药、白术、麦芽、陈皮、砂仁、香附、神曲","茯苓、人参、甘草、黄芪、黄连、神曲、肉豆蔻、木香"],"a":1,"e":"健脾丸由白术、茯苓、人参、甘草、山药、木香、黄连、神曲、山楂、麦芽、砂仁、陈皮、肉豆蔻组成，健脾和胃、消食止泻。"},{"q":"龟鹿二仙胶的组成中有","o":["鹿角","黄芪","桃仁","红花","生地黄"],"a":0,"e":"龟鹿二仙胶由鹿角、龟甲、人参、枸杞子组成，填精补髓、益气壮阳，主治真元虚损、精血不足之全身瘦削、腰膝酸软、两目昏花。"},{"q":"体现“疏柔合法，肝脾同调，气血兼顾”配伍特点的方剂是","o":["小柴胡汤","柴胡疏肝散","越鞠丸","逍遥散","四逆散"],"a":3,"e":"逍遥散以柴胡疏肝解郁，当归、白芍养血柔肝，配白术、茯苓、甘草健脾，少佐生姜、薄荷助疏散，体现疏柔合法、肝脾同调、气血兼顾。"},{"q":"小柴胡汤与桂枝汤共用的药物是","o":["柴胡、桂枝","人参、甘草","生姜、大枣","半夏、白芍","黄芩、大枣"],"a":2,"e":"小柴胡汤由柴胡、黄芩、人参、半夏、甘草、生姜、大枣组成，桂枝汤由桂枝、芍药、甘草、生姜、大枣组成，两方共有生姜、大枣、甘草。"},{"q":"清燥救肺汤中用量最大的药物是","o":["石膏","麦冬","人参","阿胶","桑叶"],"a":4,"e":"清燥救肺汤中桑叶用量最大，取其轻宣肺燥、透邪外出而为君药，石膏、麦冬、阿胶、人参等用量均小于桑叶。"},{"q":"治疗暑湿证的基础方剂是","o":["香薷散","六一散","生脉散","竹叶石膏汤","白虎汤"],"a":1,"e":"六一散由滑石六份、甘草一份组成，清暑利湿，为治疗暑湿证之基础方，症见身热烦渴、小便不利或泄泻。"},{"q":"凉膈散的功用是","o":["辛凉透表，清热解毒","泻火通便，清上泄下","辛凉疏表，清肺平喘","清热解毒，疏风散邪","清热解毒，凉血泻火"],"a":1,"e":"凉膈散由连翘、黄芩、栀子、薄荷、大黄、芒硝、甘草、白蜜组成，泻火通便、清上泄下，主治上中二焦邪郁生热之证。"},{"q":"具有攻下热结，益气养血功用的方剂是","o":["脾约丸","五仁丸","十枣汤","济川煎","黄龙汤"],"a":4,"e":"黄龙汤由大承气汤加人参、当归、甘草、桔梗、生姜、大枣组成，攻下热结兼益气养血，主治阳明腑实而气血两亏之证。"},{"q":"下列不属于苏子降气汤主治证临床表现的症状是","o":["痰涎壅盛","喘咳短气","腰痛脚软","肢体浮肿","头晕目眩"],"a":4,"e":"苏子降气汤主治上实下虚之喘咳，症见痰涎壅盛、喘咳短气、胸膈满闷、腰痛脚软、肢体浮肿，头晕目眩不属其临床表现。"},{"q":"肾气丸比六味地黄丸多的药是","o":["薯蓣、山茱萸","山药、泽泻","茯苓、牡丹皮","桂枝、附子","肉桂、附子"],"a":3,"e":"肾气丸即六味地黄丸加桂枝、附子，少火生气、温补肾阳，主治肾阳不足之腰痛脚软、小便不利或反多、舌淡而胖、脉虚弱。"},{"q":"参苓白术散的组成中有","o":["人参、麦芽","白术、神曲","茯苓、半夏","茯苓、山药","人参、黄芪"],"a":3,"e":"参苓白术散由四君子汤加山药、莲子、白扁豆、薏苡仁、砂仁、桔梗组成，故含茯苓、山药，功在益气健脾、渗湿止泻。"},{"q":"旋覆代赭汤主治病证是","o":["中虚痰阻气逆证","脾虚生痰证","脾虚食停证","胃虚有热呃逆证","胃气虚寒呃逆证"],"a":0,"e":"旋覆代赭汤由旋覆花、代赭石、人参、半夏、生姜、甘草、大枣组成，降逆化痰、益气和胃，主治胃虚痰阻气逆之噫气不除、心下痞硬。"},{"q":"生脉散的组成为","o":["人参、白术、甘草","人参、麦门冬、五味子","五味子、麦门冬、甘草","知母、人参、杏仁","知母、人参、五味子"],"a":1,"e":"生脉散由人参、麦门冬、五味子组成，益气生津、敛阴止汗，主治气阴两伤之体倦气短、口渴自汗、脉虚细。"},{"q":"大青龙汤主治证候的病机是","o":["外感风寒，营卫不和","外感风寒湿邪，内有蕴热","外感风寒，内有蕴热","外感风寒，肺气失宣","外感风寒，水饮内停"],"a":2,"e":"大青龙汤证为外感风寒、内有蕴热，症见恶寒发热、身疼痛、无汗而烦躁，故倍用麻黄发汗，加石膏清泄里热。"},{"q":"半夏白术天麻汤与定痫丸主治证的病机是","o":["脾虚生痰","肝风夹痰","上扰清窍","蔽阻心窍","痰阻经络"],"a":1,"e":"两方主治证均以肝风夹痰为病机：半夏白术天麻汤治风痰上扰之眩晕头痛，定痫丸治风痰闭阻之神昏抽搐，皆取化痰息风之法。"},{"q":"具有补血和血功用的方剂是","o":["当归补血汤","归脾汤","八珍汤","四物汤","胶艾汤"],"a":3,"e":"四物汤由熟地黄、当归、白芍、川芎组成，补血调血，为补血和血之基础方，主治营血虚滞之面色无华、唇甲色淡、月经不调。"},{"q":"以下关于川芎茶调散证的辨证要点描述错误的是","o":["头痛","咳嗽","鼻塞","脉浮","苔薄"],"a":1,"e":"川芎茶调散证属外感风邪头痛，以头痛、鼻塞、脉浮、苔薄为辨证要点，咳嗽不属其主症。"},{"q":"属于白虎汤组成药物的是","o":["黄芩","秫米","糯米","粳米","贝母"],"a":3,"e":"白虎汤由石膏、知母、甘草、粳米组成，清热生津，主治阳明气分热盛证，粳米、甘草益胃护津，使大寒之品不伤中州。"},{"q":"六一散中甘草与滑石的用量比例是","o":["6∶1","5∶1","3∶1","1∶6","1∶1"],"a":3,"e":"六一散中滑石与甘草的用量比例为六比一，故名六一，滑石清热利湿，甘草和中，使利湿而不伤正。"},{"q":"枳实导滞丸之君药是","o":["枳实","大黄","厚朴","枳实、大黄","神曲、大黄"],"a":1,"e":"枳实导滞丸中大黄用量最重，攻积泻热、荡涤肠胃，为君药；枳实、神曲、黄芩、黄连、茯苓、白术、泽泻共为辅佐。"},{"q":"清燥救肺汤的组成药物是","o":["桑叶","苏叶","瓜蒌","沙参","贝母"],"a":0,"e":"清燥救肺汤由桑叶、石膏、麦冬、阿胶、胡麻仁、杏仁、枇杷叶、人参、甘草组成，其中桑叶轻宣燥热、透邪外出而为君药。"},{"q":"主治血虚外感风寒证的方剂是","o":["败毒散","参苏饮","葱白七味饮","麻黄附子细辛汤","加减葳蕤汤"],"a":2,"e":"葱白七味饮由葱白、葛根、豆豉、生姜、麦冬、干地黄、劳水组成，养血解表，主治血虚外感风寒证，症见头痛身热、微寒无汗。"},{"q":"贝母瓜蒌散组成中无","o":["贝母","瓜蒌","茯苓","橘红","甘草"],"a":4,"e":"贝母瓜蒌散由贝母、瓜蒌、天花粉、茯苓、橘红、桔梗组成，润肺清热、理气化痰，方中不用甘草。"},{"q":"黄土汤治证的病机是","o":["脾阳不足，统摄失常","气虚不固，统摄失常","气血两亏，统摄失常","血热妄行，统摄失常","心脾两虚，统摄失常"],"a":0,"e":"黄土汤证由脾阳不足、统摄失职而致，症见大便下血、血色暗淡、四肢不温、舌淡苔白、脉沉细无力，治以温阳健脾、养血止血。"},{"q":"炙甘草汤之君药是","o":["炙甘草","生地黄","麦门冬","人参","桂枝"],"a":1,"e":"炙甘草汤重用生地黄一斤，滋阴养血、充脉复脉，为君药；炙甘草益气补中，与人参、大枣共为臣佐。"},{"q":"桂枝汤的功用是","o":["发汗解表，缓急止痛","发汗解表，宣肺平喘","解肌发表，调和营卫","温经散寒，养血通脉","发汗解表，平冲降逆"],"a":2,"e":"桂枝汤由桂枝、芍药、甘草、生姜、大枣组成，解肌发表、调和营卫，主治外感风寒表虚证之头痛发热、汗出恶风、脉浮缓。"},{"q":"何方最能体现王冰所谓“益火之源，以消阴翳”之意","o":["白虎汤","地黄饮子","右归丸","左归丸","四逆汤"],"a":2,"e":"右归丸温补肾阳、填精补血，于大队滋阴填精药中配伍附子、肉桂，取“益火之源，以消阴翳”之义，主治肾阳不足、命门火衰证。"},{"q":"龙骨、牡蛎并用的方是","o":["桑螵蛸散","金锁固精丸","真人养脏汤","缩泉丸","牡蛎散"],"a":1,"e":"金锁固精丸中煅龙骨、煅牡蛎并用，收敛固涩以涩精止遗，与沙苑子、芡实、莲须相配，主治肾虚不固之遗精滑泄。"},{"q":"具有逐瘀泻热功用的方剂是","o":["桃核承气汤","血府逐瘀汤","复元活血汤","补阳还五汤","生化汤"],"a":0,"e":"桃核承气汤由桃仁、大黄、桂枝、芒硝、甘草组成，逐瘀泻热，主治下焦蓄血证之少腹急结、小便自利、其人如狂。"},{"q":"泻痢日久，每伤阴血，真人养脏汤中养血和血的药物是","o":["当归、白芍","生地、当归","生地、白芍","当归、阿胶","生地、阿胶"],"a":0,"e":"真人养脏汤中当归、白芍养血和血，与人参、白术、肉豆蔻、肉桂相配，涩肠止泻而不伤阴血，主治脾肾虚寒之久泻久痢。"},{"q":"下列选项中，不属于八珍汤药物组成的是","o":["人参、白术","当归、川芎","白芍、甘草","茯苓、熟地","黄芪、肉桂"],"a":4,"e":"八珍汤由四君子汤合四物汤组成，即人参、白术、茯苓、甘草、当归、川芎、白芍、熟地黄，不含黄芪、肉桂，后者为十全大补汤所加。"},{"q":"炙甘草汤的功用是","o":["益气补血，健脾养心","益气补血","滋阴养血，益气温阳，复脉定悸","营血虚滞","益气健脾，养血安胎"],"a":2,"e":"炙甘草汤滋阴养血、益气温阳、复脉定悸，主治阴血阳气虚弱、心脉失养之脉结代、心动悸、虚羸少气。"},{"q":"下列各项中，均属于独活寄生汤药物组成的是","o":["独活、羌活、细辛","杜仲、牛膝、桑寄生","熟地黄、当归、芍药","人参、白术、甘草","独活、桂枝、防风"],"a":1,"e":"独活寄生汤由独活、桑寄生、杜仲、牛膝、细辛、秦艽、防风、肉桂心、茯苓、当归、川芎、芍药、干地黄、人参、甘草组成，故含杜仲、牛膝、桑寄生。"},{"q":"甘露消毒丹的功用是","o":["利湿化浊，清热凉血","利湿化浊，清热泻火","利湿化浊，清热解毒","利湿化浊，清热利咽","利湿化浊，清热通络"],"a":2,"e":"甘露消毒丹利湿化浊、清热解毒，主治湿温时疫、邪在气分之发热倦怠、胸闷腹胀、身目发黄、咽喉肿痛、颐肿口渴。"},{"q":"独活寄生汤证主治","o":["风寒湿痹","风湿热痹","顽痹","风湿犯表之痹证","外感风寒湿、里有蕴热证"],"a":2,"e":"独活寄生汤主治痹证日久、正虚邪恋之顽痹，症见腰膝冷痛、屈伸不利、麻木不仁，治以祛风湿、止痹痛、益肝肾、补气血。"},{"q":"组成药物中无山栀子的方剂是","o":["十灰散","咳血方","小蓟饮子","茵陈蒿汤","槐花散"],"a":4,"e":"槐花散由槐花、侧柏叶、荆芥穗、枳壳组成，清肠止血、疏风理气，主治肠风脏毒下血，方中不含山栀子。"},{"q":"消风散的功用是","o":["祛风散邪，清热利湿","养血祛风，散热除湿","疏风祛邪，清热除湿","疏风养血，清热除湿","养血疏风，清热利湿"],"a":3,"e":"消风散疏风养血、清热除湿，主治风疹湿疹由风湿热邪侵袭所致者，方中当归、生地、胡麻仁养血润燥，取“治风先治血”之意。"},{"q":"大黄附子汤的功用是","o":["温里散寒，通便止痛","攻下冷积，温补脾阳","温阳补血，散寒通滞","温经通脉，养血止血","润肠通便，行气止痛"],"a":0,"e":"大黄附子汤由大黄、附子、细辛组成，温里散寒、通便止痛，主治寒积里实证之腹痛便秘、胁下偏痛、发热、手足厥冷。"},{"q":"槐花散的药物组成是","o":["槐花、地榆、荆芥穗、枳实","槐花、侧柏叶、荆芥穗、枳壳","槐花、侧柏叶、防风、枳壳","槐花、荷叶、荆芥穗、枳壳","槐花、地榆、荆芥穗、枳壳"],"a":1,"e":"槐花散由槐花、侧柏叶、荆芥穗、枳壳四味组成，槐花清肠凉血止血，侧柏叶助凉血，荆芥穗疏风，枳壳宽肠行气。"},{"q":"黄芪桂枝五物汤中具有补在表之卫气的药物是","o":["桂枝","黄芪","大枣","芍药","生姜"],"a":1,"e":"黄芪桂枝五物汤中黄芪甘温，补在表之卫气，益气温阳以行血痹，与桂枝、芍药、生姜、大枣相配，主治血痹之肌肤麻木不仁。"},{"q":"四磨饮子的组成中不含有","o":["人参","槟榔","沉香","乌药","当归"],"a":4,"e":"四磨饮子由人参、槟榔、沉香、乌药组成，行气降逆、宽胸散结，主治肝气郁结之胸膈烦闷、上气喘急、心下痞满，方中不用当归。"},{"q":"不属于清燥救肺汤主治证候的是","o":["头痛身热，胸膈满闷","干咳无痰，气逆而喘","咽喉干燥，口渴鼻燥","烦渴饮引，小便频数","舌红少苔，脉虚大而数"],"a":3,"e":"清燥救肺汤主治温燥伤肺之干咳无痰、气逆而喘、咽喉干燥、鼻燥、头痛身热、舌红少苔、脉虚大而数，烦渴引饮、小便频数属消渴之象。"},{"q":"生脉散中用人参的作用是","o":["益气生津，补养肺气","补益正气，扶正祛邪","大补元气，滋补后天","补中益气，升阳举陷","补气生血，强壮脾胃"],"a":0,"e":"生脉散中人参甘温，益气生津、补养肺气，使气旺则津生，与麦冬养阴、五味子敛肺相合，共成益气生津、敛阴止汗之功。"},{"q":"症见肢节沉重肿痛，苔白腻微黄，脉数者，治宜","o":["利湿清热，理气和中","利湿清热，舒筋壮骨","利湿清热，宣畅气机","利湿清热，疏风止痛","利湿清热，通络止痛"],"a":3,"e":"肢节沉重肿痛、苔白腻微黄、脉数，属风湿热邪痹阻经络，治宜利湿清热、疏风止痛，使湿去热清、经络通畅而痛止。"},{"q":"可用于脾阳不足之肌衄证的方剂是","o":["理中汤","四物汤","四神丸","四君子汤","七厘散"],"a":0,"e":"理中汤温中祛寒、补气健脾，脾阳不足则统摄无权而血溢脉外，故可用治阳虚失血之肌衄、便血，体现温中摄血之法。"},{"q":"咳血方的病机是","o":["肺经实火，损伤肺络","阴虚火旺，损伤肺络","肺中伏火，损伤肺络","血热妄行，损伤肺络","肝火犯肺，损伤肺络"],"a":4,"e":"咳血方证由肝火犯肺、灼伤肺络而致，症见咳嗽痰中带血、心烦易怒、口苦、颊赤、舌红苔黄，治以清肝宁肺、凉血止血。"},{"q":"以自利清水，脘腹胀痛，身热口渴，神倦少气，舌苔焦黄，脉虚为辨证要点的方剂是","o":["黄龙汤","调胃承气汤","济川煎","脾约丸","大承气汤"],"a":0,"e":"黄龙汤证见自利清水、脘腹胀痛、身热口渴、神倦少气、舌苔焦黄、脉虚，属阳明腑实兼气血两亏之热结旁流，治当攻补兼施。"},{"q":"组成中含有地龙的方剂是","o":["血府逐瘀汤","补阳还五汤","复元活血汤","温经汤","生化汤"],"a":1,"e":"补阳还五汤由黄芪、当归尾、赤芍、地龙、川芎、桃仁、红花组成，补气活血通络，主治气虚血瘀之中风半身不遂、口眼歪斜。"},{"q":"咳血方的组成药物中无","o":["龙胆草","青黛","海粉","诃子","山栀子"],"a":0,"e":"咳血方由青黛、瓜蒌仁、海粉、山栀子、诃子组成，清肝宁肺、凉血止血，方中清肝降火用青黛、栀子，不含龙胆草。"},{"q":"七宝美髯丹的组成中包括","o":["熟地黄","鹿角胶","龟板胶","人参","枸杞子"],"a":4,"e":"七宝美髯丹由何首乌、牛膝、当归、枸杞子、菟丝子、补骨脂、茯苓组成，补益肝肾、乌发壮骨，主治肝肾不足之须发早白、脱发齿摇。"},{"q":"小陷胸汤组成中有","o":["半夏","黄芩","黄柏","紫苏子","莱菔子"],"a":0,"e":"小陷胸汤由黄连、半夏、瓜蒌实组成，清热化痰、宽胸散结，半夏降逆消痞，与黄连、瓜蒌相配，主治痰热互结之小结胸证。"},{"q":"炙甘草是四逆汤中的","o":["反佐药","佐制药","佐助药","佐使药","臣佐药"],"a":3,"e":"四逆汤中炙甘草益气补中，既助附子、干姜回阳救逆，又制约其峻烈并调和诸药，为佐使药，使温阳而无伤正之弊。"},{"q":"下列各项中，属于萆薢分清饮药物组成的是","o":["益智仁","醋香附","川厚朴","远志","山药"],"a":0,"e":"萆薢分清饮由萆薢、益智仁、石菖蒲、乌药组成，温肾利湿、分清化浊，主治虚寒白浊之小便频数、浑浊不清、白如米泔。"},{"q":"不属于龙胆泻肝汤主治证候的是","o":["肝火上炎之胁痛","肝火上炎之目赤","肝火上炎之耳肿","肝火犯胃之呕吐吞酸","肝经湿热下注之阴肿"],"a":3,"e":"龙胆泻肝汤清肝胆实火、利下焦湿热，主治肝火上炎之头痛目赤、耳肿耳聋、胁痛，及肝经湿热下注之阴肿阴痒、带下；呕吐吞酸属左金丸证。"},{"q":"主治火毒结聚之疔疮的方剂是","o":["仙方活命饮","五味消毒饮","四妙勇安汤","阳和汤","大黄牡丹汤"],"a":1,"e":"五味消毒饮由金银花、野菊花、蒲公英、紫花地丁、紫背天葵组成，清热解毒、消散疔疮，主治火毒结聚之疔疮初起。"},{"q":"咳血方的功效是","o":["滋阴清热，凉血止血","泻肺泄热，凉血止血","清肝宁肺，凉血止血","养阴润肺，止咳化痰","清心宁肺，养阴止血"],"a":2,"e":"咳血方清肝宁肺、凉血止血，主治肝火犯肺之咳血，症见咳嗽痰稠带血、心烦易怒、口苦、舌红苔黄、脉弦数。"},{"q":"痛泻要方的功用是","o":["温补脾肾，涩肠止泻","清热燥湿，厚肠止泻","清热解毒，凉血止痢","补脾柔肝，祛湿止泻","健脾和中，渗湿止泻"],"a":3,"e":"痛泻要方由白术、白芍、陈皮、防风组成，补脾柔肝、祛湿止泻，主治脾虚肝旺之痛泻，症见肠鸣腹痛、痛则泄泻、泻后痛减。"},{"q":"六味地黄丸加何药为都气丸","o":["枸杞子","五味子","麦门冬","知母","黄柏"],"a":1,"e":"六味地黄丸加五味子名都气丸，纳气归肾，主治肾虚气喘、呃逆；加知母、黄柏为知柏地黄丸，加枸杞子、菊花为杞菊地黄丸。"},{"q":"川芎茶调散配伍的臣药是","o":["薄荷、防风","荆芥、羌活","防风、白芷","薄荷、荆芥","羌活、白芷"],"a":3,"e":"川芎茶调散中川芎为君，薄荷、荆芥辛散上行，助君药疏风止痛而为臣药；羌活、白芷、细辛、防风则分治诸经头痛。"},{"q":"六味地黄丸中用量最大的药物是","o":["熟地黄","山茱萸","山药","茯苓","泽泻"],"a":0,"e":"六味地黄丸中熟地黄用量八两为最多，滋阴补肾、填精益髓而为君药；山茱萸、山药各四两，泽泻、茯苓、牡丹皮各三两。"},{"q":"症见喉间起白如腐，不易拭去，咽喉肿痛，鼻干唇燥，呼吸有声，宜选的方剂是","o":["百合固金汤","当归六黄汤","清燥救肺汤","玉液汤","养阴清肺汤"],"a":4,"e":"喉间白腐不易拭去、咽喉肿痛、鼻干唇燥、呼吸有声，为白喉阴虚燥热之象，治宜养阴清肺、解毒利咽，首选养阴清肺汤。"},{"q":"方剂中针对兼病或兼证起主要治疗作用的药物是","o":["臣药","佐助药","使药","反佐药","佐制药"],"a":0,"e":"臣药有二义：辅助君药加强治疗主病主证，以及针对兼病或兼证起主要治疗作用，故所问为臣药。"},{"q":"槐花散的组成药物中无以下哪种药物","o":["侧柏叶","荆芥穗","枳壳","槐花","地榆"],"a":4,"e":"槐花散由槐花、侧柏叶、荆芥穗、枳壳组成，清肠止血、疏风理气，主治肠风脏毒下血，方中未用地榆。"},{"q":"肾气丸中山茱萸与附子的用量比例是","o":["8∶1","6∶1","2∶1","3∶1","4∶1"],"a":4,"e":"肾气丸中干地黄八两、山茱萸四两、附子一两，故山茱萸与附子用量之比为四比一，取少火生气、阴中求阳之意。"},{"q":"定喘汤的功用是","o":["宣肺降气，疏风止咳","降气平喘，祛痰止咳","宣肺降气，清肺平喘","降气快膈，化痰消食","降逆化痰，益气和胃"],"a":2,"e":"定喘汤宣肺降气、清肺平喘，方中麻黄宣肺散邪，白果敛肺定喘，黄芩、桑白皮清泻肺热，主治风寒外束、痰热内蕴之喘咳。"},{"q":"肝肺同治，于清肝宁肺中求止血之功的方剂是","o":["咳血方","龙胆泻肝汤","小蓟饮子","十灰散","镇肝熄风汤"],"a":0,"e":"咳血方以青黛、栀子清肝泻火，瓜蒌仁、海粉化痰，诃子敛肺，肝肺同治，于清肝宁肺之中求止血之功。"},{"q":"黄芪桂枝五物汤功用是","o":["温经散寒，养血通脉","温补阳气，益气生脉","益气和营，温经通痹","温阳补血，散寒通滞","益气补血，散寒温阳"],"a":2,"e":"黄芪桂枝五物汤即桂枝汤去甘草、倍生姜、加黄芪而成，益气和营、温经通痹，主治营卫气血不足、风寒乘虚而入之血痹。"},{"q":"半夏泻心汤与小柴胡汤两方相同的药物是","o":["人参、黄芩、半夏、干姜、甘草","人参、生姜、半夏、甘草、大枣","半夏、黄芩、人参、甘草、大枣","柴胡、人参、黄芩、甘草、生姜","半夏、黄连、黄芩、甘草、大枣"],"a":2,"e":"半夏泻心汤由半夏、黄芩、黄连、干姜、人参、甘草、大枣组成，小柴胡汤由柴胡、黄芩、人参、半夏、甘草、生姜、大枣组成，共有半夏、黄芩、人参、甘草、大枣。"},{"q":"下列各项，其中哪项不是苏子降气汤用药","o":["苏子，半夏","杏仁，冬花","当归，甘草","前胡，厚朴","肉桂，生姜"],"a":1,"e":"苏子降气汤由紫苏子、半夏、当归、甘草、前胡、厚朴、肉桂组成，加生姜、大枣，方中不用杏仁、款冬花。"},{"q":"药物配伍具有“温润和平，不寒不热”特点的方剂是","o":["正柴胡饮","止嗽散","桑菊饮","小青龙汤","三拗汤"],"a":1,"e":"止嗽散由桔梗、荆芥、紫菀、百部、白前、甘草、陈皮组成，止咳化痰、疏表宣肺，药性温润和平、不寒不热，为治诸般咳嗽之通剂。"},{"q":"用治热结下焦之血淋、尿血的方剂是","o":["五苓散","小蓟饮子","槐花散","肾气丸","二妙散"],"a":1,"e":"小蓟饮子由小蓟、藕节、蒲黄、滑石、木通、竹叶、栀子、当归、生地、甘草组成，凉血止血、利水通淋，主治热结下焦之血淋、尿血。"},{"q":"一贯煎的功用是","o":["滋补肝肾","滋阴清热","滋阴降火","滋阴疏肝","滋阴凉血"],"a":3,"e":"一贯煎由生地黄、沙参、麦冬、当归、枸杞子、川楝子组成，滋阴疏肝，主治肝肾阴虚、肝气不舒之胸脘胁痛、吞酸口苦、舌红少津。"},{"q":"小建中汤中桂枝与芍药的用量比例","o":["1∶1","1∶2","1∶3","2∶1","3∶1"],"a":1,"e":"小建中汤中桂枝三两、芍药六两，用量之比为一比二，倍芍药以酸甘化阴、缓急止痛，与饴糖相合而寓建中之意。"},{"q":"小蓟饮子与八正散均可利尿通淋，小蓟饮子重在","o":["清心除烦","凉血止血","收涩止血","清肝宁肺","养血安神"],"a":1,"e":"小蓟饮子以凉血止血为主，兼以利水通淋，主治热结下焦之血淋、尿血；八正散则重在清热泻火、利水通淋。"},{"q":"槐花散证的病机是","o":["血热妄行，损伤血络","风热湿毒，壅遏肠道","脾阳不足，脾不统血","下焦瘀热，损伤血络","肝火犯肺，损伤肺络"],"a":1,"e":"槐花散证由风热湿毒壅遏肠道、损伤血络而致，症见便前出血、血色鲜红、四射如溅，治以清肠止血、疏风理气。"},{"q":"“病痰饮者当以温药和之”的代表方剂是","o":["苓桂术甘汤","防己黄芪汤","肾著汤","真武汤","实脾散"],"a":0,"e":"苓桂术甘汤由茯苓、桂枝、白术、甘草组成，温阳化饮、健脾利湿，为“病痰饮者当以温药和之”的代表方，主治中阳不足之痰饮。"},{"q":"苏子降气汤的主治病证是","o":["痰热喘咳证","上实下虚喘咳证","肺热喘咳证","湿痰咳嗽证","寒饮咳嗽证"],"a":1,"e":"苏子降气汤降气平喘、祛痰止咳，主治上实下虚之喘咳，上实为痰涎壅肺，下虚为肾阳不足，症见喘咳痰多、胸膈满闷、腰膝酸软。"},{"q":"《温热经纬》清暑益气汤的君药是","o":["西瓜翠衣和黄连","西洋参和石斛","石斛和麦冬","西瓜翠衣和石斛","西瓜翠衣和西洋参"],"a":4,"e":"《温热经纬》清暑益气汤以西瓜翠衣、西洋参为君，清暑益气、养阴生津，主治暑热气津两伤之身热汗多、口渴心烦、体倦少气。"},{"q":"朱砂安神丸中黄连的炮制方法为","o":["生用","姜汁炒","蜜炙黄连","酒洗","以上都不正确"],"a":3,"e":"朱砂安神丸中黄连酒洗，取其上行入心、清心泻火，与朱砂镇心安神相配，主治心火亢盛、灼伤阴血之怔忡失眠、心烦神乱。"},{"q":"苏子降气汤的功用是","o":["宣肺降气，清热化痰","降逆化痰，益气和胃","降气平喘，祛痰止咳","温肺化饮","宣利肺气，疏风止咳"],"a":2,"e":"苏子降气汤降气平喘、祛痰止咳，主治上实下虚之喘咳痰多、胸膈满闷，与定喘汤之宣肺降气、清热化痰者不同。"},{"q":"组成中生地和熟地同用的方剂是","o":["养阴清肺汤","百合固金汤","清燥救肺汤","增液汤","麦门冬汤"],"a":1,"e":"百合固金汤中生地黄、熟地黄并用，滋阴补肾、凉血止血，配百合、麦冬润肺，主治肺肾阴亏、虚火上炎之咳嗽痰血、咽喉燥痛。"},{"q":"主治外感风寒，郁而化热证的方剂是","o":["小青龙汤","升麻葛根汤","竹叶柳蒡汤","柴葛解肌汤","葱豉桔梗汤"],"a":3,"e":"柴葛解肌汤解肌清热，主治外感风寒、郁而化热证，症见恶寒渐轻、身热增盛、头痛肢楚、目疼鼻干、心烦不眠、脉浮微洪。"},{"q":"天麻钩藤饮配伍的臣药是","o":["杜仲、怀牛膝","川牛膝、石决明","杜仲、桑寄生","川牛膝、桑寄生","杜仲、石决明"],"a":1,"e":"天麻钩藤饮中天麻、钩藤平肝息风为君，石决明、川牛膝为臣，石决明潜阳降逆，川牛膝引血下行，共助平肝息风之力。"},{"q":"温脾汤的功用是","o":["温里散寒、通便止痛","泻下寒积、散寒止痛","温补脾阳、润肠通便","温肾益精、攻逐寒积","攻下冷积、温补脾阳"],"a":4,"e":"温脾汤攻下冷积、温补脾阳，由大黄、附子、干姜、人参、芒硝、当归、甘草组成，主治脾阳不足、寒积中阻之腹痛便秘。"},{"q":"阳和汤中可达皮里膜外，具有温化寒痰，通络散结作用的药物是","o":["麻黄","白芥子","肉桂","炮姜炭","生甘草"],"a":1,"e":"阳和汤中白芥子辛温，可达皮里膜外，温化寒痰、通络散结，与熟地、鹿角胶、肉桂、麻黄相配，主治阳虚寒凝之阴疽。"},{"q":"大承气汤和大陷胸汤中均有的药物是","o":["大黄、甘草","芒硝、甘草","芒硝、枳实","枳实、厚朴","大黄、芒硝"],"a":4,"e":"大承气汤由大黄、芒硝、枳实、厚朴组成，大陷胸汤由大黄、芒硝、甘遂组成，两方共有大黄、芒硝。"},{"q":"蒿芩清胆汤的主治证是","o":["湿热壅阻膀胱证","脾胃湿浊阻滞证","肝郁血虚脾弱证","表里寒热错杂证","少阳湿热痰浊证"],"a":4,"e":"蒿芩清胆汤清胆利湿、和胃化痰，主治少阳湿热痰浊证，症见寒热如疟、寒轻热重、口苦膈闷、吐酸苦水、舌红苔腻。"},{"q":"茵陈蒿汤中，清热降火，导邪从小便而出的药物是","o":["栀子","茵陈","大黄","青蒿","滑石"],"a":0,"e":"茵陈蒿汤中栀子苦寒，清热降火、通利三焦，导湿热之邪从小便而出；茵陈为君清利湿热退黄，大黄泻热逐瘀从大便而去。"},{"q":"以下关于大秦艽汤的配伍特点描述错误的是","o":["辛温甘寒","外散内补","气血兼顾","寓降于升","清养并行"],"a":3,"e":"大秦艽汤祛风清热、养血活血，配伍特点为辛温甘寒并用、外散内补兼施、气血兼顾、清养并行，寓降于升不属其特点。"},{"q":"四神丸的组成中有","o":["肉豆蔻、山茱萸","肉豆蔻、赤石脂","肉豆蔻、补骨脂","五味子、山茱萸","五味子、赤石脂"],"a":2,"e":"四神丸由肉豆蔻、补骨脂、五味子、吴茱萸组成，加生姜、大枣，温肾暖脾、固肠止泻，主治脾肾虚寒之五更泄泻。"},{"q":"组成中有山药的方是","o":["金锁固精丸","缩泉丸","桑螵蛸散","固冲汤","四神丸"],"a":1,"e":"缩泉丸由益智仁、乌药、山药组成，温肾祛寒、缩尿止遗，山药健脾补肾而兼固涩，主治膀胱虚寒之小便频数、遗尿。"},{"q":"四君子汤证的病机是","o":["脾肾阳虚，水湿内停","脾胃虚弱，湿自内生","脾胃气虚，纳谷与运化乏力","脾胃气虚，饮食停滞","脾胃虚弱，中气下陷"],"a":2,"e":"四君子汤证由脾胃气虚、纳谷与运化乏力而致，症见面色萎白、语声低微、四肢乏力、食少便溏、舌淡苔白、脉虚弱。"},{"q":"普济消毒饮中体现“火郁发之”治法的药物是","o":["黄连、黄芩","桔梗、连翘","升麻、柴胡","玄参、板蓝根","橘红、牛蒡子"],"a":2,"e":"普济消毒饮中升麻、柴胡升阳散火，引诸药上行头面，疏散郁结之热毒，体现“火郁发之”之法，为方中佐使。"},{"q":"下列哪味药不是温胆汤的组成","o":["竹茹","枳壳","橘皮","半夏","茯苓"],"a":1,"e":"温胆汤由半夏、竹茹、枳实、陈皮、甘草、茯苓组成，理气化痰、和胃利胆，方中用枳实破气消痰，不用枳壳。"},{"q":"四逆散与四逆汤共用的药物是","o":["柴胡","干姜","甘草","枳实","芍药"],"a":2,"e":"四逆散由柴胡、芍药、枳实、甘草组成，四逆汤由附子、干姜、甘草组成，两方共有的药物为甘草。"},{"q":"定喘汤清泻肺热的药物是","o":["桑白皮、地骨皮","桑白皮 、黄芩","地骨皮、黄芩、石膏","石膏、知母","黄芩、黄连"],"a":1,"e":"定喘汤中桑白皮、黄芩清泻肺热、止咳平喘，与麻黄宣肺散邪、白果敛肺定喘相配，主治风寒外束、痰热内蕴之喘咳痰稠。"},{"q":"仙方活命饮与普济消毒饮两方共同的药物是","o":["贝母","连翘","金银花","陈皮","乳香"],"a":3,"e":"两方均用陈皮理气化痰、疏壅散结。仙方活命饮尚有金银花、白芷、乳香、没药，普济消毒饮则有黄连、黄芩、升麻、柴胡。"},{"q":"增液汤的组成是","o":["人参、麦冬、生地","玄参、麦冬、生地","人参、天冬、生地","玄参、天冬、熟地","人参、麦冬、熟地"],"a":1,"e":"增液汤由玄参、麦冬、生地黄组成，滋阴清热、润肠通便，主治阳明温病津亏便秘之无水舟停证。"},{"q":"下列选项中，不属于黄龙汤组成的是","o":["麦冬","人参","当归","大黄","桔梗"],"a":0,"e":"黄龙汤由大承气汤加人参、当归、甘草、桔梗、生姜、大枣组成，攻下热结、益气养血，方中不用麦冬。"},{"q":"治疗湿痰的代表方剂为","o":["清气化痰丸","贝母瓜蒌散","温胆汤","二陈汤","茯苓丸"],"a":3,"e":"二陈汤由半夏、橘红、茯苓、甘草组成，燥湿化痰、理气和中，为治湿痰之代表方，主治咳嗽痰多色白易咯、舌苔白腻。"},{"q":"体现“实则泻其子”治法的方剂是","o":["导赤散","左金丸","泻青丸","龙胆泻肝汤","当归龙荟丸"],"a":1,"e":"左金丸中黄连用量倍于吴茱萸，清泻肝火以泻心火，即“实则泻其子”之法，主治肝火犯胃之胁痛口苦、呕吐吞酸。"},{"q":"清气化痰丸中没有使用的药物是","o":["陈皮","半夏","茯苓","紫菀","胆南星"],"a":3,"e":"清气化痰丸由胆南星、瓜蒌仁、黄芩、半夏、陈皮、枳实、茯苓、杏仁组成，清热化痰、理气止咳，方中不用紫菀。"},{"q":"《温热经纬》清暑益气汤功能清暑益气，尚可","o":["敛阴止汗","利水化湿","和胃止呕","化湿止泻","养阴生津"],"a":4,"e":"《温热经纬》清暑益气汤于清暑益气之外，尚能养阴生津，方中西洋参、石斛、麦冬、西瓜翠衣共奏清补兼施之效。"},{"q":"原方特别注明“不用姜”的方剂是","o":["平胃散","二陈汤","定喘汤","苏子降气汤","半夏白术天麻汤"],"a":2,"e":"定喘汤原方特别注明“不用姜”，因其证属痰热内蕴，生姜辛温恐助热伤津，故避而不用。"},{"q":"黄土汤的功效是","o":["益气健脾，养血止血","温经散寒，祛瘀止血","温补脾胃，温经止血","温阳健脾，养血止血","益气养血，收敛止血"],"a":3,"e":"黄土汤温阳健脾、养血止血，由灶心黄土、白术、附子、干地黄、阿胶、黄芩、甘草组成，主治脾阳不足之便血、崩漏。"},{"q":"何方配伍取“少火生气”之义","o":["肾气丸","十补丸","右归丸","右归饮","龟鹿二仙胶"],"a":0,"e":"肾气丸以少量桂枝、附子温补肾阳，配大队滋阴填精之品，取“少火生气”之义，使阳得阴助而生化无穷。"},{"q":"真人养脏汤、四神丸两方中共有的药物是","o":["补骨脂","肉桂","人参","肉豆蔻","五味子"],"a":3,"e":"两方均用肉豆蔻温中涩肠止泻。真人养脏汤尚有罂粟壳、诃子、肉桂，四神丸则配补骨脂、五味子、吴茱萸。"},{"q":"补中益气汤证的病机为","o":["脾胃气虚","脾胃气虚，湿自内生","脾胃气虚，清阳下陷","卫气虚弱，不能固表","肺肾虚衰，气逆不降"],"a":2,"e":"补中益气汤证由脾胃气虚、清阳下陷而致，症见体倦肢软、少气懒言、脱肛久泻、舌淡脉虚，治以补中益气、升阳举陷。"},{"q":"大秦艽汤与独活寄生汤组成中共有的药物是","o":["秦艽、防风、独活、生地黄、茯苓","细辛、甘草、当归、羌活、川芎","秦艽、芍药、独活、熟地黄、川芎","独活、茯苓、细辛、当归、防风","秦艽、独活、干地黄、川芎、甘草"],"a":3,"e":"两方共有独活、防风、细辛、当归、茯苓、川芎、甘草等。大秦艽汤另用石膏、白芷、黄芩，独活寄生汤则配桑寄生、杜仲、牛膝。"},{"q":"葛根黄芩黄连汤的主治证是","o":["外感风热证","表证未解，邪热入里证","邪热壅肺证","湿热痢疾","外寒内饮证"],"a":1,"e":"葛根黄芩黄连汤解表清里，主治表证未解、邪热入里证，症见身热下利、胸脘烦热、口干作渴、喘而汗出、脉促。"},{"q":"交泰丸的主治证是","o":["心火偏亢，气血两虚证","心火偏亢，肝阳上亢证","心肾气虚，心肾不交证","心肝血虚，虚火上炎证","心火偏亢，心肾不交证"],"a":4,"e":"交泰丸由黄连、肉桂组成，主治心火偏亢、肾阳不足之心肾不交证，症见怔忡失眠。黄连清心降火，肉桂引火归元，使水火既济。"},{"q":"地黄饮子主治的病证为","o":["痰饮","喑痱","消渴","脚气","转胞"],"a":1,"e":"地黄饮子滋肾阴、补肾阳、开窍化痰，主治下元虚衰、痰浊上泛之喑痱，症见舌强不能言、足废不能用。"},{"q":"下列哪项不是大枣在十枣汤中配伍意义","o":["益脾缓中","固护胃气","培土制水","缓诸药毒","补脾养血"],"a":4,"e":"大枣在十枣汤中益脾缓中、固护胃气、培土制水，并缓峻逐水药之毒，属佐使护正之用，并无补脾养血之功。"},{"q":"以下关于阿胶鸡子黄汤证的辨证要点描述错误的是","o":["高热神昏","筋脉拘急","手足瘛疭","舌绛苔少","脉细数"],"a":0,"e":"阿胶鸡子黄汤证为邪热久羁、阴血亏耗、虚风内动，以筋脉拘急、手足瘛疭、舌绛苔少、脉细数为要点；高热神昏是热陷心包之候，非本证所见。"},{"q":"白虎汤中配伍石膏的意义是","o":["清热解毒","清热滋阴","清热凉血","清退虚热","清热除烦止渴"],"a":4,"e":"石膏辛甘大寒，善清阳明气分实热而除烦止渴，为白虎汤君药，与知母相须为用，使热退津复。"},{"q":"不属于白虎汤适应证的是","o":["壮热面赤","烦渴引饮","汗出恶热","脉洪大无力","脉洪大有力"],"a":3,"e":"白虎汤适用于壮热面赤、烦渴引饮、汗出恶热、脉洪大有力之气分实热证；脉洪大无力为热盛而气津两伤，当用白虎加人参汤。"},{"q":"槐花散中用以行气宽肠，使气调血调的药物是","o":["厚朴","槟榔","枳壳","陈皮","木香"],"a":2,"e":"枳壳苦辛微寒，行气宽肠，使气调则血调，助槐花、侧柏叶凉血止血，为槐花散中调气之品。"},{"q":"导赤散中的君药是","o":["黄连","甘草","竹叶","木通","生地黄"],"a":4,"e":"生地黄甘寒而润，凉血滋阴以制心火，为导赤散君药；木通、竹叶降火利水，使心热从小便而出。"},{"q":"大秦艽汤配伍的臣药是","o":["羌活、独活、防风、白芷、细辛","生地、熟地、当归、白芍、川芎","羌活、独活、川芎、当归、白术","生地、当归、白芍、白术、甘草","熟地、川芎、白芷、羌活、独活"],"a":0,"e":"大秦艽汤以秦艽为君祛风通络，羌活、独活、防风、白芷、细辛辛散风邪，助君药疏风散邪，共为臣药。"},{"q":"可以治疗湿温病及风湿热痹的方剂是","o":["三仁汤","竹叶石膏汤","白虎加苍术汤","白虎加桂枝汤","白虎加人参汤"],"a":2,"e":"白虎加苍术汤于白虎汤中加苍术燥湿健脾，既清阳明气分热盛，又化太阴脾湿，故治湿温病及风湿热痹。"},{"q":"下列方剂中，需要去滓，再煎的是","o":["小柴胡汤","银翘散","麻黄汤","小建中汤","痛泻要方"],"a":0,"e":"小柴胡汤煎法为去滓再煎，使药性醇和、和解之力更专，是张仲景和解剂特有的煎服方法。"},{"q":"小柴胡汤中，一散一清，恰入少阳，以解少阳之邪的配伍是","o":["半夏、生姜","柴胡、黄芩","柴胡、生姜","黄芩、大枣","半夏、黄芩"],"a":1,"e":"柴胡轻清升散，透泄少阳半表之邪；黄芩苦寒，清泄少阳半里之热；一散一清，恰入少阳，共解少阳之邪。"},{"q":"牵正散的君药是","o":["白附子","黑附子","白僵蚕","黑僵蚕","全蝎"],"a":0,"e":"牵正散以白附子为君，祛头面风痰、止痉；白僵蚕、全蝎为臣，祛风化痰通络，治风中经络之口眼喎斜。"},{"q":"当归拈痛汤与五苓散共司的药物是","o":["泽泻，白术，苍术","茯苓，苍术，猪苓","泽泻，苍术，猪苓","泽泻，白术，茯苓","泽泻，白术，猪苓"],"a":4,"e":"当归拈痛汤与五苓散均用泽泻、白术、猪苓，淡渗利湿以除水湿，二方共用此三味以分利小便。"},{"q":"下列方剂组成中不含大黄的是","o":["大陷胸汤","麻子仁丸","温脾汤","济川煎","黄龙汤"],"a":3,"e":"济川煎由当归、牛膝、肉苁蓉、泽泻、升麻、枳壳组成，温肾益精、润肠通便，方中不用大黄；余四方皆含大黄以泻下。"},{"q":"四逆散中一升一降配伍的药物是","o":["柴胡配芍药","柴胡配甘草","柴胡配枳实","枳实配芍药","柴胡配枳壳"],"a":2,"e":"柴胡升发阳气、疏肝解郁，枳实降气破结，一升一降使气机调畅，为四逆散调畅气机之要。"},{"q":"痛泻要方与补中益气汤组成中共有的药物是","o":["黄芪","防风","当归","柴胡","白术"],"a":4,"e":"痛泻要方由白术、白芍、陈皮、防风组成，补中益气汤含黄芪、人参、白术、甘草、当归、陈皮、升麻、柴胡，二方共有白术。"},{"q":"功用为清热化痰，理气止咳的方剂是","o":["小陷胸汤","清气化痰丸","贝母瓜蒌散","温胆汤","麻黄汤"],"a":1,"e":"清气化痰丸以胆南星为君，配黄芩、瓜蒌仁、杏仁等，共奏清热化痰、理气止咳之功，治痰热内结之咳嗽。"},{"q":"贝母瓜萎散组成中没有","o":["半夏","瓜蒌","茯苓","桔梗","天花粉"],"a":0,"e":"贝母瓜蒌散由贝母、瓜蒌、天花粉、茯苓、橘红、桔梗组成，润肺清热、理气化痰，方中不用温燥之半夏。"},{"q":"五积散的主治证是","o":["外寒内饮证","表证未解，邪热入里证","邪热壅肺证","湿热痢疾","外感风寒，内伤生冷证"],"a":4,"e":"五积散发表温里、顺气化痰、活血消积，主治外感风寒、内伤生冷所致寒、湿、气、血、痰五积之证。"},{"q":"防风通圣散的主治证是","o":["外感风寒表实证","外寒内饮证","邪热雍肺证","协热下利","风热壅盛，表里俱实证"],"a":4,"e":"防风通圣散疏风解表、泻热通便，主治风热壅盛、表里俱实证，症见憎寒壮热、目赤咽痛、便秘溲赤。"},{"q":"肾气丸和右归丸共有的药是","o":["枸杞子","杜仲","薯蓣","泽泻","鹿角胶"],"a":2,"e":"肾气丸与右归丸均以薯蓣（山药）补脾固肾，二方尚同用山茱萸、附子、肉桂，而枸杞子、鹿角胶、杜仲为右归丸独有。"},{"q":"阿胶鸡子黄汤的功用是","o":["滋阴复脉，潜阳息风","平肝息风，补益肝肾","镇肝息风，滋阴潜阳","滋阴养血，柔肝息风","凉肝息风，增液舒筋"],"a":3,"e":"阿胶鸡子黄汤以阿胶、鸡子黄滋阴养血，配白芍、生地、牡蛎柔肝潜阳，功用为滋阴养血、柔肝息风。"},{"q":"下述选项中不属于凉开剂的是","o":["安宫牛黄丸","紫雪","至宝丹","抱龙丸","紫金锭"],"a":4,"e":"凉开剂有安宫牛黄丸、紫雪、至宝丹、抱龙丸；紫金锭药性偏温，长于辟秽解毒、化痰开窍，属温开之剂。"},{"q":"下列各项中，均属于完带汤药物组成的是","o":["人参、白术、茯苓","柴胡、枳壳、白芍","苍术、荆芥穗、山药","车前子、柴胡、木香","党参、苍术、白术"],"a":2,"e":"完带汤由白术、山药、人参、白芍、车前子、苍术、甘草、陈皮、黑荆芥、柴胡组成，苍术、荆芥穗、山药三药俱备，而不用茯苓。"},{"q":"远志、菖蒲、茯神并用的方是","o":["归脾汤","天王补心丹","酸枣仁汤","桑螵蛸散","金锁固精丸"],"a":3,"e":"桑螵蛸散以桑螵蛸为君补肾固精，配远志、石菖蒲、茯神交通心肾、安神定志，三药并用，治心肾两虚之尿频遗尿。"},{"q":"乌梅在二陈汤中的配伍意义是","o":["涩肠止泻","收敛止血","安蛔止痛","生津止渴","收敛肺气"],"a":4,"e":"二陈汤少佐乌梅收敛肺气，与半夏、橘红相配，散中有收，使燥湿化痰而不伤肺气，为祛痰剂敛散并用之范例。"},{"q":"大补阴丸的主治证是","o":["肾之阴阳两虚证","肾阳不足证","真阴不足证","肝肾阴虚证","阴虚火旺证"],"a":4,"e":"大补阴丸以熟地、龟板滋阴填精，知母、黄柏降火，主治肝肾阴虚、虚火上炎之阴虚火旺证，症见骨蒸潮热、盗汗遗精。"},{"q":"痛泻要方的君药是","o":["防风","白术","陈皮","白芍","黄芪"],"a":1,"e":"痛泻要方重用白术健脾燥湿以止泻，为君药；白芍柔肝缓急止痛为臣，佐陈皮理气、防风散肝舒脾。"},{"q":"猪苓汤组成中润燥且滋阴的药物是","o":["阿胶","茯苓","玄参","生地","麦冬"],"a":0,"e":"猪苓汤以猪苓、茯苓、泽泻、滑石利水清热，佐阿胶甘平润燥滋阴，利水而不伤阴，治水热互结兼阴伤之证。"},{"q":"三子养亲汤的功用是","o":["温肺化痰，降气消食","温肺化饮，降气平喘","温肺化痰，利气畅膈","降气消痰，止咳平喘","消食导滞，降气祛痰"],"a":0,"e":"三子养亲汤由白芥子、苏子、莱菔子组成，温肺化痰、降气消食，主治痰壅气逆食滞之咳嗽喘逆、食少痰多。"},{"q":"大柴胡汤的主治证是","o":["少阳证","阳明证","太阳证","少阳阳明合病","三阳经合病"],"a":3,"e":"大柴胡汤和解少阳、内泻热结，主治少阳阳明合病，症见往来寒热、胸胁苦满、呕不止、心下痞硬、大便不解。"},{"q":"旋覆代赭汤中原方旋覆花与代赭石的用量比例是","o":["1∶1","1∶2","1∶3","3∶1","3∶2"],"a":3,"e":"原方旋覆花三两、代赭石一两，用量为三比一；重用旋覆花降气化痰，代赭石质重沉降，量小则降逆而不伤胃。"},{"q":"橘皮竹茹汤的功效是","o":["降逆止呃，益气清热","养阴补肺，清热止血","和胃止呕，散饮降逆","回阳救急，益气生脉","温中散寒，养血通脉"],"a":0,"e":"橘皮竹茹汤以橘皮、竹茹降逆和胃，人参、甘草、大枣益气补中，共奏降逆止呃、益气清热之功，治胃虚有热之呃逆。"},{"q":"温脾汤中用量最大的药物是","o":["当归","人参","大黄","附子","芒硝"],"a":2,"e":"温脾汤中大黄用量最重，取四两泻下攻积，与附子、干姜温阳相配，成温下之法，寓攻于温。"},{"q":"以下关于小活络丹的辨证要点描述错误的是","o":["腰膝酸软无力","肢体筋脉挛痛","关节屈伸不利","舌质淡紫","舌苔白"],"a":0,"e":"小活络丹证为风寒湿痰瘀阻经络，以肢体筋脉挛痛、关节屈伸不利、舌质淡紫、舌苔白为要点；腰膝酸软无力属肾虚之候。"},{"q":"桃核承气汤的组成含有","o":["大承气汤","小承气汤","调胃承气汤","增液承气汤","复方大承气汤"],"a":2,"e":"桃核承气汤由桃仁、大黄、桂枝、芒硝、甘草组成，即调胃承气汤加桃仁、桂枝，泻热逐瘀，治下焦蓄血证。"},{"q":"配伍体现酸苦辛并进的方剂是","o":["酸枣仁汤","半夏泻心汤","乌梅丸","平胃散","黄连解毒汤"],"a":2,"e":"乌梅丸以乌梅之酸、黄连黄柏之苦、附子干姜桂枝细辛蜀椒之辛并进，寒热并用、攻补兼施，为治蛔厥之主方。"},{"q":"真人养脏汤的组成中有","o":["诃子、乌梅","诃子、罂粟壳","诃子、五倍子","诃子、山萸肉","诃子、赤石脂"],"a":1,"e":"真人养脏汤由人参、白术、肉桂、当归、白芍、木香、诃子、罂粟壳、肉豆蔻、甘草组成，涩肠止泻、温中补虚。"},{"q":"犀角地黄汤的主治证是","o":["热入营分证","热入血分证","气分热盛证","三焦火热证","气血两燔证"],"a":1,"e":"犀角地黄汤清热解毒、凉血散瘀，主治热入血分证，症见身热谵语、斑色紫黑、吐血衄血、舌绛起刺。"},{"q":"贝母瓜蒌散之功用是","o":["润肺清热，理气化痰","清热化痰，宽胸散结","温肺散寒，涤痰化饮","燥湿化痰，平肝熄风","荡涤实热，攻逐顽痰"],"a":0,"e":"贝母瓜蒌散中贝母、瓜蒌、天花粉润肺清热化痰，橘红、茯苓、桔梗理气健脾，功用为润肺清热、理气化痰。"},{"q":"大补阴丸的功用是","o":["滋阴补肾","滋阴疏肝","滋阴降火","滋阴补肺，清热止血","滋阴补肾，填精益髓"],"a":2,"e":"大补阴丸以熟地、龟板滋阴填髓培本，知母、黄柏苦寒降火清源，标本兼顾，功用为滋阴降火。"},{"q":"具有“益气解表，理气化痰”功用的方剂是","o":["败毒散","参苏饮","麻黄附子细辛汤","再造散","加减葳蕤汤"],"a":1,"e":"参苏饮以人参、苏叶益气解表，配半夏、陈皮、茯苓、枳壳、木香理气化痰，主治气虚外感风寒、内有痰湿之证。"},{"q":"防己黄芪汤与五苓散共同的药物是","o":["茯苓","猪苓","白术","泽泻","甘草"],"a":2,"e":"防己黄芪汤由防己、黄芪、白术、甘草组成，五苓散含泽泻、猪苓、茯苓、白术、桂枝，二方共用白术健脾祛湿。"},{"q":"生脉散证的病机特点是","o":["肺肾不足，阴虚火旺","温热暑邪，气阴耗伤","肺肾虚衰，气逆不降","津伤气耗，虚火内盛","风热犯肺，肺失肃降"],"a":1,"e":"生脉散证为温热、暑热之邪耗伤气阴，症见体倦气短、咽干口渴、脉虚细，治以益气生津、敛阴止汗。"},{"q":"主治“风温初起，邪客肺络证”的方剂是","o":["麻黄杏仁甘草石膏汤","香薷散","银翘散","香苏散","桑菊饮"],"a":4,"e":"桑菊饮疏风清热、宣肺止咳，主治风温初起、邪客肺络证，症见但咳、身热不甚、口微渴。"},{"q":"消风散的主治证是","o":["风寒湿","破伤风","类中风","风疹","风湿热"],"a":3,"e":"消风散疏风养血、清热除湿，主治风疹、湿疹，症见皮肤瘙痒、疹色红、抓破渗液，或遍身云片斑点。"},{"q":"小蓟饮子的药物组成含有何方","o":["碧玉散","鸡苏散","四生丸","六一散","五苓散"],"a":3,"e":"小蓟饮子含滑石、甘草，即六一散，配竹叶导热下行、利水通淋，合小蓟、藕节、蒲黄凉血止血，治热结下焦之血淋。"},{"q":"玉屏风散主治","o":["营卫失调，恶风自汗","表虚自汗，易感风邪","阴虚火旺，汗液外泄","诸虚不足，自汗盗汗","暑热耗气，短气自汗"],"a":1,"e":"玉屏风散以黄芪益气固表、白术健脾、防风走表祛风，主治表虚自汗、易感风邪之证，功用为益气固表止汗。"},{"q":"下列各项中，属于实脾散功用的是","o":["温阳利水","温阳健脾，行气利水","温阳化饮，健脾利水","利水消肿，理气健脾","温阳化气，利水渗湿"],"a":1,"e":"实脾散以附子、干姜温阳，白术、茯苓健脾，木香、厚朴、槟榔行气利水，功用为温阳健脾、行气利水，治脾肾阳虚水肿。"},{"q":"逍遥散中具有“疏散郁遏之气，透达肝经郁热”作用的药物是","o":["当归","白芍","生姜","薄荷","柴胡"],"a":3,"e":"逍遥散中薄荷少量，疏散郁遏之气、透达肝经郁热；柴胡疏肝解郁，当归、白芍养血柔肝，共成疏肝健脾之功。"},{"q":"朱砂安神丸与天王补心丹组成中共有的药物为","o":["生地","玄参","柏子仁","桔梗","以上都不正确"],"a":0,"e":"朱砂安神丸含朱砂、黄连、生地、当归、甘草，天王补心丹亦用生地黄滋阴养血，二方共有生地黄。"},{"q":"大补阴丸的君药是","o":["熟地黄","龟板","熟地黄、龟板","知母、黄柏","黄柏"],"a":2,"e":"大补阴丸以熟地黄、龟板滋阴填精、壮水制火以培其本，共为君药；知母、黄柏苦寒降火为臣，清其源。"},{"q":"归脾汤组成中有","o":["当归","阿胶","干地黄","白芍药","川芎"],"a":0,"e":"归脾汤由黄芪、人参、白术、茯神、当归、龙眼肉、酸枣仁、远志、木香、甘草等组成，益气补血、健脾养心。"},{"q":"被柯琴称为“治癫痫之圣剂”的是","o":["朱砂安神丸","磁朱丸","珍珠母丸","交泰丸","以上都不正确"],"a":1,"e":"磁朱丸重镇安神、潜阳明目，柯琴誉为治癫痫之圣剂，用治肾阴不足、心阳偏亢之神志不安、癫痫。"},{"q":"集凉血、止血、清降祛瘀诸法于一方的方剂是","o":["龙胆泻肝汤","咳血方","百合固金汤","黄土汤","十灰散"],"a":4,"e":"十灰散取大蓟、小蓟、荷叶、侧柏叶等十味烧灰存性，凉血止血，兼清降祛瘀，为治血热妄行上部出血之常用方。"},{"q":"何方以滋阴填精，益气壮阳为功","o":["六味地黄丸","龟鹿二仙胶","十补丸","七宝美髯丹","肾气丸"],"a":1,"e":"龟鹿二仙胶以龟板滋阴填精、鹿角益气壮阳，配人参、枸杞，功用为滋阴填精、益气壮阳，治真元虚损之证。"},{"q":"参苓白术散的主治病证是","o":["脾虚夹湿","脾胃气虚","气虚下陷","气虚发热","脾肾两虚"],"a":0,"e":"参苓白术散益气健脾、渗湿止泻，主治脾虚夹湿证，症见饮食不化、便溏、四肢乏力、形体消瘦。"},{"q":"具有益气生津，润燥止渴功用的方剂是","o":["麦门冬汤","生脉散","清燥救肺汤","玉液汤","琼玉膏"],"a":3,"e":"玉液汤以黄芪、山药益气，知母、天花粉、葛根生津润燥，鸡内金助运化，功用为益气生津、润燥止渴，治消渴。"},{"q":"四逆汤与当归四逆汤二方组成中均含有的药物","o":["附子","桂枝","当归","甘草","干姜"],"a":3,"e":"四逆汤用附子、干姜、甘草，当归四逆汤用当归、桂枝、芍药、细辛、甘草、通草、大枣，二方共有甘草。"},{"q":"定痫丸中的君药是","o":["竹沥、胆南星","天麻、半夏","竹沥、天麻","胆南星、半夏","全蝎、胆南星"],"a":0,"e":"定痫丸以竹沥、胆南星为君，清热化痰、息风定痫，配天麻、全蝎、僵蚕等，治痰热内伏之痫证。"},{"q":"四物汤和当归补血汤共有的药是","o":["干地黄","黄芪","川芎","芍药","当归"],"a":4,"e":"四物汤用熟地、当归、白芍、川芎，当归补血汤用黄芪、当归，二方共有当归，一为补血，一为补气生血。"},{"q":"四君子汤的主治病证为","o":["脾胃虚寒证","湿邪困脾证","脾胃气虚证","脾阳不足证","脾虚泄泻证"],"a":2,"e":"四君子汤以人参、白术、茯苓、甘草益气健脾，主治脾胃气虚证，症见面色萎白、食少便溏、气短乏力。"},{"q":"保和丸中清热散结的药物是","o":["神曲","莱菔子","栀子","连翘","连翘、莱菔子"],"a":3,"e":"保和丸中山楂消食化积为君，配连翘清热散结，以清食积所化之热，为消食剂中兼清热之配伍。"},{"q":"四物汤与归脾汤共有的药是","o":["当归","人参","酸枣仁","白芍药","甘草"],"a":0,"e":"四物汤含当归、熟地、白芍、川芎，归脾汤含当归、黄芪、人参、白术等，二方共有当归养血。"},{"q":"大补阴丸与左归丸的共有药物是","o":["猪脊髓","熟地黄","山药","鹿角胶","菟丝子"],"a":1,"e":"大补阴丸用熟地、龟板、知母、黄柏，左归丸用熟地、山药、山茱萸、枸杞、鹿角胶等，二方共有熟地黄滋阴填精。"},{"q":"二陈汤组成中含有","o":["半夏、橘红、生姜、大枣","半夏、橘红、生姜、乌梅","半夏、橘红、炙甘草、大枣","半夏、橘红、生姜、五味子","半夏、橘红、白术、茯苓"],"a":1,"e":"二陈汤由半夏、橘红、茯苓、甘草组成，煎加生姜、乌梅，生姜降逆化痰，乌梅收敛肺气，散中有收。"},{"q":"四逆汤与下列哪一个方剂所用药物相同","o":["通脉四逆汤","四逆散","白通汤","参附汤","当归四逆汤"],"a":0,"e":"通脉四逆汤即四逆汤加大附子、干姜用量，药味相同而分量不同，属同药异量之变方，主治阴盛格阳证。"},{"q":"以下除哪项外，均是清暑益气汤的辨证要点","o":["身热汗多","口渴心烦","体倦少气","腹痛吐泻","脉虚数"],"a":3,"e":"清暑益气汤证为暑热耗伤气津，以身热汗多、口渴心烦、体倦少气、脉虚数为要点；腹痛吐泻是暑湿伤中之候。"},{"q":"以下不属于安宫牛黄丸主治证的是","o":["高热烦躁","神昏谵语","小儿惊厥","舌红绛","脉迟"],"a":4,"e":"安宫牛黄丸主治邪热内陷心包，症见高热烦躁、神昏谵语、舌红绛、小儿惊厥，脉象当数，脉迟与之相悖。"},{"q":"越鞠丸所治郁证的成因包括","o":["风、寒、暑、湿、燥、火","风、寒、痰、湿、燥、食","气、血、痰、火、食、湿","气、血、痰、热、食、湿","气、血、痰、火、暑、燥"],"a":2,"e":"越鞠丸通治气、血、痰、火、食、湿六郁，以香附行气解郁为君，川芎、栀子、苍术、神曲分治血、火、湿、食诸郁。"},{"q":"镇肝熄风汤的主治证是","o":["风痰上扰证","肝风上扰证","阴虚风动证","肝热生风证","类中风"],"a":4,"e":"镇肝熄风汤镇肝息风、滋阴潜阳，主治肝肾阴虚、肝阳偏亢、气血逆乱之类中风，症见头目眩晕、脑中热痛、脉弦长有力。"},{"q":"体现“苦寒直折”治法的方剂是","o":["白虎汤","清营汤","犀角地黄汤","普济消毒饮","黄连解毒汤"],"a":4,"e":"黄连解毒汤以黄连、黄芩、黄柏、栀子大苦大寒直折三焦火毒，清热泻火而不杂他法，为苦寒直折之代表方。"},{"q":"复元活血汤中配伍瓜蒌根的用意是","o":["消瘀散结、清热消肿","清热散结、生津止渴","消肿泻火排脓","活血化瘀、行气解郁","祛瘀通经、并退虚热"],"a":0,"e":"复元活血汤中瓜蒌根消瘀散结、清热消肿，与大黄、桃仁、红花相配，共奏活血祛瘀、疏肝通络之功。"},{"q":"养阴清肺汤的君药是","o":["麦冬","丹皮","生地","玄参","白芍"],"a":2,"e":"养阴清肺汤重用生地为君，滋阴壮水以制火，配玄参、麦冬养阴解毒，治白喉阴虚燥热之证。"},{"q":"定喘汤中配伍白果的意义是","o":["敛肺定喘而祛痰","宣肺散邪以平喘","清泻肺热，止咳平喘、调和诸药","清热化痰","燥湿化痰"],"a":0,"e":"定喘汤中白果敛肺定喘而祛痰，与麻黄宣肺散邪相配，一散一收使宣降有度，治风寒外束、痰热内蕴之喘咳。"},{"q":"不属于玉女煎的主治证候是","o":["头痛","牙痛","消渴","肺痿","舌红苔黄而干"],"a":3,"e":"玉女煎清胃滋阴，主治胃热阴虚之头痛、牙痛、齿衄、消渴、舌红苔黄而干；肺痿为肺叶枯萎之虚证，另属肺痿门。"},{"q":"下列各项中，属于完带汤主治症状的是","o":["带下色白","有异味","质黏稠","舌红苔少","脉细数"],"a":0,"e":"完带汤主治脾虚肝郁、湿浊下注之带下，症见带下色白、清稀无臭、倦怠便溏，舌淡苔白，脉缓或濡弱。"},{"q":"以下关于牵正散的药物组成描述正确的是","o":["蜈蚣、全蝎、白僵蚕","全蝎、白僵蚕、黑附子","蜈蚣、白僵蚕、黑附子","全蝎、白僵蚕、白附子","蜈蚣、全蝎、白附子"],"a":3,"e":"牵正散由白附子、白僵蚕、全蝎三味组成，祛风化痰、通络止痉，治风痰阻络之口眼喎斜。"},{"q":"大承气汤的功用是","o":["攻下冷积","峻下热结","润肠通便","轻下热结","缓下热结"],"a":1,"e":"大承气汤以大黄、芒硝峻下热结，枳实、厚朴行气除满，为峻下热结之代表方，治痞满燥实俱备之阳明腑实证。"},{"q":"补益剂应用时需注意","o":["真虚假实证、真实假虚证均可使用补益剂","补益剂中须配伍健胃消导之品，注意补而不滞","若血虚急证与大失血者，尤当着重补血","气虚重者应适当补气，血虚重者应适当补血","补益剂性质温和，适用范围广，虚证实证均可"],"a":1,"e":"补益剂易滋腻碍胃，故常配健胃消导之品，使补而不滞；真虚假实与真实假虚须辨明，误投补益反助邪。"},{"q":"逍遥散与实脾散共用的药物是","o":["当归、白芍","茯苓、白术","干姜、甘草","附子、生姜","大枣、柴胡"],"a":1,"e":"逍遥散含柴胡、当归、白芍、白术、茯苓、甘草、薄荷、生姜，实脾散含附子、干姜、白术、茯苓、厚朴等，二方共用茯苓、白术。"},{"q":"十灰散的功效是","o":["清热止血","凉血止血","收敛止血","祛瘀止血","温经止血"],"a":1,"e":"十灰散诸药烧灰存性，功用为凉血止血，兼能清降祛瘀，主治血热妄行之上部出血，如吐血、咯血、衄血。"},{"q":"二陈汤中“二陈”指下列哪组药","o":["半夏、茯苓","半夏、甘草","半夏、橘红","橘红、茯苓","橘红、乌梅"],"a":2,"e":"二陈汤中半夏、橘红以陈久者为佳，取其燥湿化痰之力缓而不峻，无过燥伤阴之弊，故方名二陈。"},{"q":"甘露消毒丹的病机是","o":["湿热内蕴，升降失常","湿热内蕴，气机阻滞","湿热内蕴，下注膀胱","湿热疫毒，蕴于气分","湿热疫毒，蕴于血分"],"a":3,"e":"甘露消毒丹利湿化浊、清热解毒，主治湿温时疫之湿热并重，病机为湿热疫毒蕴于气分，症见发热困倦、胸闷腹胀、身黄颐肿。"},{"q":"炙甘草汤与一贯煎共有的药物是","o":["沙参、麦门冬","生地黄、麦门冬","生地黄、当归","生地黄、人参","阿胶、麦门冬"],"a":1,"e":"炙甘草汤用生地黄、麦门冬滋阴复脉，一贯煎亦以生地黄、麦门冬滋养肝阴，二方共有此二味。"},{"q":"清胃散的主治证是","o":["胃热牙痛","阳明经热证","胃阴不足证","胃热阴虚证","脾胃伏火证"],"a":0,"e":"清胃散清胃凉血，主治胃火牙痛，症见牙痛牵引头脑、口气热臭、齿龈红肿、舌红苔黄、脉滑数。"},{"q":"山栀子在咳血方中的配伍意义是","o":["清热凉血，清心除烦","凉血止血，清心除烦","清热除烦，解毒利湿","清热解毒，凉血除烦","清肝泻火，凉血除烦"],"a":4,"e":"咳血方中栀子清肝泻火、凉血除烦，与青黛相配，使肝火得清而肺络得宁，治肝火犯肺之咳血。"},{"q":"十灰散的组成药物中无","o":["大蓟","仙鹤草","侧柏叶","山栀子","白茅根"],"a":1,"e":"十灰散由大蓟、小蓟、荷叶、侧柏叶、白茅根、茜草、山栀子、大黄、牡丹皮、棕榈皮组成，烧灰存性，方中不用仙鹤草。"},{"q":"茵陈蒿汤的主治病证是","o":["湿热并重证","热重于湿证","湿重于热证","黄疸阳黄","黄疸阴黄"],"a":3,"e":"茵陈蒿汤以茵陈为君清热利湿退黄，配栀子、大黄使湿热从二便而出，主治湿热黄疸之阳黄，症见一身面目俱黄如橘色。"},{"q":"不属于温里剂的方剂是","o":["小建中汤","温胆汤","四逆汤","当归四逆汤","理中丸"],"a":1,"e":"温胆汤理气化痰、清胆和胃，属祛痰剂；温里剂分温中祛寒、回阳救逆、温经散寒三类，小建中汤、四逆汤、当归四逆汤、理中丸皆属之。"},{"q":"失笑散主治证的病机是","o":["瘀血内停，脉道阻滞","寒凝血滞，冲任失调","气血郁滞，血行失畅","气虚血瘀，脉络阻滞","营血虚滞，气机失畅"],"a":0,"e":"失笑散以蒲黄、五灵脂活血祛瘀、散结止痛，主治瘀血内停、脉道阻滞之诸痛，症见心胸刺痛、痛有定处。"},{"q":"肾虚不固之遗精宜选","o":["固冲汤","固经丸","牡蛎散","金锁固精丸","桑螵蛸散"],"a":3,"e":"金锁固精丸以沙苑蒺藜补肾固精，芡实、莲子、莲须、龙骨、牡蛎涩精止遗，主治肾虚精关不固之遗精滑泄。"},{"q":"柴胡在四逆散中作用是","o":["疏肝解郁，透邪外出","透泄少阳之邪","解表退热","升举阳陷","截疟解毒"],"a":0,"e":"四逆散中柴胡升发阳气、疏肝解郁并能透邪外出，与枳实升降相因，使郁阳得伸而厥逆自愈。"},{"q":"痛泻要方中配伍防风的意义是","o":["疏风解表","祛风除湿","散寒止痛","疏肝解郁","升阳举陷"],"a":3,"e":"痛泻要方中防风辛散，散肝舒脾、疏肝解郁，又能升清止泻，与白芍相配调肝脾之升降，为佐使之用。"},{"q":"四神丸取","o":["枣肉为丸","炼蜜为丸","蒸饼为丸","水泛为丸","山药为丸"],"a":0,"e":"四神丸以生姜、大枣同煮，取枣肉和药为丸，温补脾肾、涩肠止泻，治脾肾虚寒之五更泄泻。"},{"q":"疏肝理脾的基础方是","o":["小柴胡汤","四逆散","痛泻要方","大柴胡汤","四逆汤"],"a":1,"e":"四逆散透邪解郁、疏肝理脾，为疏肝理脾之基础方，后世逍遥散、柴胡疏肝散皆由此化裁而成。"},{"q":"下列不属于清燥救肺汤的辨证要点是","o":["身热夜甚","干咳少痰","气逆而喘","脉虚大而数","舌红少苔"],"a":0,"e":"清燥救肺汤证为温燥伤肺、气阴两伤，以干咳少痰、气逆而喘、舌红少苔、脉虚大而数为要点；身热夜甚是热入营分之征。"},{"q":"主治大头瘟的方剂是","o":["黄连解毒汤","普济消毒饮","清瘟败毒饮","仙方活命饮","甘露消毒丹"],"a":1,"e":"普济消毒饮清热解毒、疏风散邪，主治风热疫毒上攻之大头瘟，症见头面红肿焮痛、恶寒发热、咽喉不利。"},{"q":"症见汗出恶风，小便不利，苔白，脉浮者，治宜","o":["桂枝汤","五苓散","五皮散","猪苓汤","防己黄芪汤"],"a":4,"e":"防己黄芪汤益气祛风、健脾利水，主治表虚不固之风水或风湿，症见汗出恶风、身重、小便不利、苔白脉浮。"},{"q":"下列各项中，属于真武汤药物组成的是","o":["茯神","芍药","干姜","肉桂","苍术"],"a":1,"e":"真武汤由茯苓、芍药、生姜、白术、附子组成，温阳利水，主治脾肾阳虚水泛；芍药兼利小便、柔肝止痛。"},{"q":"桃核承气汤中配伍桂枝的用意是","o":["温经散寒","散寒通脉","助阳化气","通行血脉","平冲降逆"],"a":3,"e":"桃核承气汤中桂枝通行血脉，助桃仁活血祛瘀，并防硝黄寒凉凝血，使瘀热并除，兼为佐药之用。"},{"q":"保和丸的君药是","o":["神曲","莱菔子","半夏","陈皮","山楂"],"a":4,"e":"保和丸重用山楂酸温消食化积，尤善消肉食油腻之积，为君药；神曲、莱菔子为臣，消食导滞。"},{"q":"保和丸的服药时间应该是","o":["食后","睡前","食远","晨起","食前"],"a":2,"e":"保和丸宜食远服，即食后较长时间服药，使药力正对宿食停滞之时，消食化积而不伤胃气。"},{"q":"大柴胡汤的功用是","o":["和解少阳，内泻热结","疏风解表，泻热通便","峻下热结","调和营卫","泻下逐水"],"a":0,"e":"大柴胡汤以小柴胡汤和解少阳，去人参、甘草之补，加大黄、枳实、芍药内泻热结，功用为和解少阳、内泻热结。"},{"q":"属于清营汤组成药物的是","o":["沙参","苦参","丹参","人参","天冬"],"a":2,"e":"清营汤用水牛角、生地、玄参、麦冬、银花、连翘、黄连、竹叶心、丹参，丹参清心凉血、活血散瘀，防热与血结。"},{"q":"主治少阳湿热证之常用方是","o":["半夏泻心汤","小柴胡汤","蒿芩清胆汤","龙胆泻肝汤","茵陈蒿汤"],"a":2,"e":"蒿芩清胆汤清胆利湿、和胃化痰，主治少阳湿热痰浊证，症见寒热如疟、寒轻热重、口苦膈闷、吐酸苦水。"},{"q":"理中丸与四君子汤组成中相同的药物是","o":["白术、干姜、人参","甘草、人参、干姜","人参、茯苓、甘草","甘草、人参、白术","人参、茯苓、白术"],"a":3,"e":"理中丸用人参、干姜、白术、甘草，四君子汤用人参、白术、茯苓、甘草，二方共有甘草、人参、白术。"},{"q":"十灰散中配伍大黄的意义是","o":["攻下积滞","活血祛瘀","清热凉血","温下寒积","导热下行"],"a":4,"e":"十灰散中大黄导热下行，使上炎之火从大便而去，兼能化瘀，体现降气止血、上病下取之意。"},{"q":"八正散的功用是","o":["清热泻火，利水养阴","清热泻火，利水通淋","清热泻火，通淋排石","清热凉血，利水通淋","凉血止血，利水通淋"],"a":1,"e":"八正散以木通、车前子、萹蓄、瞿麦、滑石、栀子、大黄、甘草梢组成，清热泻火、利水通淋，治湿热淋证。"},{"q":"温脾汤中用为君药的是","o":["人参、大黄","附子、大黄","大黄、芒硝","附子、干姜","人参、芒硝"],"a":1,"e":"温脾汤以附子温补脾阳、大黄泻下冷积，二药温下相配共为君药，佐干姜、人参、当归、芒硝、甘草，攻补兼施。"},{"q":"功用为泻火逐痰的方剂是","o":["滚痰丸","清气化痰丸","贝母瓜蒌散","温胆汤","二陈汤"],"a":0,"e":"滚痰丸以礞石为君，配大黄、黄芩、沉香，泻火逐痰，主治实热老痰之癫狂惊悸、咳喘痰稠。"},{"q":"大承气汤与大柴胡汤共有的药物是","o":["大黄、芍药","枳实、厚朴","柴胡、黄芩","当归、升麻","大黄、枳实"],"a":4,"e":"大承气汤用大黄、芒硝、枳实、厚朴，大柴胡汤用柴胡、黄芩、半夏、芍药、枳实、大黄、姜枣，二方共有大黄、枳实。"},{"q":"参苓白术散中除人参、茯苓、白术、甘草和桔梗外，尚有","o":["黄芪、当归、陈皮、升麻、柴胡","莲子肉、薏苡仁、砂仁、白扁豆、山药","莲子肉、薏苡仁、砂仁、当归、陈皮","黄芪、当归、砂仁、白扁豆、山药","黄芪、当归、陈皮、白扁豆、山药"],"a":1,"e":"参苓白术散在四君子汤基础上加山药、白扁豆、莲子肉、薏苡仁、砂仁、桔梗，益气健脾、渗湿止泻。"},{"q":"羚角钩藤汤证的病机是","o":["温热病邪传入厥阴，肝经热盛，热极动风","温病迁延日久，邪热灼伤真阴","邪热久羁，耗伤阴血，虚风内动","肝肾不足，肝阳偏亢，生风化热","肝肾阴虚，肝阳偏亢，阳亢化风，气血逆乱"],"a":0,"e":"羚角钩藤汤证为温热病邪传入厥阴，肝经热盛、热极动风，症见高热不退、手足抽搐、甚则神昏，脉弦数。"},{"q":"不属于《温病条辨》白虎汤禁忌证的是","o":["脉沉者","不渴者","汗不出者","脉浮弦而细者","伤寒脉浮，发热无汗，其表未解"],"a":4,"e":"《温病条辨》白虎汤四禁为脉浮弦而细、脉沉、不渴、汗不出；表未解而无汗者当先解表之说出于《伤寒论》，不在条辨四禁之列。"},{"q":"小建中汤的药物组成不包括","o":["芍药、桂枝","生姜、大枣","炙甘草","黄芪","饴糖"],"a":3,"e":"小建中汤由桂枝、芍药、甘草、生姜、大枣、饴糖组成，即桂枝汤倍芍药加饴糖；黄芪为黄芪建中汤所加。"},{"q":"四逆散的主治证是","o":["血虚寒厥证","心肾阳衰证","阳郁厥逆证","肝郁克脾证","脾胃气虚证"],"a":2,"e":"四逆散透邪解郁、疏肝理脾，主治阳郁厥逆证，症见手足不温、腹痛、脉弦，其厥由气机不畅、阳气内郁所致。"},{"q":"完带汤主治","o":["白带","青带","黄带","赤带","黑带"],"a":0,"e":"完带汤补脾疏肝、化湿止带，主治脾虚肝郁、湿浊下注之白带，症见带下色白量多、清稀无臭。"},{"q":"四磨汤中槟榔的配伍意义是","o":["补气扶正","降气平喘","行气破滞","调肝顺气","杀虫消积"],"a":2,"e":"四磨汤中槟榔行气破滞，与沉香降气、乌药调肝、人参益气相配，破滞而不伤正，治七情气逆之胸膈烦闷。"},{"q":"症见尿频尿急，溺时涩痛，舌苔黄腻，脉滑数者，治宜","o":["茵陈蒿汤","萆薢分清饮","石韦散","八正散","小蓟饮子"],"a":3,"e":"八正散清热泻火、利水通淋，主治湿热下注膀胱之热淋，症见尿频尿急、溺时涩痛、苔黄腻、脉滑数。"},{"q":"心脾气血两虚证当以何方治之","o":["当归补血汤","四物汤","八珍汤","十全大补汤","归脾汤"],"a":4,"e":"归脾汤益气补血、健脾养心，主治心脾气血两虚证，症见心悸怔忡、健忘失眠、体倦食少、面色萎黄。"},{"q":"保和丸主治","o":["脾虚食积","食积证","湿热食积","酒积伤脾","痢疾，食积"],"a":1,"e":"保和丸消食和胃，主治饮食不节、食积内停之食积证，症见脘腹痞满胀痛、嗳腐吞酸、恶食呕逆。"},{"q":"阳和汤中所用的姜是","o":["生姜","干姜","炮姜","姜炭","煨姜"],"a":3,"e":"阳和汤用姜炭温经散寒，与肉桂、麻黄、鹿角胶相配，温阳补血、散寒通滞，治阳虚寒凝之阴疽。"},{"q":"黄连阿胶汤的功用是","o":["滋阴降火，清热平肝","滋阴降火，交通心肾","滋阴降火，除烦安神","滋阴降火，燥湿除满","滋阴降火，健脾益气"],"a":2,"e":"黄连阿胶汤以黄连、黄芩清心泻火，阿胶、芍药、鸡子黄滋阴养血，功用为滋阴降火、除烦安神，治阴虚火旺之心烦不寐。"},{"q":"阴虚气滞而致脘胁疼痛的代表方剂是","o":["百合固金汤","一贯煎","炙甘草汤","益胃汤","小柴胡汤"],"a":1,"e":"一贯煎以生地、沙参、麦冬、枸杞滋养肝肾之阴，当归养血，川楝子疏肝理气，主治肝肾阴虚、肝气不舒之脘胁疼痛。"},{"q":"三物备急丸的主治是","o":["寒实腹痛","肾虚便秘","气滞腹痛","瘀血腹痛","津枯便秘"],"a":0,"e":"三物备急丸以巴豆、干姜、大黄攻逐寒积，主治寒实冷积内停之腹痛便秘，甚则气急口噤。"},{"q":"主治水热互结之大结胸证的方剂是","o":["大承气汤","大柴胡汤","小承气汤","大陷胸汤","小陷胸汤"],"a":3,"e":"大陷胸汤以大黄、芒硝、甘遂泻热逐水，主治水热互结之大结胸证，症见心下硬满疼痛、拒按、脉沉紧。"},{"q":"竹叶石膏汤中半夏与麦门冬的配伍比例是","o":["2∶1","1∶2","1∶7","1∶5","7∶1"],"a":1,"e":"竹叶石膏汤中麦门冬一升、半夏半升，用量为一比二，半夏降逆和胃，麦冬滋养肺胃之阴，燥润相济。"},{"q":"防风在玉屏风散中的作用是","o":["疏风透疹","祛风散寒","祛风解痉","走表祛风","祛风升阳"],"a":3,"e":"玉屏风散中防风走表祛风，与黄芪固表、白术健脾相配，散中寓收，使固表而不留邪、祛风而不伤正。"},{"q":"泻白散与白虎汤共有的药物是","o":["石膏","粳米","知母","桑白皮","地骨皮"],"a":1,"e":"泻白散用地骨皮、桑白皮、甘草、粳米，白虎汤用石膏、知母、甘草、粳米，二方共有粳米和中护胃。"},{"q":"参苏饮的组成中不含有","o":["生姜","紫菀","干葛","前胡","半夏"],"a":1,"e":"参苏饮由苏叶、葛根、前胡、半夏、茯苓、陈皮、枳壳、桔梗、木香、甘草、人参、姜枣组成，方中不用紫菀。"},{"q":"小陷胸汤、贝母瓜蒌散、清气化痰丸共有的药物是","o":["瓜蒌","黄连","半夏","甘草","细辛"],"a":0,"e":"小陷胸汤用瓜蒌、黄连、半夏，贝母瓜蒌散以瓜蒌配贝母，清气化痰丸用瓜蒌仁，三方共有瓜蒌以清热化痰。"},{"q":"《医宗金鉴》所谓“以大寒之剂，易为清补之方”的方剂是","o":["竹叶石膏汤","清暑益气汤","白虎加人参汤","白虎加桂枝汤","白虎加苍术汤"],"a":0,"e":"竹叶石膏汤由白虎汤去知母，加竹叶、麦冬、半夏、人参而成，清热兼益气养阴，故《医宗金鉴》称其以大寒之剂易为清补之方。"},{"q":"小柴胡汤的功用是","o":["疏肝解郁","清热泻火","和解少阳","平调寒热","解表散寒"],"a":2,"e":"小柴胡汤以柴胡透泄少阳之邪，黄芩清泄少阳之热，佐半夏、生姜和胃降逆，功用为和解少阳，治伤寒少阳证。"},{"q":"不属于清营汤辨证要点的是","o":["身热夜甚","神烦少寐","斑疹隐隐","舌绛而干","舌绛苔白滑"],"a":4,"e":"清营汤证为热入营分，以身热夜甚、神烦少寐、斑疹隐隐、舌绛而干、脉细数为要点；营热灼阴则苔少或无，白滑苔与之不符。"},{"q":"羚角钩藤汤与蒿芩清胆汤共有的组成药物是","o":["桑叶、菊花","黄芩、生地","白芍、半夏","茯苓、枳实","竹茹、甘草"],"a":4,"e":"羚角钩藤汤含竹茹、甘草，蒿芩清胆汤亦用竹茹化痰和胃，并以碧玉散（含甘草）清热解毒，二方共有此二味。"},{"q":"银翘散中辛而微温可助君药开皮毛以解表散邪的配伍是","o":["荆芥穗、豆豉","芦根、竹叶","薄荷、牛蒡子","银花、连翘","牛蒡子、生甘草"],"a":0,"e":"银翘散中荆芥穗、淡豆豉辛而微温，助君药金银花、连翘开皮毛以解表散邪，为辛凉平剂中佐以辛温之配伍。"},{"q":"治疗外感凉燥证的方剂是","o":["杏苏散","桑杏汤","麦门冬汤","清燥救肺汤","三仁汤"],"a":0,"e":"杏苏散轻宣凉燥、理肺化痰，主治外感凉燥证，症见恶寒无汗、咳嗽痰稀、鼻塞咽干、苔白脉弦。"},{"q":"症见咳嗽气喘，痰中带血，咽喉燥痛，头晕目眩，午后潮热，应选用","o":["当归六黄汤","百合固金汤","养阴清肺汤","杏苏散","桑杏汤"],"a":1,"e":"百合固金汤养阴润肺、化痰止咳，主治肺肾阴亏、虚火上炎之咳嗽气喘、痰中带血、咽喉燥痛、头晕目眩、午后潮热。"},{"q":"九味羌活汤为哪位医家所创制","o":["李东垣","王好古","张元素","刘完素","朱丹溪"],"a":2,"e":"九味羌活汤为张元素所制，载于《此事难知》，发汗祛湿、兼清里热，治外感风寒湿邪兼内有蕴热之证。"},{"q":"温胆汤所治证的病机是","o":["火热犯肺，灼津为痰","邪热内盛，痰热结胸","脾湿生痰，风痰上扰","胆胃不和，痰热内扰","胆胃不和，痰浊内扰"],"a":4,"e":"温胆汤证为胆胃不和、痰浊内扰，症见胆怯易惊、虚烦不眠、呕恶呃逆、苔白腻，治以理气化痰、清胆和胃。"},{"q":"定喘汤的组成中不包括","o":["苏子","生姜","半夏","白果","麻黄"],"a":1,"e":"定喘汤由白果、麻黄、苏子、甘草、款冬花、杏仁、桑白皮、黄芩、半夏组成，宣降肺气、清热化痰，方中不用生姜。"},{"q":"下列各项中不属于和法范畴的是","o":["透达膜原","疏肝和胃","分消上下","调和营卫","消食和胃"],"a":4,"e":"和法包括和解少阳、透达膜原、调和营卫、疏肝和胃、分消上下等；消食和胃属消法范畴，为消导食积而设。"},{"q":"升麻葛根汤的功用是","o":["解肌发汗","解肌清热","解肌透疹","疏风止痛","疏风清热"],"a":2,"e":"升麻葛根汤以升麻、葛根解肌清热透疹，芍药、甘草和营解毒，功用为解肌透疹，治麻疹初起疹发不透。"},{"q":"左归丸组成中有","o":["茯苓","牛膝","泽泻","枸杞子","牡丹皮"],"a":3,"e":"左归丸由熟地、山药、山茱萸、枸杞子、菟丝子、鹿角胶、龟板胶、牛膝组成，滋阴补肾、填精益髓。"},{"q":"藿香正气散主治证的病机是","o":["风寒在表，水饮内停","风寒在表，湿滞脾胃","风寒在表，内有蕴热","风热在表，湿滞脾胃","风湿在表，内有蕴热"],"a":1,"e":"藿香正气散解表化湿、理气和中，主治外感风寒、内伤湿滞，病机为风寒在表、湿滞脾胃，症见寒热头痛、胸膈满闷、呕吐泄泻。"},{"q":"六味地黄丸与左归丸的组成中共有药物是","o":["熟地黄","茯苓","泽泻","枸杞子","牛膝"],"a":0,"e":"六味地黄丸用熟地、山茱萸、山药、泽泻、牡丹皮、茯苓，左归丸亦以熟地为君，二方共有熟地黄滋阴补肾。"},{"q":"以下关于小活络丹的药物组成描述错误的是","o":["川乌","乳香","草乌","天南星","地黄"],"a":4,"e":"小活络丹由川乌、草乌、天南星、乳香、没药、地龙组成，祛风除湿、化痰通络、活血止痛，方中不用地黄。"},{"q":"症见小便不利，苔白，脉浮或缓者，治宜","o":["利水渗湿，清热养阴","利水渗湿，温阳化气","利水渗湿，益气健脾","利水渗湿，温补肾阳","利水渗湿，温阳化饮"],"a":1,"e":"五苓散以泽泻、猪苓、茯苓、白术利水渗湿，桂枝温阳化气兼解表，故治水湿内停之小便不利、苔白、脉浮或缓。"},{"q":"养阴清肺汤中少佐薄荷的意义是","o":["疏散肝郁","清利头目","芳香辟秽","散邪利咽","清热透疹"],"a":3,"e":"薄荷辛凉轻清，上行入肺，在养阴清肺汤中少佐之可散邪利咽，透邪外达而不伤阴液，助君臣药清肺解毒。"},{"q":"下列描述苏子降气汤的各项中哪一项是错误的","o":["苏子降气祛痰，止咳平喘","半夏、厚朴、前胡祛痰止咳平喘","肉桂温肾祛寒，纳气平喘","当归补血柔肝","生姜、苏叶宣肺散寒"],"a":3,"e":"苏子降气汤中当归养血润燥，并取“主咳逆上气”之意降逆止咳，与肉桂共温补下元；柔肝之力非其所长，故“补血柔肝”之述有误。"},{"q":"下列哪首方剂不是二陈汤化裁而来","o":["茯苓丸","温胆汤","半夏白术天麻汤","清气化痰丸","涤痰汤"],"a":0,"e":"茯苓丸由半夏、茯苓、枳壳、风化朴硝组成，为痰流四肢之臂痛用方，非二陈汤加减；温胆汤、涤痰汤、半夏白术天麻汤、清气化痰丸皆由二陈汤化裁。"},{"q":"理中丸的功用是","o":["温中补虚、降逆止呕","温中散寒、补气健脾","温中补虚、和里缓急","温经散寒、养血通脉","温中散寒、降逆止呕"],"a":1,"e":"理中丸功能温中散寒、补气健脾，主治中焦虚寒之腹痛吐利；温中补虚、和里缓急乃小建中汤之功，二者不可混同。"},{"q":"峻下逐水法的基础方剂是","o":["禹功散","十枣汤","大陷胸汤","济川煎","黄龙汤"],"a":1,"e":"十枣汤以甘遂、大戟、芫花峻逐水饮，大枣护胃缓毒，为峻下逐水法的基础方，主治悬饮及水肿腹胀属邪实者。"},{"q":"下列哪项不属于理中丸的主治证候","o":["脘腹绵绵作痛","畏寒肢冷","大便溏泻","恶心呕吐","脉弦数"],"a":4,"e":"理中丸证属中焦虚寒，脉当沉细或迟缓无力；脉弦数主肝胆有热，与虚寒病机相悖，故不属其主治证候。"},{"q":"羚角钩藤汤配伍的臣药是","o":["生地、白芍","羚羊角、钩藤","川贝母、淡竹茹","茯神木、生甘草","桑叶、菊花"],"a":4,"e":"羚角钩藤汤以羚羊角、钩藤凉肝息风为君，桑叶、菊花轻清宣散，助君清热平肝，故为臣药；白芍、生地、贝母、竹茹等为佐。"},{"q":"八正散与连朴饮共同的药物是","o":["黄连","甘草","栀子","滑石","木通"],"a":2,"e":"八正散含栀子、木通、滑石、车前子等，连朴饮含栀子、黄连、厚朴、芦根等，两方共有的药物是栀子。"},{"q":"厚朴温中汤主治","o":["脾胃气滞证","寒热互结证","肝郁化火证","寒湿气滞证","气滞寒凝证"],"a":3,"e":"厚朴温中汤温中行气、燥湿除满，主治脾胃寒湿气滞证，见脘腹胀满疼痛、不思饮食、舌苔白腻。"},{"q":"珍珠母丸的病位以（ ）为主","o":["心和脾","肝和肾","心和肝","脾和肝","心和肾"],"a":2,"e":"珍珠母丸主治阴血不足、肝阳偏亢之惊悸不寐，治以重镇安神、平肝潜阳，其病位在心与肝。"},{"q":"以下关于羚角钩藤汤的组成，表述错误的是","o":["桑叶、菊花","浙贝母、茯苓","白芍、甘草","生地、竹茹","羚羊角、钩藤"],"a":1,"e":"羚角钩藤汤用川贝母清热化痰、茯神木平肝安神，方中并无浙贝母与茯苓，一字之差药效有别。"},{"q":"下列选项中，不属于济川煎组成的是","o":["当归","牛膝","泽泻","升麻","白芍"],"a":4,"e":"济川煎由当归、牛膝、肉苁蓉、泽泻、升麻、枳壳组成，温肾益精、润肠通便，方中不含白芍。"},{"q":"血府逐瘀汤主治的病证是","o":["膈下血瘀证","少腹血瘀证","胸中血瘀证","两胁血瘀证","头部血瘀证"],"a":2,"e":"血府逐瘀汤活血化瘀、行气止痛，主治胸中血瘀证，见胸痛日久、痛如针刺而有定处、舌暗红有瘀斑。"},{"q":"真武汤主治","o":["阳虚水泛证","阴水","风水","蓄水证","中阳不足之痰饮"],"a":0,"e":"真武汤温阳利水，主治脾肾阳虚、水湿内停之阳虚水泛证，见小便不利、四肢沉重疼痛、水肿、舌淡胖苔白滑。"},{"q":"朱砂安神丸与酸枣仁汤组成中共有的药是","o":["朱砂","酸枣仁","甘草","川芎","当归"],"a":2,"e":"朱砂安神丸由朱砂、黄连、生地、当归、炙甘草组成，酸枣仁汤由酸枣仁、知母、茯苓、川芎、甘草组成，两方共有甘草。"},{"q":"主治证病机为“外感风寒，气郁不舒”的方剂是","o":["藿香正气散","正柴胡饮","香薷散","葱豉汤","香苏散"],"a":4,"e":"香苏散以紫苏叶、香附、陈皮、炙甘草组方，理气解表，主治外感风寒兼气郁不舒，见恶寒发热、胸脘痞闷。"},{"q":"主治脾不统血证的方剂是","o":["四物汤","当归补血汤","归脾汤","胶艾汤","人参养荣汤"],"a":2,"e":"归脾汤益气补血、健脾养心，脾气健旺则血有所统，故为治脾不统血之便血、崩漏、皮下出血的首选方。"},{"q":"主治元气不升，气阴不足，脾肾两虚之消渴，宜首选的方剂是","o":["玉液汤","增液汤","百合固金汤","麦门冬汤","杏苏散"],"a":0,"e":"玉液汤益气生津、润燥止渴，主治元气不升、气阴不足、脾肾两虚之消渴，见口渴引饮、小便频数量多。"},{"q":"苏子降气汤中当归的功效是","o":["补血活血","调经止痛","润肠通便","降逆下气","温中补虚"],"a":3,"e":"当归辛甘温润，取《本经》“主咳逆上气”之义降逆下气，兼养血润燥，与肉桂同温补下元，助苏子平喘。"},{"q":"阳和汤的组成药物除麻黄、白芥子外其余是","o":["熟地、龟板、胶干姜、肉桂、川芎","熟地、鹿角胶、姜炭、肉桂、甘草","熟地、鹿角霜、炮姜、桂枝、甘草","熟地、鹿角胶、炮姜、细辛、甘草","生地、真阿胶、姜炭、桂枝、细辛"],"a":1,"e":"阳和汤由熟地、鹿角胶、姜炭、肉桂、麻黄、白芥子、生甘草组成，温阳补血、散寒通滞。"},{"q":"苓桂术甘汤主治","o":["蓄水证","水热互结阴伤证","肾著病","中阳不足之痰饮","阳虚水泛证"],"a":3,"e":"苓桂术甘汤温阳化饮、健脾利湿，主治中阳不足、痰饮内停之胸胁支满、目眩心悸、舌苔白滑。"},{"q":"以下关于《温病条辨》之加减复脉汤的组成表述错误的是","o":["炙甘草","熟地黄","阿胶","生白芍","麦冬"],"a":1,"e":"加减复脉汤由炙甘草、干地黄、生白芍、麦冬、阿胶、麻仁组成，用干地黄而非熟地黄，功在滋阴复脉。"},{"q":"温燥伤肺，气阴两伤证，治宜选用","o":["麦门冬汤","桑杏汤","杏苏散","清燥救肺汤","沙参麦冬汤"],"a":3,"e":"清燥救肺汤清燥润肺、益气养阴，主治温燥伤肺、气阴两伤证，见身热头痛、干咳无痰、气逆而喘。"},{"q":"由龟板、熟地黄、知母、黄柏、猪脊髓组成的方剂是","o":["左归丸","六味地黄丸","大补阴丸","知柏地黄丸","缩泉丸"],"a":2,"e":"大补阴丸由熟地黄、龟板、黄柏、知母、猪脊髓组成，滋阴降火，主治阴虚火旺之骨蒸潮热、盗汗遗精。"},{"q":"六味地黄丸和大补阴丸两方组成中均不含有的药物是","o":["泽泻、茯苓","知母、黄柏","生地黄、怀牛膝","牡丹皮、山茱萸","炙龟板、熟地黄"],"a":2,"e":"六味地黄丸用熟地、山萸肉、山药、泽泻、丹皮、茯苓；大补阴丸用熟地、龟板、黄柏、知母、猪脊髓，两方均不含生地黄与怀牛膝。"},{"q":"症见大便秘结，口渴，舌干红，脉沉无力，宜首选的方剂是","o":["玉液汤","增液汤","调胃承气汤","玉女煎","麻子仁丸"],"a":1,"e":"增液汤以玄参、麦冬、生地滋阴润燥、增水行舟，主治阳明温病津亏便秘，见大便秘结、口渴、舌干红、脉沉无力。"},{"q":"用治血热妄行之上部出血证的方剂是","o":["十灰散","六一散","归脾汤","理中丸","芍药汤"],"a":0,"e":"十灰散凉血止血，主治血热妄行之上部出血，如吐血、咯血、衄血；诸药烧灰存性，以增强收涩止血之力。"},{"q":"黄土汤中附子配白术的意义是","o":["温中止泻","回阳救逆","温阳健脾","温阳利水","温经散寒"],"a":2,"e":"黄土汤中附子、白术温阳健脾，恢复脾之统血之职，以治脾阳不足、统摄无权之便血崩漏，非为回阳救逆。"},{"q":"桂枝茯苓丸的主治证是","o":["瘀阻胞宫证","下焦蓄血证","中风后遗证","瘀滞脉络证","产后血虚寒凝证"],"a":0,"e":"桂枝茯苓丸活血化瘀、缓消癥块，主治瘀阻胞宫证，见妇人素有癥块、妊娠漏下不止、腹痛拒按。"},{"q":"清气化痰丸主治何种咳嗽","o":["湿痰","热痰","燥痰","风痰","顽痰"],"a":1,"e":"清气化痰丸清热化痰、理气止咳，主治痰热咳嗽，见咳嗽痰黄黏稠、胸膈痞满、舌红苔黄腻。"},{"q":"清燥救肺汤与养阴清肺汤共有的药物是","o":["杏仁、枇杷叶","沙参、麦冬","麦冬、甘草","白芍、贝母","杏仁、甘草"],"a":2,"e":"清燥救肺汤含麦冬、甘草；养阴清肺汤含麦冬、甘草及生地、玄参、白芍、丹皮、贝母、薄荷，两方共有的药物为麦冬与甘草。"},{"q":"五积散的“五积”是","o":["风、寒、暑、湿、火","热、痰、气、血、湿","气、血、食、火、痰","寒、湿、气、血、痰","火、痰、热、湿、食"],"a":3,"e":"五积散集麻黄、肉桂、苍术、厚朴、陈皮、当归、川芎等药，散寒祛湿、理气活血化痰，所治五积即寒、湿、气、血、痰。"},{"q":"具有益气健脾，养血安胎之功的方剂是","o":["归脾汤","泰山磐石散","补中益气汤","八珍汤","保产无忧散"],"a":1,"e":"泰山磐石散益气健脾、养血安胎，主治气血虚弱、胎元不固之胎动不安及屡有堕胎者，方以八珍汤加减而成。"},{"q":"一贯煎与益胃汤共有的药物是","o":["沙参、玉竹","麦门冬、冰糖","沙参、麦门冬、生地黄","生地黄、玉竹","生地黄、玉竹、川楝子"],"a":2,"e":"一贯煎用北沙参、麦冬、生地、当归、枸杞子、川楝子；益胃汤用沙参、麦冬、生地、玉竹、冰糖，共有沙参、麦门冬、生地黄。"},{"q":"当归补血汤中当归与黄芪的配伍用量比例是","o":["1∶1","1∶2","1∶5","2∶1","5∶1"],"a":2,"e":"当归补血汤重用黄芪一两为君、当归二钱为辅，二药用量之比为一比五，取有形之血生于无形之气之意。"},{"q":"藿香正气散的功用是","o":["芳香化湿，理气和中","解表化湿，理气和中","解表化湿，升清降浊","解表散寒，升清降浊","解表散寒，祛湿化浊"],"a":1,"e":"藿香正气散解表化湿、理气和中，主治外感风寒、内伤湿滞之恶寒发热、脘腹胀痛、呕吐泄泻。"},{"q":"小承气是大承气汤减去哪味药物而成","o":["大黄","芒硝","枳实","厚朴","甘草"],"a":1,"e":"小承气汤即大承气汤去芒硝，由大黄、枳实、厚朴组成，轻下热结，主治痞满实而不燥之阳明腑实轻证。"},{"q":"芍药汤的功用","o":["清热解毒，凉血止痢","清热燥湿，行气化滞","清热燥湿，调气和血","清热止利，和中止痛","温中补虚，涩肠止泻"],"a":2,"e":"芍药汤清热燥湿、调气和血，主治湿热痢疾，见下痢赤白相兼、腹痛里急后重、肛门灼热、小便短赤。"},{"q":"炙甘草汤的脉象特点是","o":["脉细数","脉沉迟","脉浮数","脉结代","脉弦数"],"a":3,"e":"炙甘草汤益气滋阴、通阳复脉，主治阴血阳气俱虚、心脉失养之脉结代、心动悸，方中重用炙甘草为君。"},{"q":"黄连配伍肉桂，使心火得降，肾阳得复，肾水上承，心肾相交，《韩氏医通》赞其“能使心肾交与顷刻”。此方剂为","o":["天王补心丹","黄连阿胶汤","朱砂安神丸","桂枝甘草龙骨牡蛎汤","交泰丸"],"a":4,"e":"交泰丸以黄连清心降火、肉桂引火归元，二药相配使心肾相交，方出《韩氏医通》，专治心肾不交之失眠。"},{"q":"济川煎的主治证是","o":["脾约便秘","津枯便秘","肾虚便秘","阳虚便秘","热结便秘"],"a":2,"e":"济川煎温肾益精、润肠通便，主治肾虚便秘，见大便秘结、小便清长、腰膝酸软、舌淡苔白、脉沉迟。"},{"q":"下列药物不是玉女煎组成的是","o":["牛膝","石膏","知母","升麻","麦门冬"],"a":3,"e":"玉女煎由石膏、熟地、麦冬、知母、牛膝组成，清胃热、滋肾阴；升麻为清胃散之药，非本方所有。"},{"q":"四逆汤的组成是","o":["附子、人参、干姜","人参、干姜、甘草","人参、附子、甘草","附子、干姜、甘草","附子、干姜、葱白"],"a":3,"e":"四逆汤由生附子、干姜、炙甘草组成，回阳救逆，主治心肾阳衰之四肢厥逆、恶寒蜷卧、脉微欲绝。"},{"q":"败毒散的功用是","o":["发汗解表，散风祛湿","助阳益气，解表散寒","益气解表，理气化痰","散寒祛湿，益气解表","清热解毒，祛风除湿"],"a":3,"e":"败毒散以羌活、独活、川芎、柴胡等散寒祛湿，配人参益气扶正，功能散寒祛湿、益气解表，主治气虚外感风寒湿证。"},{"q":"酸枣仁汤中用量最少的药物是","o":["酸枣仁","茯苓","川芎","知母","甘草"],"a":4,"e":"酸枣仁汤中酸枣仁用二升为君，茯苓、知母、川芎各二两，甘草仅一两，用量最轻，取其调和诸药。"}];
